export default "n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/_upgrade_commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f71e0f71d63b20e6709e8d7689b46e62a969498d6289ef6d96f9d2e7ee0e9458\",\"content\":\"\\\"\\\"\\\"Upgrade commands: upgrade.\\\"\\\"\\\"\\n\\nimport typer\\n\\n\\ndef register(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Register upgrade commands on *app*.\\\"\\\"\\\"\\n\\n    @app.command(\\n        name=\\\"upgrade\\\",\\n        help=\\\"Check (and optionally upgrade) a flow's component compatibility\\\",\\n        no_args_is_help=True,\\n        rich_help_panel=\\\"Authoring\\\",\\n    )\\n    def upgrade_command_wrapper(\\n        flow_path: str = typer.Argument(help=\\\"Path to the flow JSON file to check\\\"),\\n        *,\\n        write: bool = typer.Option(\\n            False,  # noqa: FBT003\\n            \\\"--write\\\",\\n            \\\"-w\\\",\\n            help=\\\"Apply safe upgrades and write the updated flow back to the file.\\\",\\n        ),\\n        strict: bool = typer.Option(\\n            False,  # noqa: FBT003\\n            \\\"--strict\\\",\\n            help=(\\n                \\\"Exit non-zero if any component is not up to date. Without --strict, pending \\\"\\n                \\\"safe upgrades exit 0 (only breaking/blocked components fail the command).\\\"\\n            ),\\n        ),\\n    ) -> None:\\n        \\\"\\\"\\\"Check component compatibility and optionally apply safe upgrades (lazy-loaded).\\\"\\\"\\\"\\n        from pathlib import Path\\n\\n        from lfx.cli.upgrade import upgrade_command\\n\\n        upgrade_command(Path(flow_path), write=write, strict=strict)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/command_plugins.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f6bccc61527d032d1de7ed11c41b4b420db7b2f3fec24f12a09773571a99e13\",\"content\":\"\\\"\\\"\\\"Discovery and registration for third-party CLI commands.\\n\\nPackages can extend the ``langflow`` root CLI by exposing a registration\\ncallable through the ``langflow.cli_commands`` entry-point group::\\n\\n    [project.entry-points.\\\"langflow.cli_commands\\\"]\\n    example = \\\"example_package.cli:register\\\"\\n\\nThe callable receives the root :class:`typer.Typer` application and registers\\none or more commands on it.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections import Counter\\nfrom collections.abc import Callable\\nfrom importlib import metadata\\nfrom typing import TypeAlias\\n\\nimport typer\\nfrom typer.main import get_command_name, solve_typer_info_defaults\\n\\nCLI_COMMAND_ENTRY_POINT_GROUP = \\\"langflow.cli_commands\\\"\\n\\nCLICommandRegister: TypeAlias = Callable[[typer.Typer], None]\\n\\n\\nclass CLICommandPluginError(RuntimeError):\\n    \\\"\\\"\\\"Raised when installed CLI command plugins cannot be registered safely.\\\"\\\"\\\"\\n\\n\\ndef _plugin_label(entry_point: metadata.EntryPoint) -> str:\\n    return f\\\"{entry_point.name!r} ({entry_point.value})\\\"\\n\\n\\ndef _load_plugins() -> list[tuple[metadata.EntryPoint, CLICommandRegister]]:\\n    try:\\n        entry_points = sorted(\\n            metadata.entry_points(group=CLI_COMMAND_ENTRY_POINT_GROUP),\\n            key=lambda entry_point: (entry_point.name, entry_point.value),\\n        )\\n    except Exception as exc:\\n        msg = f\\\"Failed to discover CLI command plugins from {CLI_COMMAND_ENTRY_POINT_GROUP!r}.\\\"\\n        raise CLICommandPluginError(msg) from exc\\n\\n    loaded_plugins: list[tuple[metadata.EntryPoint, CLICommandRegister]] = []\\n    for entry_point in entry_points:\\n        try:\\n            register = entry_point.load()\\n        except Exception as exc:\\n            msg = f\\\"Failed to load CLI command plugin {_plugin_label(entry_point)}.\\\"\\n            raise CLICommandPluginError(msg) from exc\\n\\n        if not callable(register):\\n            msg = f\\\"CLI command plugin {_plugin_label(entry_point)} is not callable.\\\"\\n            raise CLICommandPluginError(msg)\\n\\n        loaded_plugins.append((entry_point, register))\\n\\n    return loaded_plugins\\n\\n\\ndef _top_level_command_names(app: typer.Typer) -> list[str]:\\n    \\\"\\\"\\\"Return command and named-group names as Typer exposes them at this level.\\\"\\\"\\\"\\n    names = [\\n        command_info.name or get_command_name(command_info.callback.__name__)\\n        for command_info in app.registered_commands\\n        if command_info.callback is not None\\n    ]\\n    for group_info in app.registered_groups:\\n        solved_group_info = solve_typer_info_defaults(group_info)\\n        if solved_group_info.name:\\n            names.append(solved_group_info.name)\\n        elif group_info.typer_instance is not None:\\n            names.extend(_top_level_command_names(group_info.typer_instance))\\n    return names\\n\\n\\ndef _restore_app(\\n    app: typer.Typer,\\n    commands: list[typer.models.CommandInfo],\\n    groups: list[typer.models.TyperInfo],\\n    callback: typer.models.TyperInfo | None,\\n) -> None:\\n    app.registered_commands[:] = commands\\n    app.registered_groups[:] = groups\\n    app.registered_callback = callback\\n\\n\\ndef register_cli_command_plugins(app: typer.Typer) -> None:\\n    \\\"\\\"\\\"Discover installed command plugins and register them on ``app``.\\n\\n    Loading and validation finish before the app is mutated. Registration is\\n    transactional for Typer's command, group, and callback registries so a\\n    broken plugin cannot leave a partially configured CLI behind.\\n    \\\"\\\"\\\"\\n    loaded_plugins = _load_plugins()\\n    original_commands = list(app.registered_commands)\\n    original_groups = list(app.registered_groups)\\n    original_callback = app.registered_callback\\n    registered_names = Counter(_top_level_command_names(app))\\n    registered_callback = original_callback\\n\\n    for entry_point, register in loaded_plugins:\\n        try:\\n            register(app)\\n            current_names = Counter(_top_level_command_names(app))\\n        except Exception as exc:\\n            _restore_app(app, original_commands, original_groups, original_callback)\\n            msg = f\\\"Failed to register CLI command plugin {_plugin_label(entry_point)}.\\\"\\n            raise CLICommandPluginError(msg) from exc\\n\\n        collisions = sorted(\\n            name for name, count in current_names.items() if count > 1 and count > registered_names.get(name, 0)\\n        )\\n        if collisions:\\n            _restore_app(app, original_commands, original_groups, original_callback)\\n            names = \\\", \\\".join(repr(name) for name in collisions)\\n            msg = (\\n                f\\\"CLI command plugin {_plugin_label(entry_point)} attempted to register command or group name \\\"\\n                f\\\"{names}, which is already registered.\\\"\\n            )\\n            raise CLICommandPluginError(msg)\\n\\n        if registered_callback is not None and app.registered_callback is not registered_callback:\\n            _restore_app(app, original_commands, original_groups, original_callback)\\n            msg = (\\n                f\\\"CLI command plugin {_plugin_label(entry_point)} attempted to replace a callback \\\"\\n                \\\"that is already registered.\\\"\\n            )\\n            raise CLICommandPluginError(msg)\\n\\n        registered_names = current_names\\n        registered_callback = app.registered_callback\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/commands.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"94ad7a822e7f6038470d26200f0cae076a2d74625187a29da4cf48750a0b963d\",\"content\":\"\\\"\\\"\\\"CLI commands for LFX.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nimport os\\nimport sys\\nimport tempfile\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport typer\\nimport uvicorn\\nfrom dotenv import load_dotenv\\nfrom rich.console import Console\\nfrom rich.panel import Panel\\n\\nfrom lfx.cli import _serve_help\\nfrom lfx.cli.common import (\\n    create_verbose_printer,\\n    flow_id_from_path,\\n    get_api_key,\\n    get_best_access_host,\\n    get_free_port,\\n    is_port_in_use,\\n)\\nfrom lfx.cli.script_loader import find_graph_variable, load_graph_from_script\\nfrom lfx.cli.serve_app import (\\n    FlowAlreadyRegisteredError,\\n    FlowMeta,\\n    FlowRegistry,\\n    create_multi_serve_app,\\n)\\nfrom lfx.load import load_flow_from_json\\nfrom lfx.utils.flow_envelope import merge_flow_envelope, split_flow_envelope\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable\\n\\n    from lfx.cli.flow_store import FlowStore\\n    from lfx.cli.serve_identity import IdentityConfig\\n\\n# Initialize console\\nconsole = Console()\\n\\n# Constants\\nAPI_KEY_MASK_LENGTH = 8\\n\\n# Default gunicorn worker recycling (multi-worker, Unix). When --max-requests is unset we\\n# still recycle every ~this-many requests so long-lived workers shed accumulated memory /\\n# per-worker caches; jitter (10%) staggers workers so they don't all recycle on the same\\n# request count. Explicit --max-requests 0 disables recycling; explicit N overrides this.\\nDEFAULT_MAX_REQUESTS = 1000\\n# Default gunicorn worker timeout (seconds) for multi-worker serving. gunicorn's own\\n# default is 30s, which would kill long LLM flows. None (omitted --timeout) maps to this.\\nDEFAULT_TIMEOUT = 120\\n\\n\\ndef _gate_flow_for_serve(\\n    payload: dict,\\n    upgrade_flow: str,\\n    *,\\n    verbose: bool,\\n) -> dict:\\n    \\\"\\\"\\\"Run the shared ``--upgrade-flow`` gate on a parsed flow payload.\\n\\n    Splits any outer ``{\\\"data\\\": ...}`` envelope, runs ``apply_upgrade_gate`` on the inner\\n    graph (the same gate ``lfx run`` uses), then re-attaches the envelope so the result is\\n    loader-ready \u2014 ``aload_flow_from_json`` requires the ``{\\\"data\\\": ...}`` wrapper.\\n\\n    Raises:\\n        typer.Exit: if the payload is not a JSON object, or the gate aborts (incompatible in\\n            ``check`` mode, or blocked/breaking in ``safe`` mode).\\n    \\\"\\\"\\\"\\n    from lfx.upgrade.cli_gate import UpgradeFlowError, apply_upgrade_gate\\n\\n    try:\\n        outer_envelope, inner = split_flow_envelope(payload)\\n    except TypeError as e:\\n        typer.echo(f\\\"Error: {e}\\\", err=True)\\n        raise typer.Exit(1) from e\\n    try:\\n        inner, applied = apply_upgrade_gate(inner, mode=upgrade_flow)\\n    except UpgradeFlowError as e:\\n        typer.echo(f\\\"Error: {e}\\\", err=True)\\n        raise typer.Exit(1) from e\\n    if applied and verbose:\\n        typer.echo(f\\\"Applied {applied} safe component upgrade(s).\\\")\\n    return merge_flow_envelope(outer_envelope, inner, wrap_bare=True)\\n\\n\\nasync def _registry_from_temp_flow_json(\\n    json_data: Any,\\n    *,\\n    verbose_print: Callable[[str], None],\\n    check_variables: bool,\\n    no_env_fallback: bool,\\n    flow_store: FlowStore,\\n) -> tuple[FlowRegistry, str]:\\n    \\\"\\\"\\\"Build a registry from *json_data* staged in a temporary ``.json`` file.\\n\\n    Returns ``(registry, temp_path)``. Ownership of the temp file passes to the caller\\n    only on a clean return; every other exit unlinks it here \u2014 the ``typer.Exit`` raised\\n    for a load error, a Ctrl-C or cancellation mid-load, an unexpected loader failure \u2014\\n    because the caller never receives a path for its own ``finally`` to clean up.\\n    \\\"\\\"\\\"\\n    fd, temp_path = tempfile.mkstemp(suffix=\\\".json\\\")\\n    registry: FlowRegistry | None = None\\n    try:\\n        with os.fdopen(fd, \\\"w\\\") as tmp:\\n            json.dump(json_data, tmp, indent=2)\\n        registry = await build_registry_from_paths(\\n            [Path(temp_path)],\\n            verbose_print,\\n            check_variables=check_variables,\\n            no_env_fallback=no_env_fallback,\\n            store=flow_store,\\n        )\\n    except ValueError as e:\\n        typer.echo(f\\\"Error: {e}\\\", err=True)\\n        raise typer.Exit(1) from e\\n    finally:\\n        if registry is None:\\n            with contextlib.suppress(OSError):\\n                Path(temp_path).unlink()\\n    return registry, temp_path\\n\\n\\nasync def _build_serve_registry(\\n    *,\\n    script_paths: list[str] | None,\\n    flow_json: str | None,\\n    stdin: bool,\\n    check_variables: bool,\\n    no_env_fallback: bool,\\n    flow_store: FlowStore,\\n    verbose_print: Callable[[str], None],\\n    upgrade_flow: str | None = None,\\n    verbose: bool = False,\\n) -> tuple[FlowRegistry, str | None]:\\n    \\\"\\\"\\\"Build the FlowRegistry from startup inputs.\\n\\n    Returns (registry, temp_file_path_or_None). Caller must unlink the temp\\n    file if not None.\\n\\n    When ``upgrade_flow`` is set, the flow is run through the shared ``--upgrade-flow`` gate\\n    before the registry is built. This is supported for inline JSON, stdin, and a single\\n    ``.json`` file path; directories, multiple paths, and ``.py`` scripts are rejected.\\n    \\\"\\\"\\\"\\n    temp_file_to_cleanup: str | None = None\\n\\n    if flow_json is not None or stdin:\\n        if flow_json is not None:\\n            try:\\n                json_data = json.loads(flow_json)\\n            except json.JSONDecodeError as e:\\n                typer.echo(f\\\"Error: Invalid JSON content: {e}\\\", err=True)\\n                raise typer.Exit(1) from e\\n        else:\\n            stdin_content = sys.stdin.read().strip()\\n            if not stdin_content:\\n                typer.echo(\\\"Error: No content received from stdin\\\", err=True)\\n                raise typer.Exit(1)\\n            try:\\n                json_data = json.loads(stdin_content)\\n            except json.JSONDecodeError as e:\\n                typer.echo(f\\\"Error: Invalid JSON content from stdin: {e}\\\", err=True)\\n                raise typer.Exit(1) from e\\n        if upgrade_flow:\\n            json_data = _gate_flow_for_serve(json_data, upgrade_flow, verbose=verbose)\\n        registry, temp_file_to_cleanup = await _registry_from_temp_flow_json(\\n            json_data,\\n            verbose_print=verbose_print,\\n            check_variables=check_variables,\\n            no_env_fallback=no_env_fallback,\\n            flow_store=flow_store,\\n        )\\n\\n    elif script_paths:\\n        resolved = [Path(p).resolve() for p in script_paths]\\n        missing = [p for p in resolved if not p.exists()]\\n        if missing:\\n            for m in missing:\\n                typer.echo(f\\\"Error: Path '{m}' does not exist.\\\", err=True)\\n            raise typer.Exit(1)\\n\\n        if upgrade_flow:\\n            # --upgrade-flow with a path supports exactly one .json flow file: directories,\\n            # multiple files, and .py scripts can't be safely upgraded in place here.\\n            if len(resolved) != 1 or resolved[0].is_dir() or resolved[0].suffix.lower() != \\\".json\\\":\\n                typer.echo(\\n                    \\\"Error: --upgrade-flow with a path supports exactly one .json flow file \\\"\\n                    \\\"(not directories, multiple files, or .py scripts).\\\",\\n                    err=True,\\n                )\\n                raise typer.Exit(1)\\n            try:\\n                payload = json.loads(resolved[0].read_text(encoding=\\\"utf-8\\\"))\\n            except (json.JSONDecodeError, OSError) as e:\\n                typer.echo(\\n                    f\\\"Error: --upgrade-flow: could not read flow file '{resolved[0]}': {e}\\\",\\n                    err=True,\\n                )\\n                raise typer.Exit(1) from e\\n            gated = _gate_flow_for_serve(payload, upgrade_flow, verbose=verbose)\\n            registry, temp_file_to_cleanup = await _registry_from_temp_flow_json(\\n                gated,\\n                verbose_print=verbose_print,\\n                check_variables=check_variables,\\n                no_env_fallback=no_env_fallback,\\n                flow_store=flow_store,\\n            )\\n\\n        elif len(resolved) == 1 and resolved[0].is_dir():\\n            dir_path = resolved[0]\\n            try:\\n                registry = await build_registry_from_directory(\\n                    dir_path,\\n                    verbose_print,\\n                    check_variables=check_variables,\\n                    no_env_fallback=no_env_fallback,\\n                    store=flow_store,\\n                )\\n            except ValueError as e:\\n                typer.echo(f\\\"Error: {e}\\\", err=True)\\n                raise typer.Exit(1) from e\\n            verbose_print(f\\\"Loaded {len(registry)} flow(s) from directory {dir_path}\\\")\\n        else:\\n            non_supported = [p for p in resolved if p.suffix not in {\\\".json\\\", \\\".py\\\"}]\\n            if non_supported:\\n                for p in non_supported:\\n                    typer.echo(f\\\"Error: '{p}' must be a .json or .py file.\\\", err=True)\\n                raise typer.Exit(1)\\n            try:\\n                registry = await build_registry_from_paths(\\n                    resolved,\\n                    verbose_print,\\n                    check_variables=check_variables,\\n                    no_env_fallback=no_env_fallback,\\n                    store=flow_store,\\n                )\\n            except ValueError as e:\\n                typer.echo(f\\\"Error: {e}\\\", err=True)\\n                raise typer.Exit(1) from e\\n\\n    else:\\n        if upgrade_flow:\\n            typer.echo(\\n                \\\"Error: --upgrade-flow requires a JSON flow source (--flow-json, --stdin, or a .json file path).\\\",\\n                err=True,\\n            )\\n            raise typer.Exit(1)\\n        registry = FlowRegistry(no_env_fallback=no_env_fallback, store=flow_store)\\n        verbose_print(\\\"Starting with empty registry \u2014 flows can be uploaded at runtime\\\")\\n\\n    return registry, temp_file_to_cleanup\\n\\n\\ndef serve_command(\\n    script_paths: list[str] | None = typer.Argument(\\n        default=None,\\n        help=(\\n            \\\"Path(s) to JSON flow file(s) (.json), Python script(s) (.py), or a directory \\\"\\n            \\\"containing .json files (top-level only, non-recursive). \\\"\\n            \\\"Optional when using --flow-json or --stdin.\\\"\\n        ),\\n    ),\\n    host: str = typer.Option(\\\"127.0.0.1\\\", \\\"--host\\\", \\\"-h\\\", help=\\\"Host to bind the server to\\\"),\\n    port: int = typer.Option(8000, \\\"--port\\\", \\\"-p\\\", help=\\\"Port to bind the server to\\\"),\\n    workers: int = typer.Option(\\n        1,\\n        \\\"--workers\\\",\\n        \\\"-w\\\",\\n        help=\\\"Number of worker processes (gunicorn on Unix, uvicorn on Windows). \\\"\\n        \\\"Use with --flow-dir for multi-worker flow sharing.\\\",\\n    ),\\n    verbose: bool = typer.Option(  # noqa: FBT001\\n        False,  # noqa: FBT003\\n        \\\"--verbose\\\",\\n        \\\"-v\\\",\\n        help=\\\"Show diagnostic output and execution details\\\",\\n    ),\\n    env_file: Path | None = typer.Option(\\n        None,\\n        \\\"--env-file\\\",\\n        help=\\\"Path to the .env file containing environment variables\\\",\\n    ),\\n    log_level: str = typer.Option(\\n        \\\"warning\\\",\\n        \\\"--log-level\\\",\\n        help=\\\"Logging level. One of: debug, info, warning, error, critical\\\",\\n    ),\\n    flow_json: str | None = typer.Option(\\n        None,\\n        \\\"--flow-json\\\",\\n        help=\\\"Inline JSON flow content as a string (alternative to script_paths)\\\",\\n    ),\\n    flow_dir: Path | None = typer.Option(\\n        None,\\n        \\\"--flow-dir\\\",\\n        help=_serve_help.FLOW_DIR,\\n    ),\\n    max_requests: int | None = typer.Option(\\n        None,\\n        \\\"--max-requests\\\",\\n        help=_serve_help.MAX_REQUESTS,\\n    ),\\n    timeout: int | None = typer.Option(\\n        None,\\n        \\\"--timeout\\\",\\n        help=_serve_help.TIMEOUT,\\n    ),\\n    *,\\n    stdin: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"--stdin\\\",\\n        help=\\\"Read JSON flow content from stdin (alternative to script_paths)\\\",\\n    ),\\n    check_variables: bool = typer.Option(\\n        True,  # noqa: FBT003\\n        \\\"--check-variables/--no-check-variables\\\",\\n        help=\\\"Check global variables for environment compatibility\\\",\\n    ),\\n    no_env_fallback: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"--no-env-fallback/--env-fallback\\\",\\n        help=_serve_help.NO_ENV_FALLBACK,\\n    ),\\n    reset_environ: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"--reset-environ/--no-reset-environ\\\",\\n        help=_serve_help.RESET_ENVIRON,\\n    ),\\n    sync_workers: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"--use-sync-workers/--use-async-workers\\\",\\n        help=_serve_help.SYNC_WORKERS,\\n    ),\\n    # Plain defaults (not typer.Option): the CLI options live on serve_command_wrapper,\\n    # which passes these through. Plain defaults keep clean values even if a direct\\n    # caller omits them \u2014 a typer.Option default would leak an OptionInfo object\\n    # (e.g. mode would arrive as <typer.models.OptionInfo>, not \\\"off\\\").\\n    identity_mode: str = \\\"off\\\",\\n    identity_jwt_issuer: str | None = None,\\n    identity_jwt_audience: str | None = None,\\n    identity_jwt_jwks_url: str | None = None,\\n    identity_claim: str = \\\"sub\\\",\\n    identity_jwt_header: str = \\\"Authorization\\\",\\n    identity_header: str = \\\"X-Consumer-Username\\\",\\n    identity_jwt_allow_insecure_http: bool = False,\\n    upgrade_flow: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Serve LFX flows as a web API.\\n\\n    Supports single files, inline JSON, stdin, multiple explicit files,\\n    and a directory of JSON flows.\\n    \\\"\\\"\\\"\\n    from lfx.log.logger import configure\\n\\n    configure(log_level=log_level)\\n    verbose_print = create_verbose_printer(verbose=verbose)\\n\\n    # Validate at most one input source\\n    has_paths = bool(script_paths)\\n    input_sources = [has_paths, flow_json is not None, stdin]\\n    if sum(input_sources) > 1:\\n        typer.echo(\\n            \\\"Error: Cannot combine path(s), --flow-json, and --stdin. Choose exactly one.\\\",\\n            err=True,\\n        )\\n        raise typer.Exit(1)\\n\\n    if env_file:\\n        if not env_file.exists():\\n            typer.echo(f\\\"Error: Environment file '{env_file}' does not exist.\\\", err=True)\\n            raise typer.Exit(1)\\n        verbose_print(f\\\"Loading environment variables from: {env_file}\\\")\\n        load_dotenv(env_file, override=True)\\n\\n    try:\\n        api_key = get_api_key()\\n        verbose_print(\\\"LANGFLOW_API_KEY is configured\\\")\\n    except ValueError as e:\\n        typer.echo(str(e), err=True)\\n        typer.echo(\\\"Set the LANGFLOW_API_KEY environment variable before serving.\\\", err=True)\\n        raise typer.Exit(1) from e\\n\\n    valid_log_levels = {\\\"debug\\\", \\\"info\\\", \\\"warning\\\", \\\"error\\\", \\\"critical\\\"}\\n    if log_level.lower() not in valid_log_levels:\\n        typer.echo(\\n            f\\\"Error: Invalid log level '{log_level}'. Must be one of: {', '.join(sorted(valid_log_levels))}\\\",\\n            err=True,\\n        )\\n        raise typer.Exit(1)\\n\\n    if workers < 1:\\n        typer.echo(\\\"Error: --workers must be at least 1.\\\", err=True)\\n        raise typer.Exit(1)\\n\\n    # When serve_command is invoked directly (not via the typer CLI), an omitted option arrives\\n    # as a typer OptionInfo sentinel rather than its real default. Normalize up front so the\\n    # gunicorn math, the single-worker warning, and the worker env see clean values \u2014 an\\n    # un-normalized OptionInfo is truthy, which would silently flip the bool flags on.\\n    if not isinstance(max_requests, int):\\n        max_requests = None\\n    if not isinstance(timeout, int):\\n        timeout = None\\n    if not isinstance(reset_environ, bool):\\n        reset_environ = False\\n    if not isinstance(sync_workers, bool):\\n        sync_workers = False\\n\\n    from lfx.cli.serve_identity import IdentityConfig, IdentityConfigError\\n\\n    try:\\n        identity_config = IdentityConfig(\\n            mode=identity_mode,  # type: ignore[arg-type]\\n            jwt_issuer=identity_jwt_issuer,\\n            jwt_audience=identity_jwt_audience,\\n            jwt_jwks_url=identity_jwt_jwks_url,\\n            claim=identity_claim,\\n            jwt_header=identity_jwt_header,\\n            trusted_header=identity_header,\\n            allow_insecure_http=identity_jwt_allow_insecure_http,\\n        )\\n    except IdentityConfigError as e:\\n        typer.echo(f\\\"Error: {e}\\\", err=True)\\n        raise typer.Exit(1) from e\\n\\n    os.environ[\\\"LANGFLOW_PRETTY_LOGS\\\"] = \\\"false\\\"\\n    configure(log_level=log_level)\\n\\n    from lfx.cli.flow_store import FilesystemFlowStore, NullFlowStore\\n\\n    flow_store = FilesystemFlowStore(flow_dir) if flow_dir else NullFlowStore()\\n\\n    if workers > 1 and flow_dir is None:\\n        typer.echo(\\n            \\\"Warning: --workers > 1 without --flow-dir means each worker has an isolated \\\"\\n            \\\"in-memory registry. Flows uploaded to one worker will not be visible to others \\\"\\n            \\\"(and with --max-requests recycling, uploaded flows do not survive worker recycling \\\"\\n            \\\"at all). Pass --flow-dir to enable shared flow storage across workers.\\\",\\n            err=True,\\n        )\\n\\n    # Strict per-request isolation comes from --reset-environ (any platform) or from\\n    # --use-sync-workers with --max-requests 1 (fresh process per request). Without one of\\n    # those, warm workers reuse a single os.environ across requests, so a component that does\\n    # os.environ[name] = value leaks to later requests on the same worker.\\n    if workers > 1 and not reset_environ and not (sync_workers and max_requests == 1):\\n        typer.echo(\\n            \\\"Warning: --workers > 1 without --reset-environ (or --use-sync-workers with \\\"\\n            \\\"--max-requests 1) provides NO per-request isolation. Warm workers share one \\\"\\n            \\\"os.environ across many requests, so a flow's environment mutations or \\\"\\n            \\\"request-scoped credentials can leak into later requests on the same worker. \\\"\\n            \\\"Add --reset-environ for cross-request isolation.\\\",\\n            err=True,\\n        )\\n\\n    if workers > 1 and flow_dir is not None and script_paths:\\n        # With --flow-dir, workers skip LFX_SERVE_STARTUP_PATHS and rely on warm_from_store().\\n        # .py files produce no raw_json so they can't be written to the store \u2014 workers would\\n        # silently start without those flows.  Without --flow-dir workers re-execute the .py\\n        # file directly from LFX_SERVE_STARTUP_PATHS, which works fine.\\n        py_paths = [p for p in script_paths if Path(p).suffix == \\\".py\\\"]\\n        if py_paths:\\n            for p in py_paths:\\n                typer.echo(\\n                    f\\\"Error: '{Path(p).name}' (.py) cannot be used with --workers > 1 and --flow-dir. \\\"\\n                    \\\"Python graphs cannot be serialized to the store, so workers would start without \\\"\\n                    \\\"those flows. Use a .json export, omit --flow-dir, or use --workers 1.\\\",\\n                    err=True,\\n                )\\n            raise typer.Exit(1)\\n\\n    # Determine display name for startup panel\\n    if flow_json is not None:\\n        source_display = \\\"inline JSON\\\"\\n    elif stdin:\\n        source_display = \\\"stdin\\\"\\n    elif script_paths:\\n        resolved_display = [Path(p).resolve() for p in script_paths]\\n        if len(resolved_display) == 1 and resolved_display[0].is_dir():\\n            source_display = str(resolved_display[0])\\n        else:\\n            source_display = \\\", \\\".join(Path(p).name for p in script_paths)\\n    else:\\n        source_display = \\\"none (upload flows via POST /flows/upload/)\\\"\\n\\n    temp_file_to_cleanup: str | None = None\\n    try:\\n        registry, temp_file_to_cleanup = asyncio.run(\\n            _build_serve_registry(\\n                script_paths=script_paths,\\n                flow_json=flow_json,\\n                stdin=stdin,\\n                check_variables=check_variables,\\n                no_env_fallback=no_env_fallback,\\n                flow_store=flow_store,\\n                verbose_print=verbose_print,\\n                upgrade_flow=upgrade_flow,\\n                verbose=verbose,\\n            )\\n        )\\n\\n        if flow_dir:\\n            if workers == 1:\\n                # Single-worker: warm now so the startup panel shows the real count and the\\n                # first request to any pre-existing flow doesn't pay a cold-load penalty.\\n                # Multi-worker: each worker warms inside create_serve_app(); the parent can't\\n                # safely warm and pass graphs across processes, so we skip it here.\\n                registry.warm_from_store()\\n            verbose_print(f\\\"Flow store at {flow_dir} ({len(registry)} flows available)\\\")\\n\\n        if is_port_in_use(port, host):\\n            port = get_free_port(port)\\n            verbose_print(f\\\"Port in use; using {port} instead\\\")\\n\\n        verbose_print(\\\"Starting server...\\\")\\n\\n        protocol = \\\"http\\\"\\n        access_host = get_best_access_host(host)\\n        masked_key = f\\\"{api_key[:API_KEY_MASK_LENGTH]}...\\\" if len(api_key) > API_KEY_MASK_LENGTH else \\\"***\\\"\\n        server_line = f\\\"{protocol}://{access_host}:{port}\\\"\\n        if access_host != host:\\n            server_line += f\\\"  [dim](bound to {host}:{port})[/dim]\\\"\\n\\n        console.print()\\n        console.print(\\n            Panel.fit(\\n                f\\\"[bold green]LFX Server Ready[/bold green]\\\\n\\\\n\\\"\\n                f\\\"[bold]Source:[/bold] {source_display}\\\\n\\\"\\n                f\\\"[bold]Flows:[/bold] {len(registry)}\\\\n\\\"\\n                f\\\"[bold]Workers:[/bold] {workers}\\\\n\\\"\\n                f\\\"[bold]Server:[/bold] {server_line}\\\\n\\\"\\n                f\\\"[bold]API Key:[/bold] {masked_key}\\\\n\\\\n\\\"\\n                f\\\"[dim]List flows:[/dim]\\\\n\\\"\\n                f\\\"[blue]{protocol}://{access_host}:{port}/flows[/blue]\\\\n\\\\n\\\"\\n                f\\\"[dim]Upload new flow:[/dim]\\\\n\\\"\\n                f\\\"[blue]POST {protocol}://{access_host}:{port}/flows/upload/[/blue]\\\\n\\\\n\\\"\\n                f\\\"[dim]Run a flow:[/dim]\\\\n\\\"\\n                f\\\"[blue]POST {protocol}://{access_host}:{port}/flows/{{flow_id}}/run[/blue]\\\",\\n                title=\\\"[bold blue]LFX Server[/bold blue]\\\",\\n                border_style=\\\"blue\\\",\\n            )\\n        )\\n        console.print()\\n\\n        try:\\n            if workers > 1:\\n                _launch_workers(\\n                    host=host,\\n                    port=port,\\n                    workers=workers,\\n                    log_level=log_level,\\n                    flow_dir=flow_dir,\\n                    no_env_fallback=no_env_fallback,\\n                    script_paths=script_paths,\\n                    temp_file_to_cleanup=temp_file_to_cleanup,\\n                    verbose_print=verbose_print,\\n                    max_requests=max_requests,\\n                    reset_environ=reset_environ,\\n                    sync_workers=sync_workers,\\n                    timeout=timeout,\\n                    identity_config=identity_config,\\n                )\\n            else:\\n                from lfx.cli.serve_app import _SERVE_RESET_ENVIRON_ENV\\n\\n                # These flags only affect multi-worker serving; with one worker they are\\n                # silently inert, so warn loudly rather than appear to honor them.\\n                if max_requests is not None or sync_workers or timeout is not None:\\n                    typer.echo(\\n                        \\\"Warning: --max-requests/--use-sync-workers/--timeout apply only to multi-worker \\\"\\n                        \\\"serving (--workers > 1) and are ignored with a single worker.\\\",\\n                        err=True,\\n                    )\\n\\n                # Single worker also serves many requests warm, so honor --reset-environ\\n                # here (read per request by guarded_execute). --use-sync-workers is a\\n                # multi-worker routing concern and has no effect with one worker.\\n                os.environ[_SERVE_RESET_ENVIRON_ENV] = \\\"1\\\" if reset_environ else \\\"0\\\"\\n                try:\\n                    serve_app = create_multi_serve_app(registry=registry, identity_config=identity_config)\\n                    uvicorn.run(serve_app, host=host, port=port, workers=1, log_level=log_level)\\n                finally:\\n                    # Symmetry with _launch_workers: don't leave our key in the parent env.\\n                    os.environ.pop(_SERVE_RESET_ENVIRON_ENV, None)\\n        except KeyboardInterrupt:\\n            verbose_print(\\\"\\\\nServer stopped\\\")\\n            raise typer.Exit(0) from None\\n        except Exception as e:\\n            verbose_print(f\\\"Failed to start server: {e}\\\")\\n            raise typer.Exit(1) from e\\n\\n    finally:\\n        if temp_file_to_cleanup:\\n            with contextlib.suppress(OSError):\\n                Path(temp_file_to_cleanup).unlink()\\n\\n\\n@contextlib.contextmanager\\ndef _exported_env(env: dict[str, str]):\\n    \\\"\\\"\\\"Export ``env`` into ``os.environ`` for the body, then restore the prior state.\\n\\n    Keys we added are removed; keys we overwrote are restored to their original value (not a\\n    prefix sweep), so a ``LFX_SERVE_*`` var the operator exported before launch survives with\\n    its own value rather than being deleted.\\n    \\\"\\\"\\\"\\n    sentinel = object()\\n    previous = {key: os.environ.get(key, sentinel) for key in env}\\n    for key, value in env.items():\\n        os.environ[key] = value\\n    try:\\n        yield\\n    finally:\\n        for key, prev in previous.items():\\n            if prev is sentinel:\\n                os.environ.pop(key, None)\\n            else:\\n                os.environ[key] = prev\\n\\n\\ndef _launch_workers(\\n    *,\\n    host: str,\\n    port: int,\\n    workers: int,\\n    log_level: str,\\n    flow_dir: Path | None,\\n    no_env_fallback: bool,\\n    script_paths: list[str] | None,\\n    temp_file_to_cleanup: str | None,\\n    verbose_print: Callable[[str], None],\\n    max_requests: int | None,\\n    reset_environ: bool = False,\\n    sync_workers: bool = False,\\n    timeout: int | None = None,\\n    identity_config: IdentityConfig | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Launch ``workers`` worker processes for ``lfx serve --workers N``.\\n\\n    On Unix this runs gunicorn with ``preload_app=True`` (the master builds the\\n    warm app once and forks workers via copy-on-write). ``max_requests`` controls\\n    worker recycling: ``None`` (the default) maps to ``DEFAULT_MAX_REQUESTS`` so warm\\n    workers recycle periodically and shed accumulated memory (with 10% jitter so they\\n    don't recycle in lockstep); ``0`` disables recycling; ``N`` recycles after N\\n    requests.\\n\\n    **Isolation note.** ``--max-requests`` is worker hygiene, not per-request isolation:\\n    the async worker recycles gracefully, so a worker that has hit its limit keeps serving\\n    while it winds down and a later request can observe an earlier one's ``os.environ``\\n    writes. Strict isolation comes from ``--use-sync-workers`` (the blocking sync worker\\n    exits synchronously after each request) or ``--reset-environ`` (snapshot/restore\\n    ``os.environ`` around every run).\\n\\n    gunicorn is Unix-only. On Windows it cannot run at all, so multi-worker serving\\n    falls back to uvicorn's own multi-worker supervisor (no preload, no recycling);\\n    ``--max-requests`` is refused there, since it cannot be supported.\\n\\n    ``reset_environ`` (``--reset-environ``) is forwarded to the workers via\\n    ``LFX_SERVE_RESET_ENVIRON`` so each worker snapshots/restores ``os.environ``\\n    around every flow run (see ``guarded_execute``). ``sync_workers``\\n    (``--use-sync-workers``, Unix only) swaps the async worker for gunicorn's blocking\\n    ``sync`` worker wrapped by an a2wsgi ASGI->WSGI bridge, so the kernel routes each\\n    request to an idle worker. Both default off. ``timeout`` (``--timeout``) sets\\n    gunicorn's worker timeout; ``None`` maps to ``DEFAULT_TIMEOUT`` (120s) \u2014 raise it for\\n    long flows, especially under ``--use-sync-workers``.\\n\\n    ``identity_config`` (``--identity-mode`` and friends) is round-tripped to the\\n    workers via ``LFX_SERVE_IDENTITY_*`` env vars so each worker reconstructs it in\\n    ``create_serve_app`` (uvicorn) or ``serve_preloaded_app`` (gunicorn preload).\\n    ``None`` means ``off`` (the default) \u2014 set explicitly so an inherited value\\n    can't silently flip it on.\\n    \\\"\\\"\\\"\\n    from lfx.cli.serve_app import (\\n        _SERVE_FLOW_DIR_ENV,\\n        _SERVE_NO_ENV_FALLBACK_ENV,\\n        _SERVE_RESET_ENVIRON_ENV,\\n        _SERVE_STARTUP_PATHS_ENV,\\n    )\\n    from lfx.cli.serve_identity import IdentityConfig\\n\\n    # Env vars each worker reads to reconstruct config: the gunicorn preload master via\\n    # build_registry_from_env(), or each uvicorn factory worker via create_serve_app().\\n    # When flow_dir is set, startup flows are already in the store (written by\\n    # _build_serve_registry) so workers load them via warm_from_store(); otherwise workers\\n    # re-read the original files from LFX_SERVE_STARTUP_PATHS.\\n    startup_paths_for_workers: list[str] = []\\n    if not flow_dir:\\n        if script_paths:\\n            startup_paths_for_workers = [str(Path(p).resolve()) for p in script_paths]\\n        elif temp_file_to_cleanup:\\n            startup_paths_for_workers = [temp_file_to_cleanup]\\n    worker_env = {\\n        _SERVE_FLOW_DIR_ENV: str(flow_dir) if flow_dir else \\\"\\\",\\n        _SERVE_NO_ENV_FALLBACK_ENV: \\\"1\\\" if no_env_fallback else \\\"0\\\",\\n        _SERVE_STARTUP_PATHS_ENV: json.dumps(startup_paths_for_workers),\\n        # Read per request by guarded_execute. Set explicitly (even \\\"0\\\") so a stray\\n        # inherited value can't silently flip behavior.\\n        _SERVE_RESET_ENVIRON_ENV: \\\"1\\\" if reset_environ else \\\"0\\\",\\n        # Round-trip identity config into the workers (each keeps its own JWKS cache \u2014 a\\n        # few KB; no cross-worker sharing). Set explicitly even for \\\"off\\\".\\n        **(identity_config or IdentityConfig()).to_env(),\\n    }\\n\\n    with _exported_env(worker_env):\\n        if sys.platform == \\\"win32\\\":\\n            if max_requests is not None and max_requests > 0:\\n                typer.echo(\\n                    \\\"Error: --max-requests enables gunicorn worker recycling, which is not \\\"\\n                    \\\"available on Windows. Omit --max-requests to run multi-worker on Windows. \\\"\\n                    \\\"For cross-request os.environ isolation use --reset-environ (any platform); \\\"\\n                    \\\"for per-process isolation deploy on Linux/macOS with --use-sync-workers.\\\",\\n                    err=True,\\n                )\\n                raise typer.Exit(1)\\n            if sync_workers:\\n                typer.echo(\\n                    \\\"Error: --use-sync-workers uses gunicorn's sync worker, which is not available on \\\"\\n                    \\\"Windows. Omit --use-sync-workers to run multi-worker on Windows, or deploy on \\\"\\n                    \\\"Linux/macOS for idle-worker routing.\\\",\\n                    err=True,\\n                )\\n                raise typer.Exit(1)\\n            # gunicorn cannot run on Windows; fall back to uvicorn's multi-worker\\n            # supervisor. No preload/COW and no gunicorn recycling, though --reset-environ\\n            # still isolates per request (applied in guarded_execute, not gunicorn).\\n            verbose_print(\\n                \\\"Note: multi-worker serving on Windows uses uvicorn (no gunicorn recycling); \\\"\\n                \\\"use --reset-environ for cross-request os.environ isolation, or deploy on \\\"\\n                \\\"Linux/macOS with --use-sync-workers for per-process isolation.\\\"\\n            )\\n            uvicorn.run(\\n                \\\"lfx.cli.serve_app:create_serve_app\\\",\\n                host=host,\\n                port=port,\\n                workers=workers,\\n                log_level=log_level,\\n                factory=True,\\n            )\\n        else:\\n            # gunicorn ships with lfx on Linux/macOS; a missing import means a trimmed/broken\\n            # environment. Fail with the same friendly message as the a2wsgi check below rather\\n            # than a raw ModuleNotFoundError.\\n            try:\\n                from lfx.cli.serve_gunicorn import LFXGunicornApp\\n            except ImportError as exc:\\n                typer.echo(\\n                    \\\"Error: multi-worker serving needs 'gunicorn', which ships with lfx on \\\"\\n                    \\\"Linux/macOS; it is missing, so reinstall lfx to restore your environment.\\\",\\n                    err=True,\\n                )\\n                raise typer.Exit(1) from exc\\n\\n            if sync_workers:\\n                # Fail fast in the parent rather than per-worker on first request. a2wsgi\\n                # ships with lfx on Linux/macOS, so a missing import means a broken\\n                # environment, not a forgotten optional install.\\n                try:\\n                    import a2wsgi  # noqa: F401\\n                except ImportError as exc:\\n                    typer.echo(\\n                        \\\"Error: --use-sync-workers needs 'a2wsgi', which ships with lfx on Linux/macOS; \\\"\\n                        \\\"it is missing, so reinstall lfx to restore your environment.\\\",\\n                        err=True,\\n                    )\\n                    raise typer.Exit(1) from exc\\n                # gunicorn's blocking sync worker stops accepting while a request runs,\\n                # so the kernel routes the next request to an idle worker. It serves the\\n                # ASGI app through the a2wsgi WSGI bridge (built lazily, post-fork).\\n                app_import_string = \\\"lfx.cli.serve_preloaded_app:wsgi_application\\\"\\n                worker_class = \\\"sync\\\"\\n            else:\\n                app_import_string = \\\"lfx.cli.serve_preloaded_app:app\\\"\\n                worker_class = \\\"lfx.cli.serve_gunicorn.LFXUvicornWorker\\\"\\n\\n            # Unset (None) -> DEFAULT_MAX_REQUESTS so warm workers recycle periodically and\\n            # shed accumulated memory. Explicit 0 disables recycling; explicit N overrides.\\n            effective_max_requests = max_requests if max_requests is not None else DEFAULT_MAX_REQUESTS\\n            # Unset (None) -> DEFAULT_TIMEOUT; explicit --timeout N overrides.\\n            effective_timeout = timeout if timeout is not None else DEFAULT_TIMEOUT\\n\\n            LFXGunicornApp(\\n                app_import_string,\\n                {\\n                    \\\"bind\\\": f\\\"{host}:{port}\\\",\\n                    \\\"workers\\\": workers,\\n                    \\\"worker_class\\\": worker_class,\\n                    \\\"preload_app\\\": True,\\n                    \\\"max_requests\\\": effective_max_requests,\\n                    # 10% jitter so workers don't all hit the limit on the same request count\\n                    # (avoids a synchronized recycle/latency blip). 0 stays 0 (never recycle).\\n                    \\\"max_requests_jitter\\\": effective_max_requests // 10,\\n                    \\\"loglevel\\\": log_level,\\n                    # Worker timeout (--timeout, default 120). gunicorn's own default is 30s,\\n                    # which would kill long LLM flows \u2014 especially under --use-sync-workers, where a\\n                    # blocking worker cannot heartbeat mid-request.\\n                    \\\"timeout\\\": effective_timeout,\\n                },\\n            ).run()\\n\\n\\nasync def _load_graph_and_meta(\\n    path: Path,\\n    root_dir: Path,\\n    *,\\n    check_variables: bool,\\n) -> tuple:\\n    \\\"\\\"\\\"Load and prepare one graph, returning (graph, FlowMeta, raw_json | None).\\n\\n    raw_json is the parsed flow dict for .json files; None for .py files\\n    (which cannot be round-tripped to JSON for store persistence).\\n    \\\"\\\"\\\"\\n    raw_json: dict | None = None\\n    try:\\n        if path.suffix == \\\".py\\\":\\n            find_graph_variable(path)  # validates a 'graph' variable exists\\n            graph = await load_graph_from_script(path)\\n        else:\\n            raw_json = json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n            graph = load_flow_from_json(raw_json)\\n    except Exception as exc:\\n        msg = f\\\"Failed to load {path.name}: {exc}\\\"\\n        raise ValueError(msg) from exc\\n    graph.prepare()\\n    if check_variables:\\n        from lfx.cli.validation import validate_global_variables_for_env\\n\\n        errors = validate_global_variables_for_env(graph)\\n        if errors:\\n            msg = f\\\"Global variable validation failed for {path.name}: {'; '.join(errors)}\\\"\\n            raise ValueError(msg)\\n    path_flow_id = flow_id_from_path(path, root_dir)\\n    # Prefer the JSON's own id so the startup ID matches what workers reconstruct\\n    # from the store (which also prefers raw_json[\\\"id\\\"]).  Fall back to the\\n    # path-derived UUID when the JSON has no id (e.g. hand-written flows).\\n    flow_id = (raw_json.get(\\\"id\\\") if raw_json else None) or path_flow_id\\n    graph.flow_id = flow_id\\n    meta = FlowMeta(\\n        id=flow_id,\\n        relative_path=str(path.relative_to(root_dir)),\\n        title=(raw_json.get(\\\"name\\\") or path.stem) if raw_json else path.stem,\\n        description=(raw_json.get(\\\"description\\\")) if raw_json else None,\\n    )\\n    return graph, meta, raw_json\\n\\n\\nasync def _populate_registry(\\n    paths: list[Path],\\n    root_dir: Path,\\n    registry: FlowRegistry,\\n    verbose_print: Callable[[str], None],\\n    *,\\n    check_variables: bool,\\n) -> None:\\n    \\\"\\\"\\\"Load each path into *registry*, collecting errors and raising at the end.\\\"\\\"\\\"\\n    errors: list[str] = []\\n    for path in paths:\\n        try:\\n            graph, meta, raw_json = await _load_graph_and_meta(path, root_dir, check_variables=check_variables)\\n            registry.add(graph, meta, raw_json=raw_json)\\n            verbose_print(f\\\"Loaded flow '{meta.title}' (id={meta.id})\\\")\\n        except FlowAlreadyRegisteredError:\\n            verbose_print(f\\\"Skipping duplicate flow id={meta.id} from {path.name}\\\")\\n        except Exception as exc:  # noqa: BLE001\\n            errors.append(f\\\"{path.name}: {exc}\\\")\\n    if errors:\\n        msg = \\\"Failed to load flows:\\\\n\\\" + \\\"\\\\n\\\".join(f\\\"  - {e}\\\" for e in errors)\\n        raise ValueError(msg)\\n\\n\\nasync def build_registry_from_directory(\\n    dir_path: Path,\\n    verbose_print: Callable[[str], None],\\n    *,\\n    check_variables: bool,\\n    no_env_fallback: bool = False,\\n    store: FlowStore | None = None,\\n) -> FlowRegistry:\\n    \\\"\\\"\\\"Build a FlowRegistry by scanning *dir_path* for ``*.json`` files (non-recursive).\\n\\n    Callers that want pre-existing store flows (e.g. from a prior run) to be\\n    reachable are responsible for calling ``registry.warm_from_store()`` after\\n    this returns.  ``serve_command`` does this in the right place; calling it\\n    here too would cause double-loading when ``store`` backs the same directory.\\n    \\\"\\\"\\\"\\n    from lfx.cli.flow_store import NullFlowStore\\n\\n    json_files = sorted(dir_path.glob(\\\"*.json\\\"))\\n    if not json_files:\\n        msg = f\\\"No .json files found in directory: {dir_path}\\\"\\n        raise ValueError(msg)\\n\\n    registry = FlowRegistry(no_env_fallback=no_env_fallback, store=store or NullFlowStore())\\n    await _populate_registry(json_files, dir_path, registry, verbose_print, check_variables=check_variables)\\n    return registry\\n\\n\\nasync def build_registry_from_paths(\\n    paths: list[Path],\\n    verbose_print: Callable[[str], None],\\n    *,\\n    check_variables: bool,\\n    no_env_fallback: bool = False,\\n    store: FlowStore | None = None,\\n) -> FlowRegistry:\\n    \\\"\\\"\\\"Build a FlowRegistry from an explicit list of ``.json`` or ``.py`` paths.\\n\\n    Callers that want pre-existing store flows to be reachable are responsible\\n    for calling ``registry.warm_from_store()`` after this returns.\\n    ``serve_command`` does this in the right place.\\n    \\\"\\\"\\\"\\n    from lfx.cli.flow_store import NullFlowStore\\n\\n    # Use a shared root so same-named files in different directories get distinct IDs.\\n    common_root = (\\n        Path(os.path.commonpath([str(p) for p in paths])) if len(paths) > 1 else paths[0].parent if paths else Path()\\n    )\\n    registry = FlowRegistry(no_env_fallback=no_env_fallback, store=store or NullFlowStore())\\n    await _populate_registry(paths, common_root, registry, verbose_print, check_variables=check_variables)\\n    return registry\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/common.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4b41b4520c68940f2913f40d4ebec2e4e245531a64e31d53c57dde5b0ad36213\",\"content\":\"\\\"\\\"\\\"Common utilities for CLI commands.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nimport contextlib\\nimport contextvars\\nimport importlib.metadata as importlib_metadata\\nimport io\\nimport os\\nimport re\\nimport socket\\nimport subprocess\\nimport sys\\nimport tempfile\\nimport threading\\nimport uuid\\nimport zipfile\\nfrom io import StringIO\\nfrom pathlib import Path\\nfrom shutil import which\\nfrom typing import TYPE_CHECKING, Any\\nfrom urllib.parse import urlparse\\n\\nimport httpx\\nimport typer\\n\\nfrom lfx.cli.runtime_variables import build_request_variables_from_global_vars\\nfrom lfx.cli.script_loader import (\\n    extract_structured_result,\\n    find_graph_variable,\\n    load_graph_from_script,\\n)\\nfrom lfx.execution import aget_default_coordinator\\nfrom lfx.load import load_flow_from_json\\nfrom lfx.run._defaults import apply_run_defaults, resolve_fallback_to_env_vars\\nfrom lfx.schema.schema import InputValueRequest\\nfrom lfx.services.variable.request_scope import (\\n    activate_no_env_fallback,\\n    activate_request_variables,\\n    reset_no_env_fallback,\\n    reset_request_variables,\\n)\\n\\nif TYPE_CHECKING:\\n    from types import ModuleType\\n\\n# Attempt to import tomllib (3.11+) else fall back to tomli\\n_toml_parser: ModuleType | None = None\\ntry:\\n    import tomllib as _toml_parser\\nexcept ModuleNotFoundError:\\n    with contextlib.suppress(ModuleNotFoundError):\\n        import tomli as toml_parser\\n\\n        _toml_parser = toml_parser\\n\\nMAX_PORT_NUMBER = 65535\\n\\n# Fixed namespace constant for deterministic UUID5 generation across runs\\n_LANGFLOW_NAMESPACE_UUID = uuid.UUID(\\\"3c091057-e799-4e32-8ebc-27bc31e1108c\\\")\\n\\n# Environment variable for GitHub token\\n_GITHUB_TOKEN_ENV = \\\"GITHUB_TOKEN\\\"\\n\\n\\nclass _StreamCaptureBinding:\\n    \\\"\\\"\\\"Shared capture state inherited by child execution contexts.\\\"\\\"\\\"\\n\\n    def __init__(self, target) -> None:\\n        self.target = target\\n        self.active = True\\n\\n    def deactivate(self) -> None:\\n        \\\"\\\"\\\"Stop routing writes and release the completed capture buffer.\\\"\\\"\\\"\\n        self.active = False\\n        self.target = None\\n\\n\\nclass _ContextualTextStream:\\n    \\\"\\\"\\\"Route writes to a task-local stream while preserving a process fallback.\\n\\n    ``sys.stdout`` and ``sys.stderr`` are process globals, so replacing either\\n    around an ``await`` lets concurrent requests overwrite one another's capture\\n    target. A stable proxy keeps the process-global object unchanged while a\\n    ContextVar selects the destination for the current request and any child\\n    tasks (or context-propagating worker threads).\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, fallback, *, context_name: str) -> None:\\n        self._fallback = fallback\\n        self._binding: contextvars.ContextVar[_StreamCaptureBinding | None] = contextvars.ContextVar(\\n            context_name, default=None\\n        )\\n\\n    def _current(self):\\n        binding = self._binding.get()\\n        return self._fallback if binding is None or not binding.active else binding.target\\n\\n    def activate(self, target) -> tuple[contextvars.Token[_StreamCaptureBinding | None], _StreamCaptureBinding]:\\n        binding = _StreamCaptureBinding(target)\\n        return self._binding.set(binding), binding\\n\\n    def reset(\\n        self,\\n        activation: tuple[contextvars.Token[_StreamCaptureBinding | None], _StreamCaptureBinding],\\n    ) -> None:\\n        token, binding = activation\\n        binding.deactivate()\\n        self._binding.reset(token)\\n\\n    def write(self, data):\\n        return self._current().write(data)\\n\\n    def flush(self) -> None:\\n        self._current().flush()\\n\\n    def writelines(self, lines) -> None:\\n        self._current().writelines(lines)\\n\\n    def __getattr__(self, name: str):\\n        return getattr(self._current(), name)\\n\\n\\n_STREAM_PROXY_LOCK = threading.Lock()\\n\\n\\ndef _ensure_contextual_streams() -> tuple[_ContextualTextStream, _ContextualTextStream]:\\n    \\\"\\\"\\\"Install stdout/stderr proxies once for the current process stream pair.\\\"\\\"\\\"\\n    with _STREAM_PROXY_LOCK:\\n        stdout = sys.stdout\\n        if not isinstance(stdout, _ContextualTextStream):\\n            stdout = _ContextualTextStream(stdout, context_name=\\\"lfx_request_stdout\\\")\\n            sys.stdout = stdout\\n\\n        stderr = sys.stderr\\n        if not isinstance(stderr, _ContextualTextStream):\\n            stderr = _ContextualTextStream(stderr, context_name=\\\"lfx_request_stderr\\\")\\n            sys.stderr = stderr\\n\\n    return stdout, stderr\\n\\n\\ndef create_verbose_printer(*, verbose: bool):\\n    \\\"\\\"\\\"Create a verbose printer function that only prints in verbose mode.\\n\\n    Args:\\n        verbose: Whether to print verbose output\\n\\n    Returns:\\n        Function that prints to stderr only in verbose mode\\n    \\\"\\\"\\\"\\n\\n    def verbose_print(message: str) -> None:\\n        \\\"\\\"\\\"Print diagnostic messages to stderr only in verbose mode.\\\"\\\"\\\"\\n        if verbose:\\n            typer.echo(message, file=sys.stderr)\\n\\n    return verbose_print\\n\\n\\ndef is_port_in_use(port: int, host: str = \\\"localhost\\\") -> bool:\\n    \\\"\\\"\\\"Check if a port is already in use.\\\"\\\"\\\"\\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\\n        try:\\n            s.bind((host, port))\\n        except OSError:\\n            return True\\n        else:\\n            return False\\n\\n\\ndef get_free_port(starting_port: int = 8000) -> int:\\n    \\\"\\\"\\\"Get a free port starting from the given port.\\\"\\\"\\\"\\n    port = starting_port\\n    while port < MAX_PORT_NUMBER:\\n        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\\n            try:\\n                s.bind((\\\"\\\", port))\\n            except OSError:\\n                port += 1\\n            else:\\n                return port\\n    msg = \\\"No free ports available\\\"\\n    raise RuntimeError(msg)\\n\\n\\ndef get_best_access_host(host: str) -> str:\\n    \\\"\\\"\\\"Get the best host address for external access.\\\"\\\"\\\"\\n    # Note: 0.0.0.0 and :: are intentionally checked as they bind to all interfaces\\n    if host in (\\\"0.0.0.0\\\", \\\"::\\\", \\\"\\\"):\\n        return \\\"localhost\\\"\\n    return host\\n\\n\\ndef get_api_key() -> str:\\n    \\\"\\\"\\\"Get the API key from environment variable.\\n\\n    Used by ``lfx serve`` to set the superuser key on the local server.\\n    For *remote* commands (push, pull, login, \u2026), the per-environment key\\n    is resolved via :func:`lfx.config.resolve_environment` and the\\n    ``api_key_env`` field in ``.lfx/environments.yaml``.\\n    \\\"\\\"\\\"\\n    api_key = os.getenv(\\\"LANGFLOW_API_KEY\\\") or os.getenv(\\\"LFX_API_KEY\\\")\\n    if not api_key:\\n        msg = \\\"LANGFLOW_API_KEY environment variable is not set\\\"\\n        raise ValueError(msg)\\n    return api_key\\n\\n\\ndef is_url(path_or_url: str) -> bool:\\n    \\\"\\\"\\\"Check if the given string is a URL.\\n\\n    Args:\\n        path_or_url: String to check\\n\\n    Returns:\\n        True if it's a URL, False otherwise\\n    \\\"\\\"\\\"\\n    try:\\n        result = urlparse(path_or_url)\\n        return all([result.scheme, result.netloc])\\n    except Exception:  # noqa: BLE001\\n        return False\\n\\n\\ndef download_script_from_url(url: str, verbose_print) -> Path:\\n    \\\"\\\"\\\"Download a Python script from a URL and save it to a temporary file.\\n\\n    Args:\\n        url: URL to download the script from\\n        verbose_print: Function to print verbose messages\\n\\n    Returns:\\n        Path to the temporary file containing the downloaded script\\n\\n    Raises:\\n        typer.Exit: If download fails\\n    \\\"\\\"\\\"\\n    verbose_print(f\\\"Downloading script from URL: {url}\\\")\\n\\n    try:\\n        with httpx.Client(timeout=30.0) as client:\\n            response = client.get(url)\\n            response.raise_for_status()\\n\\n            # Check if the response is a Python script\\n            content_type = response.headers.get(\\\"content-type\\\", \\\"\\\").lower()\\n            valid_types = {\\\"application/x-python\\\", \\\"application/octet-stream\\\"}\\n            if not (content_type.startswith(\\\"text/\\\") or content_type in valid_types):\\n                verbose_print(f\\\"Warning: Unexpected content type: {content_type}\\\")\\n\\n            # Create a temporary file with .py extension\\n            with tempfile.NamedTemporaryFile(mode=\\\"w\\\", suffix=\\\".py\\\", delete=False) as temp_file:\\n                temp_path = Path(temp_file.name)\\n\\n                # Write the content to the temporary file\\n                script_content = response.text\\n                temp_file.write(script_content)\\n\\n            verbose_print(f\\\"\u2713 Script downloaded successfully to temporary file: {temp_path}\\\")\\n            return temp_path\\n\\n    except httpx.HTTPStatusError as e:\\n        msg = f\\\"\u2717 HTTP error downloading script: {e.response.status_code} - {e.response.text}\\\"\\n        verbose_print(msg)\\n        raise typer.Exit(1) from e\\n    except httpx.RequestError as e:\\n        msg = f\\\"\u2717 Network error downloading script: {e}\\\"\\n        verbose_print(msg)\\n        raise typer.Exit(1) from e\\n    except Exception as e:\\n        msg = f\\\"\u2717 Unexpected error downloading script: {e}\\\"\\n        verbose_print(msg)\\n        raise typer.Exit(1) from e\\n\\n\\ndef validate_script_path(script_path: Path | str, verbose_print) -> tuple[str, Path]:\\n    \\\"\\\"\\\"Validate script path or URL and return file extension and resolved path.\\n\\n    Args:\\n        script_path: Path to the script file or URL\\n        verbose_print: Function to print verbose messages\\n\\n    Returns:\\n        Tuple of (file_extension, resolved_path)\\n\\n    Raises:\\n        typer.Exit: If validation fails\\n    \\\"\\\"\\\"\\n    # Handle URL case\\n    if isinstance(script_path, str) and is_url(script_path):\\n        resolved_path = download_script_from_url(script_path, verbose_print)\\n        file_extension = resolved_path.suffix.lower()\\n        if file_extension != \\\".py\\\":\\n            verbose_print(f\\\"Error: URL must point to a Python script (.py file), got: {file_extension}\\\")\\n            raise typer.Exit(1)\\n        return file_extension, resolved_path\\n\\n    # Handle local file case\\n    if isinstance(script_path, str):\\n        script_path = Path(script_path)\\n\\n    if not script_path.exists():\\n        verbose_print(f\\\"Error: File '{script_path}' does not exist.\\\")\\n        raise typer.Exit(1)\\n\\n    if not script_path.is_file():\\n        verbose_print(f\\\"Error: '{script_path}' is not a file.\\\")\\n        raise typer.Exit(1)\\n\\n    # Check file extension and validate\\n    file_extension = script_path.suffix.lower()\\n    if file_extension not in [\\\".py\\\", \\\".json\\\"]:\\n        verbose_print(f\\\"Error: '{script_path}' must be a .py or .json file.\\\")\\n        raise typer.Exit(1)\\n\\n    return file_extension, script_path\\n\\n\\nasync def load_graph_from_path(script_path: Path, file_extension: str, verbose_print, *, verbose: bool = False):\\n    \\\"\\\"\\\"Load a graph from a Python script or JSON file.\\n\\n    Args:\\n        script_path: Path to the script file\\n        file_extension: File extension (.py or .json)\\n        verbose_print: Function to print verbose messages\\n        verbose: Whether verbose mode is enabled\\n\\n    Returns:\\n        Loaded graph object\\n\\n    Raises:\\n        typer.Exit: If loading fails\\n    \\\"\\\"\\\"\\n    file_type = \\\"Python script\\\" if file_extension == \\\".py\\\" else \\\"JSON flow\\\"\\n    verbose_print(f\\\"Analyzing {file_type}: {script_path}\\\")\\n\\n    try:\\n        if file_extension == \\\".py\\\":\\n            verbose_print(\\\"Analyzing Python script...\\\")\\n            graph_var = find_graph_variable(script_path)\\n            if graph_var:\\n                source_info = graph_var.get(\\\"source\\\", \\\"Unknown\\\")\\n                type_info = graph_var.get(\\\"type\\\", \\\"Unknown\\\")\\n                line_no = graph_var.get(\\\"line\\\", \\\"Unknown\\\")\\n                verbose_print(f\\\"\u2713 Found 'graph' variable at line {line_no}\\\")\\n                verbose_print(f\\\"  Type: {type_info}\\\")\\n                verbose_print(f\\\"  Source: {source_info}\\\")\\n            else:\\n                error_msg = \\\"No 'graph' variable found in script\\\"\\n                verbose_print(f\\\"\u2717 {error_msg}\\\")\\n                raise ValueError(error_msg)\\n\\n            verbose_print(\\\"Loading graph...\\\")\\n            graph = await load_graph_from_script(script_path)\\n        else:  # .json\\n            verbose_print(\\\"Loading JSON flow...\\\")\\n            graph = load_flow_from_json(script_path, disable_logs=not verbose)\\n\\n    except ValueError as e:\\n        # Re-raise ValueError as typer.Exit to preserve the error message\\n        raise typer.Exit(1) from e\\n    except Exception as e:\\n        verbose_print(f\\\"\u2717 Failed to load graph: {e}\\\")\\n        raise typer.Exit(1) from e\\n    else:\\n        return graph\\n\\n\\ndef prepare_graph(graph, verbose_print):\\n    \\\"\\\"\\\"Prepare a graph for execution.\\n\\n    Args:\\n        graph: Graph object to prepare\\n        verbose_print: Function to print verbose messages\\n\\n    Raises:\\n        typer.Exit: If preparation fails\\n    \\\"\\\"\\\"\\n    verbose_print(\\\"Preparing graph for execution...\\\")\\n    try:\\n        graph.prepare()\\n        verbose_print(\\\"\u2713 Graph prepared successfully\\\")\\n    except Exception as e:\\n        verbose_print(f\\\"\u2717 Failed to prepare graph: {e}\\\")\\n        raise typer.Exit(1) from e\\n\\n\\nasync def execute_graph_with_capture(\\n    graph,\\n    input_value: str | None,\\n    session_id: str | None = None,\\n    event_manager=None,\\n    user_id: str | None = None,\\n):\\n    \\\"\\\"\\\"Execute a graph and capture output.\\n\\n    Args:\\n        graph: Graph object to execute\\n        input_value: Input value to pass to the graph\\n        session_id: Optional session ID. ``None`` auto-generates one so that\\n            message-store paths (which validate session_id) succeed; an empty or\\n            whitespace-only string is rejected with ``ValueError`` to surface\\n            shell/env-var typos (see ``lfx.run._defaults.validate_provided_id``).\\n        event_manager: Optional ``EventManager``. When provided it is threaded\\n            into the run so components emit token/message/error events to its\\n            queue as the run progresses (used by the streaming workflow\\n            endpoint). ``None`` keeps the non-streaming behavior.\\n        user_id: Optional verified caller identity (e.g. forwarded by an edge\\n            gateway via a verified JWT \u2014 see ``lfx.cli.serve_identity``). ``None``\\n            keeps any ``user_id`` already pinned on the graph, and auto-generates\\n            a throwaway UUID when the graph has none (components require a\\n            non-empty user_id, but lfx's variable service is env-backed so the\\n            value is not used for scoping). A non-``None`` value overwrites the\\n            graph's value (the verified identity is authoritative).\\n\\n    Returns:\\n        Tuple of (results, captured_logs)\\n\\n    Raises:\\n        Exception: Re-raises any exception that occurs during graph execution\\n    \\\"\\\"\\\"\\n    # Apply session_id, user_id, and Memory-vertex propagation defaults via the\\n    # shared helper (same logic as run_flow). A supplied (verified) user_id\\n    # overwrites any graph-pinned value; when None (off mode / CLI runs) the\\n    # graph's existing user_id is kept, or a UUID auto-generated if it has none \u2014\\n    # the same result as calling this function before user_id was a parameter.\\n    apply_run_defaults(graph, session_id=session_id, user_id=user_id, overwrite_user_id=user_id is not None)\\n\\n    # Create input request\\n    inputs = InputValueRequest(input_value=input_value) if input_value else None\\n\\n    # Capture output during execution. The process-global streams remain stable\\n    # proxies; only this request's ContextVars point at these buffers.\\n    captured_stdout = StringIO()\\n    captured_stderr = StringIO()\\n    stdout_router, stderr_router = _ensure_contextual_streams()\\n\\n    fallback_to_env_vars = resolve_fallback_to_env_vars()\\n\\n    # Resolve before the stdout/stderr capture below: the first resolution in a process\\n    # imports the `lfx.executors` entry-point plugins, and their import-time output belongs\\n    # on the real streams rather than in this request's buffers.\\n    coordinator = await aget_default_coordinator()\\n\\n    scope_vars = build_request_variables_from_global_vars(graph.context.get(\\\"request_variables\\\"))\\n    scope_token = activate_request_variables(scope_vars or None)\\n    no_env_fallback_token = activate_no_env_fallback(disabled=bool(graph.context.get(\\\"no_env_fallback\\\")))\\n    stdout_token = stdout_router.activate(captured_stdout)\\n    stderr_token = stderr_router.activate(captured_stderr)\\n\\n    try:\\n        # Opened here rather than inside async_start, which is a generator and cannot make its\\n        # span current. See Graph.async_start.\\n        with graph.flow_execution_span():\\n            results = [\\n                payload\\n                async for payload in coordinator.stream(\\n                    graph,\\n                    initial_inputs=inputs,\\n                    fallback_to_env_vars=fallback_to_env_vars,\\n                    event_manager=event_manager,\\n                    open_flow_span=False,\\n                )\\n            ]\\n    except Exception as exc:\\n        # Capture any error output that was written to stderr\\n        error_output = captured_stderr.getvalue()\\n        if error_output:\\n            # Add error output to the exception for better debugging\\n            exc.args = (f\\\"{exc.args[0] if exc.args else str(exc)}\\\\n\\\\nCaptured stderr:\\\\n{error_output}\\\",)\\n        raise\\n    finally:\\n        try:\\n            reset_no_env_fallback(no_env_fallback_token)\\n            reset_request_variables(scope_token)\\n        finally:\\n            stderr_router.reset(stderr_token)\\n            stdout_router.reset(stdout_token)\\n\\n    # Get captured logs\\n    captured_logs = captured_stdout.getvalue() + captured_stderr.getvalue()\\n\\n    return results, captured_logs\\n\\n\\ndef extract_result_data(results, captured_logs: str) -> dict:\\n    \\\"\\\"\\\"Extract structured result data from graph execution results.\\n\\n    Args:\\n        results: Graph execution results\\n        captured_logs: Captured output logs\\n\\n    Returns:\\n        Structured result data dictionary\\n    \\\"\\\"\\\"\\n    result_data = extract_structured_result(results)\\n    result_data[\\\"logs\\\"] = captured_logs\\n    return result_data\\n\\n\\n# --- Dependency helpers ------------------------------------------------------------------\\n\\n\\ndef _parse_pep723_block(script_path: Path, verbose_print) -> dict | None:\\n    \\\"\\\"\\\"Extract the TOML table contained in a PEP-723 inline metadata block.\\n\\n    Args:\\n        script_path: Path to the Python script to inspect.\\n        verbose_print: Diagnostic printer.\\n\\n    Returns:\\n        Parsed TOML dict if a block is found and successfully parsed, otherwise None.\\n    \\\"\\\"\\\"\\n    if _toml_parser is None:\\n        verbose_print(\\\"tomllib/tomli not available - cannot parse inline dependencies\\\")\\n        return None\\n\\n    try:\\n        lines = script_path.read_text(encoding=\\\"utf-8\\\").splitlines()\\n    except OSError as exc:  # pragma: no cover\\n        verbose_print(f\\\"Failed reading script for dependency parsing: {exc}\\\")\\n        return None\\n\\n    # Locate `# /// script` and closing `# ///` markers.\\n    try:\\n        start_idx = next(i for i, ln in enumerate(lines) if ln.lstrip().startswith(\\\"# /// script\\\")) + 1\\n        end_idx = next(i for i, ln in enumerate(lines[start_idx:], start=start_idx) if ln.lstrip().startswith(\\\"# ///\\\"))\\n    except StopIteration:\\n        return None  # No valid block\\n\\n    # Remove leading comment markers and excess whitespace\\n    block_lines: list[str] = []\\n    for raw_line in lines[start_idx:end_idx]:\\n        stripped_line = raw_line.lstrip()\\n        if not stripped_line.startswith(\\\"#\\\"):\\n            continue\\n        block_lines.append(stripped_line.lstrip(\\\"# \\\"))\\n\\n    block_toml = \\\"\\\\n\\\".join(block_lines).strip()\\n    if not block_toml:\\n        return None\\n\\n    try:\\n        return _toml_parser.loads(block_toml)\\n    except Exception as exc:  # pragma: no cover  # noqa: BLE001\\n        verbose_print(f\\\"Failed parsing TOML from PEP-723 block: {exc}\\\")\\n        return None\\n\\n\\ndef extract_script_dependencies(script_path: Path, verbose_print) -> list[str]:\\n    \\\"\\\"\\\"Return dependency strings declared via PEP-723 inline metadata.\\n\\n    Only `.py` files are supported for now. Returns an empty list if the file has\\n    no metadata block or could not be parsed.\\n    \\\"\\\"\\\"\\n    if script_path.suffix != \\\".py\\\":\\n        return []\\n\\n    parsed = _parse_pep723_block(script_path, verbose_print)\\n    if not parsed:\\n        return []\\n\\n    deps = parsed.get(\\\"dependencies\\\", [])\\n    # Ensure list[str]\\n    if isinstance(deps, list):\\n        return [str(d).strip() for d in deps if str(d).strip()]\\n    return []\\n\\n\\ndef _needs_install(requirement: str) -> bool:\\n    \\\"\\\"\\\"Heuristic: check if *some* distribution that satisfies the requirement is present.\\n\\n    Exact version resolution is delegated to the installer; here we do a best-effort\\n    importlib.metadata lookup for the top-level name before the first comparison op.\\n    \\\"\\\"\\\"\\n    from packaging.requirements import Requirement  # locally imported to avoid hard dep if unused\\n\\n    try:\\n        req = Requirement(requirement)\\n    except Exception:  # noqa: BLE001\\n        return True  # If we cannot parse it, assume missing so installer handles it\\n\\n    try:\\n        dist_version = importlib_metadata.version(req.name)\\n    except importlib_metadata.PackageNotFoundError:\\n        return True\\n\\n    # If specifier is empty, we already have it.\\n    if not req.specifier:\\n        return False\\n\\n    try:\\n        from packaging.version import InvalidVersion, Version\\n    except ImportError:\\n        # If packaging is missing, we cannot compare - treat as missing.\\n        return True\\n\\n    try:\\n        if req.specifier.contains(Version(dist_version), prereleases=True):\\n            return False\\n    except InvalidVersion:\\n        return True\\n\\n    return True\\n\\n\\ndef ensure_dependencies_installed(dependencies: list[str], verbose_print) -> None:\\n    \\\"\\\"\\\"Install missing dependencies using uv (preferred) or pip.\\n\\n    Args:\\n        dependencies: List of requirement strings (PEP 508 style).\\n        verbose_print: Diagnostic printer.\\n    \\\"\\\"\\\"\\n    if not dependencies:\\n        return\\n\\n    missing = [req for req in dependencies if _needs_install(req)]\\n    if not missing:\\n        verbose_print(\\\"All script dependencies already satisfied\\\")\\n        return\\n\\n    installer_cmd: list[str]\\n    if which(\\\"uv\\\"):\\n        installer_cmd = [\\\"uv\\\", \\\"pip\\\", \\\"install\\\", \\\"--quiet\\\", *missing]\\n        tool_name = \\\"uv\\\"\\n    else:\\n        # Fall back to current interpreter's pip\\n        installer_cmd = [sys.executable, \\\"-m\\\", \\\"pip\\\", \\\"install\\\", \\\"--quiet\\\", *missing]\\n        tool_name = \\\"pip\\\"\\n\\n    verbose_print(f\\\"Installing missing dependencies with {tool_name}: {', '.join(missing)}\\\")\\n    try:\\n        subprocess.run(installer_cmd, check=True)  # noqa: S603\\n        verbose_print(\\\"\u2713 Dependency installation succeeded\\\")\\n    except subprocess.CalledProcessError as exc:  # pragma: no cover\\n        verbose_print(f\\\"\u2717 Failed installing dependencies: {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n\\ndef flow_id_from_path(file_path: Path, root_dir: Path) -> str:\\n    \\\"\\\"\\\"Generate a deterministic UUID-5 based flow id from *file_path*.\\n\\n    The function uses a fixed namespace UUID and the POSIX-style relative path\\n    (relative to *root_dir*) as the *name* when calling :pyfunc:`uuid.uuid5`.\\n    This guarantees:\\n\\n    1.  The same folder deployed again produces identical flow IDs.\\n    2.  IDs remain stable even if the absolute location of the folder changes\\n        (only the relative path is hashed).\\n    3.  Practically collision-free identifiers without maintaining external\\n        state.\\n\\n    Args:\\n        file_path: Path of the JSON flow file.\\n        root_dir: Root directory from which *file_path* should be considered\\n            relative.  Typically the folder passed to the deploy command.\\n\\n    Returns:\\n    -------\\n    str\\n        Canonical UUID string (36 chars, including hyphens).\\n    \\\"\\\"\\\"\\n    relative = file_path.relative_to(root_dir).as_posix()\\n    return str(uuid.uuid5(_LANGFLOW_NAMESPACE_UUID, relative))\\n\\n\\n# ---------------------------------------------------------------------------\\n# GitHub / ZIP repository helpers (synchronous equivalents of initial_setup)\\n# ---------------------------------------------------------------------------\\n\\n_GITHUB_RE_REPO = re.compile(r\\\"https?://(?:www\\\\.)?github\\\\.com/([\\\\w.-]+)/([\\\\w.-]+)(?:\\\\.git)?/?$\\\")\\n_GITHUB_RE_TREE = re.compile(r\\\"https?://(?:www\\\\.)?github\\\\.com/([\\\\w.-]+)/([\\\\w.-]+)/tree/([\\\\w\\\\/-]+)\\\")\\n_GITHUB_RE_RELEASE = re.compile(r\\\"https?://(?:www\\\\.)?github\\\\.com/([\\\\w.-]+)/([\\\\w.-]+)/releases/tag/([\\\\w\\\\/-]+)\\\")\\n_GITHUB_RE_COMMIT = re.compile(r\\\"https?://(?:www\\\\.)?github\\\\.com/([\\\\w.-]+)/([\\\\w.-]+)/commit/(\\\\w+)(?:/)?$\\\")\\n\\n\\ndef _github_headers() -> dict[str, str]:\\n    token = os.getenv(_GITHUB_TOKEN_ENV)\\n    if token:\\n        return {\\\"Authorization\\\": f\\\"token {token}\\\"}\\n    return {}\\n\\n\\ndef detect_github_url_sync(url: str, *, timeout: float = 15.0) -> str:\\n    \\\"\\\"\\\"Convert various GitHub URLs into a direct `.zip` download link (sync).\\n\\n    Mirrors the async implementation in *initial_setup.setup.detect_github_url*.\\n    \\\"\\\"\\\"\\n    if match := _GITHUB_RE_REPO.match(url):\\n        owner, repo = match.groups()\\n        # Determine default branch via GitHub API\\n        with httpx.Client(timeout=timeout, follow_redirects=True, headers=_github_headers()) as client:\\n            resp = client.get(f\\\"https://api.github.com/repos/{owner}/{repo}\\\")\\n            resp.raise_for_status()\\n            default_branch = resp.json().get(\\\"default_branch\\\", \\\"main\\\")\\n        return f\\\"https://github.com/{owner}/{repo}/archive/refs/heads/{default_branch}.zip\\\"\\n\\n    if match := _GITHUB_RE_TREE.match(url):\\n        owner, repo, branch = match.groups()\\n        branch = branch.rstrip(\\\"/\\\")\\n        return f\\\"https://github.com/{owner}/{repo}/archive/refs/heads/{branch}.zip\\\"\\n\\n    if match := _GITHUB_RE_RELEASE.match(url):\\n        owner, repo, tag = match.groups()\\n        tag = tag.rstrip(\\\"/\\\")\\n        return f\\\"https://github.com/{owner}/{repo}/archive/refs/tags/{tag}.zip\\\"\\n\\n    if match := _GITHUB_RE_COMMIT.match(url):\\n        owner, repo, commit = match.groups()\\n        return f\\\"https://github.com/{owner}/{repo}/archive/{commit}.zip\\\"\\n\\n    # Not a recognized GitHub URL; assume it's already a direct link\\n    return url\\n\\n\\ndef download_and_extract_repo(url: str, verbose_print, *, timeout: float = 60.0) -> Path:\\n    \\\"\\\"\\\"Download a ZIP archive from *url* and extract into a temp directory.\\n\\n    Returns the **root directory** containing the extracted files.\\n    \\\"\\\"\\\"\\n    verbose_print(f\\\"Downloading repository/ZIP from {url}\\\")\\n\\n    zip_url = detect_github_url_sync(url)\\n\\n    try:\\n        with httpx.Client(timeout=timeout, follow_redirects=True, headers=_github_headers()) as client:\\n            resp = client.get(zip_url)\\n            resp.raise_for_status()\\n\\n        tmp_dir = tempfile.TemporaryDirectory()\\n        with zipfile.ZipFile(io.BytesIO(resp.content)) as zf:\\n            zf.extractall(tmp_dir.name)\\n\\n        verbose_print(f\\\"\u2713 Repository extracted to {tmp_dir.name}\\\")\\n\\n        # Most GitHub archives have a single top-level folder; use it if present\\n        root_path = Path(tmp_dir.name)\\n        sub_entries = list(root_path.iterdir())\\n        if len(sub_entries) == 1 and sub_entries[0].is_dir():\\n            root_path = sub_entries[0]\\n\\n        # Ensure root on sys.path for custom components\\n        if str(root_path) not in sys.path:\\n            sys.path.insert(0, str(root_path))\\n\\n        # Attach TemporaryDirectory to path object so caller can keep reference\\n        # and prevent premature cleanup. We set attribute _tmp_dir.\\n        root_path._tmp_dir = tmp_dir  # type: ignore[attr-defined]  # noqa: SLF001\\n\\n    except httpx.HTTPStatusError as e:\\n        verbose_print(f\\\"\u2717 HTTP error downloading ZIP: {e.response.status_code}\\\")\\n        raise\\n    except Exception as exc:\\n        verbose_print(f\\\"\u2717 Failed downloading or extracting repo: {exc}\\\")\\n        raise\\n    else:\\n        return root_path\\n\\n\\ndef load_sdk(command_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import ``langflow_sdk`` to keep CLI startup fast.\\n\\n    Raises :class:`typer.BadParameter` with install guidance when the package\\n    is not available.\\n\\n    Args:\\n        command_name: Name of the CLI command requesting the SDK (used in\\n            the error message).\\n    \\\"\\\"\\\"\\n    try:\\n        import langflow_sdk  # type: ignore[import-untyped]\\n    except ImportError as exc:\\n        msg = f\\\"langflow-sdk is required for lfx {command_name}. Install it with: pip install langflow-sdk\\\"\\n        raise typer.BadParameter(msg) from exc\\n    else:\\n        return langflow_sdk\\n\\n\\ndef safe_filename(name: str) -> str:\\n    \\\"\\\"\\\"Convert a flow name to a safe filesystem basename (no extension).\\\"\\\"\\\"\\n    safe = \\\"\\\".join(c if c.isalnum() or c in \\\"-_ \\\" else \\\"_\\\" for c in name)\\n    return safe.strip().replace(\\\" \\\", \\\"_\\\")\\n\\n\\ndef extract_script_docstring(script_path: Path) -> str | None:\\n    \\\"\\\"\\\"Extract the module-level docstring from a Python script.\\n\\n    Args:\\n        script_path: Path to the Python script file\\n\\n    Returns:\\n        The docstring text if found, None otherwise\\n    \\\"\\\"\\\"\\n    try:\\n        # Read the file content\\n        with script_path.open(encoding=\\\"utf-8\\\") as f:\\n            content = f.read()\\n\\n        # Parse the AST\\n        tree = ast.parse(content)\\n\\n        # Check if the first statement is a docstring\\n        # A docstring is a string literal that appears as the first statement\\n        if (\\n            tree.body\\n            and isinstance(tree.body[0], ast.Expr)\\n            and isinstance(tree.body[0].value, ast.Constant)\\n            and isinstance(tree.body[0].value.value, str)\\n        ):\\n            docstring = tree.body[0].value.value\\n            # Clean up the docstring by removing extra whitespace\\n            return docstring.strip()\\n\\n    except (OSError, SyntaxError, UnicodeDecodeError):\\n        # If we can't read or parse the file, just return None\\n        # Don't raise an error as this is optional functionality\\n        pass\\n\\n    return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/create.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f0249f9444af4cf6ff2acd0523846596a24062280ff1f4d370108533a7e5085e\",\"content\":\"\\\"\\\"\\\"lfx create -- scaffold a new flow JSON from a built-in template.\\n\\nWrites a ready-to-edit flow JSON file into the target directory so teams\\ncan start from a known-good structure rather than an empty file.\\n\\nExamples::\\n\\n    lfx create my-chatbot\\n    lfx create my-rag --template hello-world\\n    lfx create my-flow --output-dir ./flows --overwrite\\n    lfx create --list\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport uuid\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nimport typer\\nfrom rich.console import Console\\nfrom rich.table import Table\\n\\nconsole = Console()\\n\\n_FLOWS_TEMPLATE_DIR = Path(__file__).parent.parent / \\\"templates\\\" / \\\"flows\\\"\\n\\n# Descriptions shown in ``lfx create --list``\\n_TEMPLATE_DESCRIPTIONS: dict[str, str] = {\\n    \\\"hello-world\\\": \\\"ChatInput \u2192 ChatOutput \u2014 minimal echo flow, no LLM required\\\",\\n}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef list_templates() -> list[str]:\\n    \\\"\\\"\\\"Return the names of all available flow templates (sorted).\\\"\\\"\\\"\\n    if not _FLOWS_TEMPLATE_DIR.exists():\\n        return []\\n    return sorted(p.stem for p in _FLOWS_TEMPLATE_DIR.glob(\\\"*.json\\\"))\\n\\n\\ndef _load_template(name: str) -> dict[str, Any]:\\n    \\\"\\\"\\\"Load and parse a template JSON by name.  Raises FileNotFoundError if missing.\\\"\\\"\\\"\\n    path = _FLOWS_TEMPLATE_DIR / f\\\"{name}.json\\\"\\n    if not path.exists():\\n        available = list_templates()\\n        hint = f\\\"  Available templates: {', '.join(available)}\\\" if available else \\\"  No templates found.\\\"\\n        msg = f\\\"Template '{name}' not found.\\\\n{hint}\\\"\\n        raise FileNotFoundError(msg)\\n    return json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n\\n\\ndef _slugify(name: str) -> str:\\n    \\\"\\\"\\\"Convert a flow name to a safe filename stem (lowercase, hyphens).\\\"\\\"\\\"\\n    return name.lower().replace(\\\" \\\", \\\"-\\\").replace(\\\"_\\\", \\\"-\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Core command (importable for testing and for init seeding)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _is_lfx_project() -> bool:\\n    \\\"\\\"\\\"Return True if cwd (or a parent up to .git) contains .lfx/environments.yaml.\\\"\\\"\\\"\\n    cwd = Path.cwd()\\n    for directory in (cwd, *cwd.parents):\\n        if (directory / \\\".lfx\\\" / \\\"environments.yaml\\\").is_file():\\n            return True\\n        if (directory / \\\".lfx\\\" / \\\"environments.yml\\\").is_file():\\n            return True\\n        if (directory / \\\".git\\\").is_dir() or directory.parent == directory:\\n            break\\n    return False\\n\\n\\ndef create_command(\\n    name: str,\\n    *,\\n    template: str = \\\"hello-world\\\",\\n    output_dir: Path = Path(\\\"flows\\\"),\\n    overwrite: bool = False,\\n) -> Path:\\n    \\\"\\\"\\\"Create a new flow JSON from *template* and write it to *output_dir/<slug>.json*.\\n\\n    Returns the path of the written file.\\n    Raises ``typer.Exit`` on user-facing errors so the CLI reports them cleanly.\\n    \\\"\\\"\\\"\\n    if not _is_lfx_project():\\n        console.print(\\n            \\\"[yellow]Warning:[/yellow] No .lfx/environments.yaml found in this project. \\\"\\n            \\\"Run [bold]lfx init[/bold] first to scaffold a project.\\\"\\n        )\\n\\n    available = list_templates()\\n    if not available:\\n        console.print(\\\"[red]Error:[/red] No flow templates found in the lfx package.\\\")\\n        raise typer.Exit(1)\\n\\n    if template not in available:\\n        console.print(\\n            f\\\"[red]Error:[/red] Unknown template [bold]{template!r}[/bold]. Available: {', '.join(available)}\\\"\\n        )\\n        raise typer.Exit(1)\\n\\n    slug = _slugify(name)\\n    output_dir = output_dir.resolve()\\n    dest = output_dir / f\\\"{slug}.json\\\"\\n\\n    if dest.exists() and not overwrite:\\n        console.print(f\\\"[red]Error:[/red] {dest} already exists. Use [bold]--overwrite[/bold] to replace it.\\\")\\n        raise typer.Exit(1)\\n\\n    # Load template and stamp with a fresh UUID + the requested name\\n    flow = _load_template(template)\\n    flow[\\\"id\\\"] = str(uuid.uuid4())\\n    flow[\\\"name\\\"] = name\\n\\n    output_dir.mkdir(parents=True, exist_ok=True)\\n    dest.write_text(json.dumps(flow, indent=2), encoding=\\\"utf-8\\\")\\n\\n    console.print(f\\\"[bold green]\u2713[/bold green] Created [bold]{dest}[/bold]\\\")\\n    console.print(f\\\"  Template : {template}\\\")\\n    console.print(f\\\"  Flow ID  : {flow['id']}\\\")\\n    console.print()\\n    console.print(\\\"Next steps:\\\")\\n    console.print(f\\\"  [bold]lfx validate {dest}[/bold]\\\")\\n    console.print(f\\\"  [bold]lfx serve {dest}[/bold]\\\")\\n\\n    return dest\\n\\n\\n# ---------------------------------------------------------------------------\\n# Listing helper (also used by the CLI --list flag)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef print_templates() -> None:\\n    \\\"\\\"\\\"Print available templates as a Rich table.\\\"\\\"\\\"\\n    available = list_templates()\\n    if not available:\\n        console.print(\\\"[yellow]No flow templates found.[/yellow]\\\")\\n        return\\n\\n    table = Table(title=\\\"Available flow templates\\\", show_header=True, header_style=\\\"bold\\\")\\n    table.add_column(\\\"Name\\\", style=\\\"cyan\\\", no_wrap=True)\\n    table.add_column(\\\"Description\\\")\\n\\n    for name in available:\\n        desc = _TEMPLATE_DESCRIPTIONS.get(name, \\\"\\\")\\n        table.add_row(name, desc)\\n\\n    console.print(table)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/export.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6b7dbcf0808a123487098abc849a46d5da31e7c8c8fd0b344a702ff8f3b37ec9\",\"content\":\"\\\"\\\"\\\"lfx export -- serialize flows to git-friendly JSON.\\n\\nTwo modes of operation\\n----------------------\\nLocal (default)\\n    Read one or more flow JSON files from disk, normalize them, and write the\\n    result back to disk (or stdout).  No network connection required.\\n\\nRemote (--env / --flow-id / --project-id)\\n    Pull flows directly from a running Langflow instance using the\\n    ``langflow-sdk`` HTTP client, normalize them, and write to disk.\\n\\nExamples:\\n--------\\nNormalize a local file in-place::\\n\\n    lfx export my_flow.json --in-place\\n\\nNormalize and write to a new file::\\n\\n    lfx export my_flow.json -o my_flow.normalized.json\\n\\nPull a single flow from staging and write to the current directory::\\n\\n    lfx export --flow-id <uuid> --env staging\\n\\nExport an entire project from staging into ./flows/::\\n\\n    lfx export --project-id <uuid> --env staging --output-dir ./flows/\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport sys\\nfrom pathlib import Path\\nfrom typing import Any\\nfrom uuid import UUID\\n\\nimport typer\\nfrom rich.console import Console\\n\\nfrom lfx.cli.common import load_sdk, safe_filename\\n\\nconsole = Console(stderr=True)\\n\\n\\ndef _write_flow(\\n    flow: dict[str, Any],\\n    *,\\n    sdk: Any,\\n    output: Path | None,\\n    in_place: bool,\\n    source_path: Path | None,\\n    indent: int,\\n) -> Path | None:\\n    \\\"\\\"\\\"Serialise *flow* and write it to the appropriate destination.\\n\\n    Returns the path written to, or ``None`` if writing to stdout.\\n    \\\"\\\"\\\"\\n    content = sdk.flow_to_json(flow, indent=indent)\\n\\n    if in_place and source_path:\\n        source_path.write_text(content, encoding=\\\"utf-8\\\")\\n        return source_path\\n\\n    if output:\\n        output.write_text(content, encoding=\\\"utf-8\\\")\\n        return output\\n\\n    sys.stdout.write(content)\\n    return None\\n\\n\\ndef export_command(\\n    flow_paths: list[str],\\n    *,\\n    output: str | None,\\n    output_dir: str | None,\\n    env: str | None,\\n    flow_id: str | None,\\n    project_id: str | None,\\n    environments_file: str | None,\\n    target: str | None = None,\\n    api_key: str | None = None,\\n    in_place: bool,\\n    strip_volatile: bool,\\n    strip_secrets: bool,\\n    code_as_lines: bool,\\n    strip_node_volatile: bool,\\n    indent: int,\\n) -> None:\\n    sdk = load_sdk(\\\"export\\\")\\n\\n    normalize_kwargs = {\\n        \\\"strip_volatile\\\": strip_volatile,\\n        \\\"strip_secrets\\\": strip_secrets,\\n        \\\"sort_keys\\\": True,\\n        \\\"code_as_lines\\\": code_as_lines,\\n        \\\"strip_node_volatile\\\": strip_node_volatile,\\n    }\\n\\n    # ------------------------------------------------------------------\\n    # Remote mode: pull from a live Langflow instance\\n    # ------------------------------------------------------------------\\n    if flow_id or project_id:\\n        if not env and not target:\\n            console.print(\\\"[red]Error:[/red] --env or --target is required for remote export.\\\")\\n            raise typer.Exit(1)\\n\\n        from lfx.config import ConfigError, resolve_environment\\n\\n        try:\\n            env_cfg = resolve_environment(\\n                env,\\n                target=target,\\n                api_key=api_key,\\n                environments_file=environments_file,\\n            )\\n        except ConfigError as exc:\\n            console.print(f\\\"[red]Error:[/red] {exc}\\\")\\n            raise typer.Exit(1) from exc\\n\\n        client = sdk.Client(base_url=env_cfg.url, api_key=env_cfg.api_key)\\n\\n        if flow_id:\\n            flow_obj = client.get_flow(UUID(flow_id))\\n            normalized = sdk.normalize_flow(flow_obj.model_dump(mode=\\\"json\\\"), **normalize_kwargs)\\n            dest_dir = Path(output_dir) if output_dir else Path.cwd()\\n            dest_dir.mkdir(parents=True, exist_ok=True)\\n            safe_name = safe_filename(flow_obj.name)\\n            out_path = dest_dir / f\\\"{safe_name}.json\\\"\\n            out_path.write_text(sdk.flow_to_json(normalized, indent=indent), encoding=\\\"utf-8\\\")\\n            console.print(f\\\"[green]Exported[/green] {flow_obj.name!r} \u2192 {out_path}\\\")\\n            return\\n\\n        # Project mode: export all flows\\n        project = client.get_project(UUID(project_id))\\n        dest_dir = Path(output_dir) if output_dir else Path.cwd() / safe_filename(project.name)\\n        dest_dir.mkdir(parents=True, exist_ok=True)\\n\\n        exported = 0\\n        for flow_obj in project.flows:\\n            normalized = sdk.normalize_flow(flow_obj.model_dump(mode=\\\"json\\\"), **normalize_kwargs)\\n            safe_name = safe_filename(flow_obj.name)\\n            out_path = dest_dir / f\\\"{safe_name}.json\\\"\\n            out_path.write_text(sdk.flow_to_json(normalized, indent=indent), encoding=\\\"utf-8\\\")\\n            console.print(f\\\"[green]Exported[/green] {flow_obj.name!r} \u2192 {out_path}\\\")\\n            exported += 1\\n\\n        console.print(f\\\"\\\\n[bold]{exported}[/bold] flow(s) exported to {dest_dir}\\\")\\n        return\\n\\n    # ------------------------------------------------------------------\\n    # Local mode: normalize files already on disk\\n    # ------------------------------------------------------------------\\n    if not flow_paths:\\n        console.print(\\\"[red]Error:[/red] Provide at least one flow JSON file, or use --flow-id / --project-id.\\\")\\n        raise typer.Exit(1)\\n\\n    if output and len(flow_paths) > 1:\\n        console.print(\\\"[red]Error:[/red] --output can only be used with a single input file.\\\")\\n        raise typer.Exit(1)\\n\\n    out_path_obj = Path(output) if output else None\\n\\n    for raw_path in flow_paths:\\n        src = Path(raw_path)\\n        if not src.exists():\\n            console.print(f\\\"[red]Error:[/red] File not found: {src}\\\")\\n            raise typer.Exit(1)\\n\\n        try:\\n            normalized = sdk.normalize_flow_file(src, **normalize_kwargs)\\n        except (json.JSONDecodeError, OSError, ValueError) as exc:\\n            console.print(f\\\"[red]Error:[/red] Could not process {src}: {exc}\\\")\\n            raise typer.Exit(1) from exc\\n\\n        dest = _write_flow(\\n            normalized,\\n            sdk=sdk,\\n            output=out_path_obj,\\n            in_place=in_place,\\n            source_path=src,\\n            indent=indent,\\n        )\\n        if dest:\\n            console.print(f\\\"[green]Exported[/green] {src} \u2192 {dest}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/init.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8616396f40c0e7d8f923b18b71382900b8cc414e8a13b3f432fcdce543eef2e9\",\"content\":\"\\\"\\\"\\\"lfx init -- scaffold a new Flow DevOps project.\\n\\nCreates the standard directory layout, an environments config stub,\\nexample tests, and (optionally) GitHub Actions CI workflows -- everything\\na team needs to start treating flows as code.\\n\\nExamples::\\n\\n    lfx init my-rag-project\\n    lfx init .                   # scaffold into the current directory\\n    lfx init my-project --no-github-actions\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nimport typer\\nfrom rich.console import Console\\nfrom rich.tree import Tree\\n\\nconsole = Console()\\n\\n# ---------------------------------------------------------------------------\\n# Templates embedded as strings (environments config and test stubs)\\n# ---------------------------------------------------------------------------\\n\\n_ENVIRONMENTS_YAML = \\\"\\\"\\\"\\\\\\n# .lfx/environments.yaml\\n#\\n# Configure your Langflow instances here.\\n# Safe to commit \u2014 API keys are NEVER stored in this file.\\n# The api_key_env value is the NAME of an environment variable that holds\\n# the actual API key; set that variable in your shell or CI secrets.\\n#\\n# Quick start:\\n#   1. Open Langflow \u2192 Settings \u2192 API Keys \u2192 Create a new key\\n#   2. export LANGFLOW_LOCAL_API_KEY=<your key>\\n#   3. lfx export --env local --flow-id <uuid> --output-dir flows/\\n\\nenvironments:\\n  local:\\n    url: http://localhost:7860\\n    api_key_env: LANGFLOW_LOCAL_API_KEY\\n\\n  staging:\\n    url: https://staging.langflow.example.com\\n    api_key_env: LANGFLOW_STAGING_API_KEY\\n\\n  production:\\n    url: https://langflow.example.com\\n    api_key_env: LANGFLOW_PROD_API_KEY\\n\\ndefaults:\\n  environment: local\\n\\\"\\\"\\\"\\n\\n_TEST_FLOWS_PY = '''\\\\\\n\\\"\\\"\\\"Integration tests for Langflow flows.\\n\\nRun against a local instance (started with ``lfx serve``):\\n\\n    pytest tests/ --langflow-url http://localhost:8000\\n\\nRun against a named environment (staging, production, etc.):\\n\\n    pytest tests/ --langflow-env staging -m integration\\n\\nThe flow_runner fixture auto-skips when no connection is configured,\\nso these tests are safe to include in any CI pipeline.\\n\\\"\\\"\\\"\\n\\nimport pytest\\n\\n\\n@pytest.mark.integration\\ndef test_flow_responds(flow_runner):\\n    \\\"\\\"\\\"Smoke test: every flow should return a non-empty response.\\\"\\\"\\\"\\n    # TODO: replace \\\"my-flow-endpoint\\\" with your flow\\\\'s endpoint name or UUID\\n    result = flow_runner(\\\"my-flow-endpoint\\\", \\\"Hello!\\\")\\n    assert result.first_text_output() is not None, \\\"Flow returned no output\\\"\\n\\n\\n@pytest.mark.integration\\ndef test_flow_output_quality(flow_runner):\\n    \\\"\\\"\\\"Example: assert on the content of the response.\\\"\\\"\\\"\\n    result = flow_runner(\\\"my-flow-endpoint\\\", \\\"What is Langflow?\\\")\\n    text = result.first_text_output()\\n    assert text is not None\\n    assert len(text) > 20, f\\\"Response seems too short: {text!r}\\\"\\n'''\\n\\n_GITIGNORE = \\\"\\\"\\\"\\\\\\n# Langflow credentials -- never commit API keys\\n# (langflow-environments.toml may contain literal keys; .lfx/environments.yaml is safe to commit)\\nlangflow-environments.toml\\n\\\"\\\"\\\"\\n\\n# Templates bundled inside the Python package\\n_TEMPLATES_DIR = Path(__file__).parent.parent / \\\"templates\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _write(\\n    path: Path,\\n    content: str,\\n    label: str,\\n    created: list[tuple[str, str]],\\n    *,\\n    target: Path,\\n    overwrite: bool,\\n) -> None:\\n    path.parent.mkdir(parents=True, exist_ok=True)\\n    if path.exists() and not overwrite:\\n        return\\n    path.write_text(content, encoding=\\\"utf-8\\\")\\n    created.append((str(path.relative_to(target)), label))\\n\\n\\ndef _copy_template(\\n    src: Path, dest: Path, label: str, created: list[tuple[str, str]], *, target: Path, overwrite: bool\\n) -> None:\\n    dest.parent.mkdir(parents=True, exist_ok=True)\\n    if dest.exists() and not overwrite:\\n        return\\n    dest.write_text(src.read_text(encoding=\\\"utf-8\\\"), encoding=\\\"utf-8\\\")\\n    created.append((str(dest.relative_to(target)), label))\\n\\n\\ndef _render_tree(target: Path, created: list[tuple[str, str]]) -> None:\\n    label = f\\\"[bold]{target.name}/[/bold]\\\" if target != Path.cwd() else \\\"[bold].[/bold] (current directory)\\\"\\n    tree = Tree(label)\\n    branch_nodes: dict[str, Any] = {}\\n\\n    for rel_path, annotation in sorted(created, key=lambda x: x[0]):\\n        parts = Path(rel_path).parts\\n        node = tree\\n        for i, part in enumerate(parts[:-1]):\\n            key = \\\"/\\\".join(parts[: i + 1])\\n            if key not in branch_nodes:\\n                branch_nodes[key] = node.add(f\\\"[bold blue]{part}/[/bold blue]\\\")\\n            node = branch_nodes[key]\\n        suffix = f\\\"  [dim]{annotation}[/dim]\\\" if annotation else \\\"\\\"\\n        node.add(f\\\"[green]{parts[-1]}[/green]{suffix}\\\")\\n\\n    console.print()\\n    console.print(tree)\\n\\n\\n# ---------------------------------------------------------------------------\\n# Command\\n# ---------------------------------------------------------------------------\\n\\n\\ndef init_command(\\n    project_dir: Path,\\n    *,\\n    github_actions: bool,\\n    overwrite: bool,\\n    example: bool = True,\\n) -> None:\\n    \\\"\\\"\\\"Scaffold a Flow DevOps project at *project_dir*.\\\"\\\"\\\"\\n    target = project_dir.resolve()\\n\\n    if target.exists() and not overwrite:\\n        existing = [p for p in target.iterdir() if p.name != \\\".git\\\"]\\n        if existing:\\n            msg = f\\\"{target} already exists and is not empty. Use [bold]--overwrite[/bold] to scaffold into it anyway.\\\"\\n            console.print(f\\\"[red]Error:[/red] {msg}\\\")\\n            raise typer.Exit(1)\\n\\n    target.mkdir(parents=True, exist_ok=True)\\n    created: list[tuple[str, str]] = []\\n\\n    kw: dict[str, Any] = {\\\"target\\\": target, \\\"overwrite\\\": overwrite, \\\"created\\\": created}\\n\\n    # flows/\\n    (target / \\\"flows\\\").mkdir(exist_ok=True)\\n    if example:\\n        from lfx.cli.create import create_command as _create\\n\\n        try:\\n            _create(\\n                \\\"hello-world\\\",\\n                template=\\\"hello-world\\\",\\n                output_dir=target / \\\"flows\\\",\\n                overwrite=overwrite,\\n            )\\n            created.append((\\\"flows/hello-world.json\\\", \\\"starter flow \u2014 edit or replace\\\"))\\n        except (OSError, ValueError, TypeError, RuntimeError) as exc:\\n            # Don't let a template failure block the rest of init\\n            console.print(f\\\"[yellow]Warning:[/yellow] Could not seed starter flow: {exc}\\\")\\n    else:\\n        _write(target / \\\"flows\\\" / \\\".gitkeep\\\", \\\"\\\", \\\"versioned empty directory\\\", **kw)\\n\\n    # tests/\\n    _write(target / \\\"tests\\\" / \\\"__init__.py\\\", \\\"\\\", \\\"\\\", **kw)\\n    _write(target / \\\"tests\\\" / \\\"test_flows.py\\\", _TEST_FLOWS_PY, \\\"flow_runner example tests\\\", **kw)\\n\\n    # .lfx/environments.yaml\\n    _write(\\n        target / \\\".lfx\\\" / \\\"environments.yaml\\\",\\n        _ENVIRONMENTS_YAML,\\n        \\\"edit with your instance URLs + API key env var names (safe to commit)\\\",\\n        **kw,\\n    )\\n\\n    # .gitignore \u2014 keep langflow-environments.toml ignored for backward compat\\n    gitignore = target / \\\".gitignore\\\"\\n    if gitignore.exists():\\n        existing_content = gitignore.read_text(encoding=\\\"utf-8\\\")\\n        if \\\"langflow-environments.toml\\\" not in existing_content:\\n            gitignore.write_text(existing_content.rstrip() + \\\"\\\\n\\\\n\\\" + _GITIGNORE, encoding=\\\"utf-8\\\")\\n            created.append((\\\".gitignore\\\", \\\"appended credentials ignore rule\\\"))\\n    else:\\n        _write(gitignore, _GITIGNORE, \\\"ignores legacy credentials file\\\", **kw)\\n\\n    # GitHub Actions CI workflows\\n    if github_actions:\\n        gha_src = _TEMPLATES_DIR / \\\"github-actions\\\"\\n        if gha_src.exists():\\n            for tmpl in sorted(gha_src.glob(\\\"*.yml\\\")):\\n                dest = target / \\\".github\\\" / \\\"workflows\\\" / tmpl.name\\n                _copy_template(tmpl, dest, \\\"CI workflow\\\", created, target=target, overwrite=overwrite)\\n        else:\\n            console.print(\\\"[yellow]Warning:[/yellow] GitHub Actions templates not found; skipping.\\\")\\n\\n    # Generic shell CI scripts (always scaffolded \u2014 work with any CI system)\\n    shell_src = _TEMPLATES_DIR / \\\"shell\\\"\\n    if shell_src.exists():\\n        for tmpl in sorted(shell_src.glob(\\\"*.sh\\\")):\\n            dest = target / \\\"ci\\\" / tmpl.name\\n            _copy_template(tmpl, dest, \\\"generic CI script\\\", created, target=target, overwrite=overwrite)\\n            dest.chmod(dest.stat().st_mode | 0o111)  # ensure executable bit\\n\\n    # Print the created-files tree\\n    _render_tree(target, created)\\n\\n    # Next-steps guide\\n    console.print()\\n    console.print(\\\"[bold green]\u2713 Project scaffolded.[/bold green]  Next steps:\\\\n\\\")\\n    console.print(\\\"  1. Edit [bold].lfx/environments.yaml[/bold] with your instance URL\\\")\\n    console.print(\\\"  2. [bold]export LANGFLOW_LOCAL_API_KEY=<key>[/bold]   (Settings \u2192 API Keys)\\\")\\n    if example:\\n        console.print(\\\"  3. [bold]lfx validate flows/hello-world.json[/bold]  (check the starter flow)\\\")\\n        console.print(\\\"  4. [bold]lfx serve flows/hello-world.json[/bold]     (run it locally)\\\")\\n        console.print(\\\"  5. [bold]lfx push --dir flows/ --env local[/bold]    (deploy to Langflow)\\\")\\n    else:\\n        console.print(\\\"  3. [bold]lfx create my-flow --template hello-world[/bold]\\\")\\n        console.print(\\\"  4. [bold]lfx push --dir flows/ --env local[/bold]\\\")\\n    console.print(f\\\"  {'6' if example else '5'}. [bold]pytest tests/ --langflow-env local[/bold]\\\")\\n    console.print()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/login.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4d8b8fcd925fd6af301311c284da641d463712fad63d1aeb6d0bbdbf48bd9439\",\"content\":\"\\\"\\\"\\\"lfx login -- validate credentials against a remote Langflow instance.\\n\\nTests whether the configured URL and API key are reachable and accepted,\\nthen prints a summary with guidance on how to fix any problems.\\n\\nUsage examples\\n--------------\\nValidate a named environment::\\n\\n    lfx login --env staging\\n\\nValidate inline credentials::\\n\\n    lfx login --target https://langflow.example.com --api-key sk-abc123\\n\\nValidate whichever environment is the default in your config::\\n\\n    lfx login\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nimport typer\\nfrom rich.console import Console\\nfrom rich.panel import Panel\\n\\nfrom lfx.cli.common import load_sdk\\n\\nconsole = Console()\\nerr_console = Console(stderr=True)\\n\\n_KEY_MASK = 8  # characters shown before \\\"...\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _mask_key(key: str) -> str:\\n    if len(key) <= _KEY_MASK:\\n        return \\\"***\\\"\\n    return key[:_KEY_MASK] + \\\"...\\\"\\n\\n\\ndef _api_key_env_name(env_name: str, environments_file: str | None) -> str | None:\\n    \\\"\\\"\\\"Return the ``api_key_env`` var name for *env_name* from the config file, or ``None``.\\\"\\\"\\\"\\n    try:\\n        from lfx.config.environments import _find_config_file, _load_config\\n\\n        override = Path(environments_file) if environments_file else None\\n        config_path = _find_config_file(override)\\n        if config_path is None:\\n            return None\\n        _load_config(config_path)\\n\\n        # Re-read raw to get api_key_env\\n        from lfx.config.environments import _load_raw\\n\\n        raw = _load_raw(config_path)\\n        block = (raw.get(\\\"environments\\\") or {}).get(env_name, {})\\n        return block.get(\\\"api_key_env\\\") if isinstance(block, dict) else None\\n    except Exception:  # noqa: BLE001\\n        return None\\n\\n\\ndef _probe_connection(client: Any, sdk: Any) -> tuple[bool, str, int]:\\n    \\\"\\\"\\\"Attempt a lightweight API call. Return ``(ok, message, flow_count)``.\\\"\\\"\\\"\\n    try:\\n        flows = client.list_flows(page=1, size=1)\\n        return True, \\\"OK\\\", len(flows)\\n    except sdk.LangflowAuthError:\\n        return False, \\\"auth\\\", 0\\n    except sdk.LangflowConnectionError as exc:\\n        return False, f\\\"connection:{exc}\\\", 0\\n    except sdk.LangflowHTTPError as exc:\\n        return False, f\\\"http:{exc}\\\", 0\\n    except Exception as exc:  # noqa: BLE001\\n        # A Pydantic ValidationError means the HTTP request completed and was\\n        # authenticated (auth is fine) but the SDK's schema doesn't match the\\n        # local Langflow version exactly.  Treat this as a successful probe.\\n        if \\\"ValidationError\\\" in type(exc).__qualname__:\\n            return True, \\\"OK\\\", 0\\n        return False, f\\\"error:{exc}\\\", 0\\n\\n\\n# ---------------------------------------------------------------------------\\n# CLI entry point\\n# ---------------------------------------------------------------------------\\n\\n\\ndef login_command(\\n    *,\\n    env: str | None,\\n    environments_file: str | None,\\n    target: str | None,\\n    api_key: str | None,\\n) -> None:\\n    sdk = load_sdk(\\\"login\\\")\\n\\n    from lfx.config import ConfigError, resolve_environment\\n\\n    try:\\n        env_cfg = resolve_environment(\\n            env,\\n            target=target,\\n            api_key=api_key,\\n            environments_file=environments_file,\\n        )\\n    except ConfigError as exc:\\n        err_console.print(f\\\"[red]Configuration error:[/red] {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n    # ------------------------------------------------------------------\\n    # Key guidance (before probing)\\n    # ------------------------------------------------------------------\\n    key_env_name: str | None = None\\n    if env_cfg.api_key is None and env_cfg.name not in (\\\"__inline__\\\", \\\"__env__\\\"):\\n        key_env_name = _api_key_env_name(env_cfg.name, environments_file)\\n\\n    if env_cfg.api_key is None:\\n        warning_parts = [\\\"[yellow]Warning:[/yellow] No API key configured.\\\"]\\n        if key_env_name:\\n            warning_parts.append(f\\\"  Set [bold]export {key_env_name}=<your-key>[/bold] then retry.\\\")\\n        else:\\n            warning_parts.append(\\\"  Add [bold]api_key_env: LANGFLOW_<ENV>_API_KEY[/bold] to your config,\\\")\\n            warning_parts.append(\\\"  then set that environment variable to your API key.\\\")\\n        for line in warning_parts:\\n            err_console.print(line)\\n\\n    # ------------------------------------------------------------------\\n    # Probe the connection\\n    # ------------------------------------------------------------------\\n    client = sdk.Client(base_url=env_cfg.url, api_key=env_cfg.api_key)\\n\\n    console.print(f\\\"[dim]Connecting to[/dim] {env_cfg.url} \u2026\\\")\\n    ok, msg, _flow_count = _probe_connection(client, sdk)\\n\\n    if not ok:\\n        if msg == \\\"auth\\\":\\n            err_console.print()\\n            err_console.print(\\\"[red bold]\u2717 Authentication failed.[/red bold]\\\")\\n            err_console.print(f\\\"  URL:  {env_cfg.url}\\\")\\n            if env_cfg.api_key:\\n                err_console.print(f\\\"  Key:  {_mask_key(env_cfg.api_key)}\\\")\\n            err_console.print()\\n            err_console.print(\\\"[bold]How to fix:[/bold]\\\")\\n            if key_env_name:\\n                err_console.print(\\\"  1. Open Langflow \u2192 Settings \u2192 API Keys \u2192 Create a new key\\\")\\n                err_console.print(f\\\"  2. [bold]export {key_env_name}=<your-new-key>[/bold]\\\")\\n            elif env_cfg.name not in (\\\"__inline__\\\", \\\"__env__\\\"):\\n                err_console.print(\\\"  1. Open Langflow \u2192 Settings \u2192 API Keys \u2192 Create a new key\\\")\\n                err_console.print(\\\"  2. Pass [bold]--api-key <key>[/bold] or configure api_key_env in your YAML\\\")\\n            else:\\n                err_console.print(\\\"  1. Open Langflow \u2192 Settings \u2192 API Keys \u2192 Create a new key\\\")\\n                err_console.print(\\\"  2. Pass [bold]--api-key <key>[/bold]\\\")\\n            raise typer.Exit(1)\\n\\n        if msg.startswith(\\\"connection:\\\"):\\n            err_console.print()\\n            err_console.print(\\\"[red bold]\u2717 Cannot connect.[/red bold]\\\")\\n            err_console.print(f\\\"  URL: {env_cfg.url}\\\")\\n            err_console.print()\\n            err_console.print(\\\"[bold]How to fix:[/bold]\\\")\\n            err_console.print(\\\"  \u2022 Make sure your Langflow instance is running\\\")\\n            err_console.print(\\\"  \u2022 Check the URL in your .lfx/environments.yaml\\\")\\n            err_console.print(\\\"  \u2022 If running locally: [bold]langflow run[/bold] or [bold]lfx serve <flow.json>[/bold]\\\")\\n            raise typer.Exit(1)\\n\\n        # Generic HTTP or other error\\n        err_console.print(f\\\"\\\\n[red bold]\u2717 Request failed:[/red bold] {msg.split(':', 1)[-1]}\\\")\\n        raise typer.Exit(1)\\n\\n    # ------------------------------------------------------------------\\n    # Success\\n    # ------------------------------------------------------------------\\n    masked_key = _mask_key(env_cfg.api_key) if env_cfg.api_key else \\\"[dim](none)[/dim]\\\"\\n\\n    key_source = \\\"\\\"\\n    if key_env_name and env_cfg.api_key:\\n        key_source = f\\\"  [dim]from env var {key_env_name}[/dim]\\\"\\n    elif os.environ.get(\\\"LANGFLOW_API_KEY\\\") == env_cfg.api_key and env_cfg.api_key:\\n        key_source = \\\"  [dim]from LANGFLOW_API_KEY[/dim]\\\"\\n\\n    env_label = env_cfg.name if env_cfg.name not in (\\\"__inline__\\\", \\\"__env__\\\") else \\\"(inline)\\\"\\n\\n    console.print()\\n    console.print(\\n        Panel.fit(\\n            f\\\"[bold green]\u2713 Connected successfully![/bold green]\\\\n\\\\n\\\"\\n            f\\\"[bold]Environment:[/bold] {env_label}\\\\n\\\"\\n            f\\\"[bold]URL:[/bold]         {env_cfg.url}\\\\n\\\"\\n            f\\\"[bold]API key:[/bold]     {masked_key}{key_source}\\\",\\n            title=\\\"[bold blue]lfx login[/bold blue]\\\",\\n            border_style=\\\"green\\\",\\n        )\\n    )\\n\\n    if not env_cfg.api_key:\\n        console.print()\\n        console.print(\\\"[dim]Note: connected without an API key (anonymous access).[/dim]\\\")\\n        console.print(\\\"[dim]Some operations may fail. Add api_key_env to your config.[/dim]\\\")\\n\\n    if env_cfg.name in (\\\"__inline__\\\", \\\"__env__\\\") and env_cfg.api_key:\\n        console.print()\\n        console.print(\\\"[dim]Tip: to avoid passing credentials each time, add to .lfx/environments.yaml:[/dim]\\\")\\n        env_display = env or \\\"myenv\\\"\\n        console.print(\\\"[dim]  environments:[/dim]\\\")\\n        console.print(f\\\"[dim]    {env_display}:[/dim]\\\")\\n        console.print(f\\\"[dim]      url: {env_cfg.url}[/dim]\\\")\\n        console.print(f\\\"[dim]      api_key_env: LANGFLOW_{env_display.upper()}_API_KEY[/dim]\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/pull.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d6ea3c0c32d3e99ff76a65afe8d7b0d7303d26c1d78b12aacd1abbfdc1ec8d5b\",\"content\":\"\\\"\\\"\\\"lfx pull -- fetch flows from a remote Langflow instance to local files.\\n\\nDownloads flows from a live Langflow instance, normalizes them for version\\ncontrol, and writes them to a local directory.  Repeated pulls are safe:\\nexisting files are overwritten with the latest remote state.\\n\\nUsage examples\\n--------------\\nPull all flows from staging to ``flows/``::\\n\\n    lfx pull --env staging\\n\\nPull all flows in a named project::\\n\\n    lfx pull --env staging --project \\\"My RAG Pipeline\\\"\\n\\nPull a single flow by UUID::\\n\\n    lfx pull --env staging --flow-id <uuid>\\n\\nPull to a custom directory::\\n\\n    lfx pull --env production --output-dir ./local-flows/\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom dataclasses import dataclass\\nfrom pathlib import Path\\nfrom typing import Any\\nfrom uuid import UUID\\n\\nimport typer\\nfrom rich.console import Console\\nfrom rich.table import Table\\n\\nfrom lfx.cli.common import load_sdk, safe_filename\\nfrom lfx.log.logger import logger\\n\\nconsole = Console(stderr=True)\\nok_console = Console()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Result types\\n# ---------------------------------------------------------------------------\\n\\n\\n@dataclass\\nclass PullResult:\\n    flow_id: UUID\\n    flow_name: str\\n    path: Path\\n    status: str  # \\\"unchanged\\\" | \\\"updated\\\" | \\\"created\\\" | \\\"error\\\"\\n    error: str | None = None\\n\\n    @property\\n    def ok(self) -> bool:\\n        return self.status != \\\"error\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _write_flow(\\n    flow_obj: Any,\\n    *,\\n    sdk: Any,\\n    dest_dir: Path,\\n    strip_secrets: bool,\\n    indent: int,\\n) -> PullResult:\\n    \\\"\\\"\\\"Normalize and write a single flow to *dest_dir*.\\\"\\\"\\\"\\n    flow_id = flow_obj.id\\n    flow_name = flow_obj.name\\n\\n    try:\\n        normalized = sdk.normalize_flow(\\n            flow_obj.model_dump(mode=\\\"json\\\"),\\n            strip_volatile=True,\\n            strip_secrets=strip_secrets,\\n            sort_keys=True,\\n        )\\n        safe_name = safe_filename(flow_name)\\n        out_path = dest_dir / f\\\"{safe_name}.json\\\"\\n        new_content = sdk.flow_to_json(normalized, indent=indent)\\n        if out_path.exists() and out_path.read_text(encoding=\\\"utf-8\\\") == new_content:\\n            status = \\\"unchanged\\\"\\n        else:\\n            status = \\\"created\\\" if not out_path.exists() else \\\"updated\\\"\\n            out_path.write_text(new_content, encoding=\\\"utf-8\\\")\\n        return PullResult(flow_id=flow_id, flow_name=flow_name, path=out_path, status=status)\\n    except Exception as exc:  # noqa: BLE001\\n        logger.debug(\\\"Failed to write flow %s\\\", flow_id, exc_info=True)\\n        dummy_path = dest_dir / f\\\"{flow_id}.json\\\"\\n        return PullResult(flow_id=flow_id, flow_name=flow_name, path=dummy_path, status=\\\"error\\\", error=str(exc))\\n\\n\\ndef _render_results(results: list[PullResult]) -> None:\\n    table = Table(show_header=True, header_style=\\\"bold\\\")\\n    table.add_column(\\\"Name\\\")\\n    table.add_column(\\\"ID\\\")\\n    table.add_column(\\\"File\\\")\\n    table.add_column(\\\"Status\\\")\\n\\n    status_style = {\\n        \\\"unchanged\\\": (\\\"dim\\\", \\\"UNCHANGED\\\"),\\n        \\\"updated\\\": (\\\"yellow\\\", \\\"UPDATED\\\"),\\n        \\\"created\\\": (\\\"green\\\", \\\"CREATED\\\"),\\n        \\\"error\\\": (\\\"red\\\", \\\"ERROR\\\"),\\n    }\\n\\n    for r in results:\\n        color, label = status_style.get(r.status, (\\\"white\\\", r.status.upper()))\\n        if r.error:\\n            label += f\\\": {r.error}\\\"\\n        table.add_row(r.flow_name, str(r.flow_id), str(r.path), f\\\"[{color}]{label}[/{color}]\\\")\\n\\n    ok_console.print()\\n    ok_console.print(table)\\n\\n    errors = [r for r in results if not r.ok]\\n    n_changed = sum(1 for r in results if r.status in (\\\"created\\\", \\\"updated\\\"))\\n    n_unchanged = sum(1 for r in results if r.status == \\\"unchanged\\\")\\n    if errors:\\n        console.print(f\\\"\\\\n[red]{len(errors)} pull(s) failed.[/red]\\\")\\n    else:\\n        parts = []\\n        if n_changed:\\n            parts.append(f\\\"[green]{n_changed} updated[/green]\\\")\\n        if n_unchanged:\\n            parts.append(f\\\"[dim]{n_unchanged} unchanged[/dim]\\\")\\n        ok_console.print(\\\"\\\\n\\\" + \\\", \\\".join(parts) + \\\".\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# CLI entry point\\n# ---------------------------------------------------------------------------\\n\\n\\ndef pull_command(\\n    *,\\n    env: str | None,\\n    output_dir: str | None,\\n    flow_id: str | None,\\n    project: str | None,\\n    project_id: str | None,\\n    environments_file: str | None,\\n    target: str | None = None,\\n    api_key: str | None = None,\\n    strip_secrets: bool,\\n    indent: int,\\n) -> None:\\n    sdk = load_sdk(\\\"pull\\\")\\n\\n    from lfx.config import ConfigError, resolve_environment\\n\\n    try:\\n        env_cfg = resolve_environment(\\n            env,\\n            target=target,\\n            api_key=api_key,\\n            environments_file=environments_file,\\n        )\\n    except ConfigError as exc:\\n        console.print(f\\\"[red]Error:[/red] {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n    client = sdk.Client(base_url=env_cfg.url, api_key=env_cfg.api_key)\\n\\n    dest_dir = Path(output_dir) if output_dir else Path(\\\"flows\\\")\\n    dest_dir.mkdir(parents=True, exist_ok=True)\\n\\n    results: list[PullResult] = []\\n\\n    # ---- Single flow by ID -----------------------------------------------\\n    if flow_id:\\n        try:\\n            flow_obj = client.get_flow(UUID(flow_id))\\n        except Exception as exc:\\n            console.print(f\\\"[red]Error:[/red] Could not fetch flow {flow_id}: {exc}\\\")\\n            raise typer.Exit(1) from exc\\n\\n        result = _write_flow(flow_obj, sdk=sdk, dest_dir=dest_dir, strip_secrets=strip_secrets, indent=indent)\\n        results.append(result)\\n        if result.ok:\\n            console.print(f\\\"[green]Pulled[/green] {result.flow_name!r} \u2192 {result.path}\\\")\\n        else:\\n            console.print(f\\\"[red]Failed[/red] {result.flow_name!r}: {result.error}\\\")\\n\\n    # ---- All flows in a named project ------------------------------------\\n    elif project or project_id:\\n        if project_id:\\n            try:\\n                proj = client.get_project(UUID(project_id))\\n            except Exception as exc:\\n                console.print(f\\\"[red]Error:[/red] Could not fetch project {project_id}: {exc}\\\")\\n                raise typer.Exit(1) from exc\\n        else:\\n            projects = client.list_projects()\\n            matched = [p for p in projects if p.name == project]\\n            if not matched:\\n                names = \\\", \\\".join(repr(p.name) for p in projects) or \\\"(none)\\\"\\n                console.print(f\\\"[red]Error:[/red] Project {project!r} not found. Available: {names}\\\")\\n                raise typer.Exit(1)\\n            try:\\n                proj = client.get_project(matched[0].id)\\n            except Exception as exc:\\n                console.print(f\\\"[red]Error:[/red] Could not fetch project {project!r}: {exc}\\\")\\n                raise typer.Exit(1) from exc\\n\\n        console.print(f\\\"[dim]Pulling from project[/dim] {proj.name!r} (id={proj.id})\\\")\\n\\n        for flow_obj in proj.flows:\\n            result = _write_flow(flow_obj, sdk=sdk, dest_dir=dest_dir, strip_secrets=strip_secrets, indent=indent)\\n            results.append(result)\\n            if result.status == \\\"unchanged\\\":\\n                console.print(f\\\"[dim]Unchanged[/dim] {result.flow_name!r}\\\")\\n            elif result.ok:\\n                console.print(f\\\"[green]Pulled[/green] {result.flow_name!r} \u2192 {result.path}\\\")\\n            else:\\n                console.print(f\\\"[red]Failed[/red] {result.flow_name!r}: {result.error}\\\")\\n\\n    # ---- All flows in the environment ------------------------------------\\n    else:\\n        console.print(f\\\"[dim]Pulling all flows from[/dim] {env_cfg.url}\\\")\\n        try:\\n            flows = client.list_flows(get_all=True, remove_example_flows=True)\\n        except Exception as exc:\\n            console.print(f\\\"[red]Error:[/red] Could not list flows: {exc}\\\")\\n            raise typer.Exit(1) from exc\\n\\n        if not flows:\\n            console.print(\\\"[yellow]Warning:[/yellow] No flows found on the remote instance.\\\")\\n            return\\n\\n        for flow_obj in flows:\\n            result = _write_flow(flow_obj, sdk=sdk, dest_dir=dest_dir, strip_secrets=strip_secrets, indent=indent)\\n            results.append(result)\\n            if result.status == \\\"unchanged\\\":\\n                console.print(f\\\"[dim]Unchanged[/dim] {result.flow_name!r}\\\")\\n            elif result.ok:\\n                console.print(f\\\"[green]Pulled[/green] {result.flow_name!r} \u2192 {result.path}\\\")\\n            else:\\n                console.print(f\\\"[red]Failed[/red] {result.flow_name!r}: {result.error}\\\")\\n\\n    _render_results(results)\\n\\n    if any(not r.ok for r in results):\\n        raise typer.Exit(1)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/push.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d244bac903a4590b67a54ae96e3509da84d8ae92fc12e7bdf5b14b74ea3441e2\",\"content\":\"\\\"\\\"\\\"lfx push -- push normalized flow JSON to a remote Langflow instance.\\n\\nUses stable flow IDs for upsert (PUT /api/v1/flows/{id}), so repeated pushes\\nare idempotent: the first push creates the flow, subsequent ones update it in\\nplace without changing its ID on the remote instance.\\n\\nUsage examples\\n--------------\\nPush a single flow to staging::\\n\\n    lfx push my_flow.json --env staging\\n\\nPush several flows at once::\\n\\n    lfx push flows/*.json --env staging\\n\\nPush all flows in a directory and place them in a named project::\\n\\n    lfx push --dir ./flows/ --env staging --project \\\"My RAG Pipeline\\\"\\n\\nDry-run to see what would happen::\\n\\n    lfx push ./flows/ --env production --dry-run\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom dataclasses import dataclass\\nfrom pathlib import Path\\nfrom typing import Any\\nfrom uuid import UUID\\n\\nimport typer\\nfrom rich.console import Console\\nfrom rich.table import Table\\n\\nfrom lfx.cli.common import load_sdk\\n\\nconsole = Console(stderr=True)\\nok_console = Console()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Result types\\n# ---------------------------------------------------------------------------\\n\\n\\n@dataclass\\nclass PushResult:\\n    path: Path\\n    flow_id: UUID\\n    flow_name: str\\n    status: str  # \\\"created\\\" | \\\"updated\\\" | \\\"unchanged\\\" | \\\"error\\\" | \\\"dry-run\\\"\\n    error: str | None = None\\n    flow_url: str | None = None\\n\\n    @property\\n    def ok(self) -> bool:\\n        return self.status in (\\\"created\\\", \\\"updated\\\", \\\"unchanged\\\", \\\"dry-run\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _load_flow_file(path: Path) -> dict[str, Any]:\\n    \\\"\\\"\\\"Read and parse a flow JSON file; raise Exit on error.\\\"\\\"\\\"\\n    try:\\n        return json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n    except (OSError, json.JSONDecodeError) as exc:\\n        console.print(f\\\"[red]Error:[/red] Cannot read {path}: {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n\\ndef _extract_flow_id(flow: dict[str, Any], path: Path) -> UUID:\\n    \\\"\\\"\\\"Extract and validate the flow's stable ID from the JSON.\\\"\\\"\\\"\\n    raw_id = flow.get(\\\"id\\\")\\n    if not raw_id:\\n        console.print(f\\\"[red]Error:[/red] {path} has no 'id' field. Run [bold]lfx export[/bold] first.\\\")\\n        raise typer.Exit(1)\\n    try:\\n        return UUID(str(raw_id))\\n    except ValueError:\\n        console.print(f\\\"[red]Error:[/red] {path} has an invalid 'id': {raw_id!r}\\\")\\n        raise typer.Exit(1)  # noqa: B904\\n\\n\\ndef _flow_to_create(sdk: Any, flow: dict[str, Any], folder_id: UUID | None) -> Any:\\n    \\\"\\\"\\\"Build a FlowCreate from a normalized flow dict.\\\"\\\"\\\"\\n    return sdk.FlowCreate(\\n        name=flow.get(\\\"name\\\", \\\"Untitled\\\"),\\n        description=flow.get(\\\"description\\\"),\\n        data=flow.get(\\\"data\\\"),\\n        is_component=flow.get(\\\"is_component\\\", False),\\n        endpoint_name=flow.get(\\\"endpoint_name\\\"),\\n        tags=flow.get(\\\"tags\\\"),\\n        folder_id=folder_id or (UUID(flow[\\\"folder_id\\\"]) if flow.get(\\\"folder_id\\\") else None),\\n        icon=flow.get(\\\"icon\\\"),\\n        icon_bg_color=flow.get(\\\"icon_bg_color\\\"),\\n        locked=flow.get(\\\"locked\\\", False),\\n        mcp_enabled=flow.get(\\\"mcp_enabled\\\", False),\\n    )\\n\\n\\ndef _upsert_single(\\n    client: Any,\\n    sdk: Any,\\n    path: Path,\\n    flow_id: UUID,\\n    flow_create: Any,\\n    *,\\n    dry_run: bool,\\n    flow_name: str,\\n    base_url: str,\\n    local_file_content: str | None = None,\\n    strip_secrets: bool = True,\\n) -> PushResult:\\n    flow_url = f\\\"{base_url.rstrip('/')}/flow/{flow_id}\\\"\\n\\n    if dry_run:\\n        return PushResult(path=path, flow_id=flow_id, flow_name=flow_name, status=\\\"dry-run\\\", flow_url=flow_url)\\n\\n    # Compare normalized remote against local file to detect unchanged flows,\\n    # avoiding a spurious PUT when nothing has actually changed.\\n    # Import directly from serialization so this internal comparison is not\\n    # counted as a call to the public sdk.normalize_flow (keeps tests clean).\\n    if local_file_content is not None:\\n        try:\\n            # Use direct module imports (not sdk.*) so mock call-counts in tests\\n            # stay accurate and so the except clause uses a real exception class.\\n            from langflow_sdk.exceptions import LangflowNotFoundError\\n            from langflow_sdk.serialization import flow_to_json, normalize_flow\\n\\n            remote = client.get_flow(flow_id)\\n            remote_normalized = normalize_flow(\\n                remote.model_dump(mode=\\\"json\\\"),\\n                strip_volatile=True,\\n                strip_secrets=strip_secrets,\\n                sort_keys=True,\\n            )\\n            if flow_to_json(remote_normalized) == local_file_content:\\n                return PushResult(\\n                    path=path,\\n                    flow_id=flow_id,\\n                    flow_name=flow_name,\\n                    status=\\\"unchanged\\\",\\n                    flow_url=flow_url,\\n                )\\n        except LangflowNotFoundError:\\n            pass  # Flow doesn't exist yet \u2014 fall through to create it\\n        except Exception:  # noqa: BLE001\\n            import logging\\n\\n            logging.getLogger(__name__).debug(\\\"Remote comparison failed; proceeding with push\\\", exc_info=True)\\n\\n    try:\\n        _, created = client.upsert_flow(flow_id, flow_create)\\n        status = \\\"created\\\" if created else \\\"updated\\\"\\n        return PushResult(path=path, flow_id=flow_id, flow_name=flow_name, status=status, flow_url=flow_url)\\n    except sdk.LangflowHTTPError as exc:\\n        return PushResult(\\n            path=path,\\n            flow_id=flow_id,\\n            flow_name=flow_name,\\n            status=\\\"error\\\",\\n            error=str(exc),\\n            flow_url=flow_url,\\n        )\\n\\n\\ndef _find_or_create_project(\\n    client: Any,\\n    sdk: Any,\\n    project_name: str,\\n    *,\\n    dry_run: bool,\\n) -> UUID | None:\\n    \\\"\\\"\\\"Return the UUID of a project with *project_name*, creating if needed.\\n\\n    Returns ``None`` in dry-run mode (project may not exist yet).\\n    \\\"\\\"\\\"\\n    projects = client.list_projects()\\n    for p in projects:\\n        if p.name == project_name:\\n            console.print(f\\\"[dim]Project[/dim] {project_name!r} found (id={p.id})\\\")\\n            return p.id\\n\\n    if dry_run:\\n        console.print(f\\\"[dim]Project[/dim] {project_name!r} would be created (dry-run)\\\")\\n        return None\\n\\n    project = client.create_project(sdk.ProjectCreate(name=project_name))\\n    console.print(f\\\"[green]Created project[/green] {project_name!r} (id={project.id})\\\")\\n    return project.id\\n\\n\\ndef _find_project_root() -> Path | None:\\n    \\\"\\\"\\\"Return the lfx project root (directory containing .lfx/), or None.\\n\\n    Only the ``.lfx`` marker is used \u2014 ``.git`` is intentionally excluded so\\n    that the containment check doesn't reject paths when running inside a\\n    larger monorepo or outside any lfx project.\\n    \\\"\\\"\\\"\\n    cwd = Path.cwd()\\n    for directory in (cwd, *cwd.parents):\\n        if (directory / \\\".lfx\\\").is_dir():\\n            return directory\\n        # Stop at a filesystem root\\n        if directory.parent == directory:\\n            break\\n    return None\\n\\n\\ndef _check_path_containment(p: Path, root: Path | None) -> None:\\n    \\\"\\\"\\\"Ensure *p* is inside *root*; skip check when no project root is found.\\\"\\\"\\\"\\n    if root is None:\\n        return\\n    try:\\n        p.resolve().relative_to(root.resolve())\\n    except ValueError:\\n        console.print(\\n            f\\\"[red]Error:[/red] Path {p} is outside the project root ({root}). \\\"\\n            \\\"Refusing to push files from outside the project.\\\"\\n        )\\n        raise typer.Exit(1)  # noqa: B904\\n\\n\\ndef _collect_flow_files(sources: list[str], dir_path: str | None) -> list[Path]:\\n    \\\"\\\"\\\"Resolve the set of flow JSON files to push.\\n\\n    When neither explicit file paths nor ``--dir`` are given, defaults to\\n    ``flows/`` \u2014 mirroring the behaviour of ``lfx pull``.\\n    \\\"\\\"\\\"\\n    paths: list[Path] = []\\n    root = _find_project_root()\\n\\n    # Default to flows/ when nothing is specified, just like lfx pull does.\\n    effective_dir = dir_path or (None if sources else \\\"flows\\\")\\n\\n    if effective_dir:\\n        d = Path(effective_dir)\\n        _check_path_containment(d, root)\\n        if not d.is_dir():\\n            console.print(f\\\"[red]Error:[/red] Directory not found: {d}\\\")\\n            raise typer.Exit(1)\\n        paths.extend(sorted(d.glob(\\\"*.json\\\")))\\n        if not paths:\\n            console.print(f\\\"[yellow]Warning:[/yellow] No *.json files found in {d}\\\")\\n\\n    for s in sources:\\n        p = Path(s)\\n        _check_path_containment(p, root)\\n        if not p.exists():\\n            console.print(f\\\"[red]Error:[/red] File not found: {p}\\\")\\n            raise typer.Exit(1)\\n        if p.is_dir():\\n            dir_jsons = sorted(p.glob(\\\"*.json\\\"))\\n            if not dir_jsons:\\n                console.print(f\\\"[yellow]Warning:[/yellow] No *.json files found in {p}\\\")\\n            paths.extend(dir_jsons)\\n        else:\\n            paths.append(p)\\n\\n    return paths\\n\\n\\ndef _render_results(results: list[PushResult], *, dry_run: bool) -> None:\\n    table = Table(show_header=True, header_style=\\\"bold\\\")\\n    table.add_column(\\\"File\\\")\\n    table.add_column(\\\"Name\\\")\\n    table.add_column(\\\"ID\\\")\\n    table.add_column(\\\"Status\\\")\\n    table.add_column(\\\"URL\\\")\\n\\n    status_colors = {\\n        \\\"created\\\": \\\"green\\\",\\n        \\\"updated\\\": \\\"cyan\\\",\\n        \\\"unchanged\\\": \\\"dim\\\",\\n        \\\"dry-run\\\": \\\"yellow\\\",\\n        \\\"error\\\": \\\"red\\\",\\n    }\\n\\n    for r in results:\\n        color = status_colors.get(r.status, \\\"white\\\")\\n        label = r.status.upper() + (f\\\": {r.error}\\\" if r.error else \\\"\\\")\\n        url_cell = f\\\"[blue]{r.flow_url}[/blue]\\\" if r.flow_url and r.ok else (r.flow_url or \\\"\\\")\\n        table.add_row(\\n            str(r.path),\\n            r.flow_name,\\n            str(r.flow_id),\\n            f\\\"[{color}]{label}[/{color}]\\\",\\n            url_cell,\\n        )\\n\\n    ok_console.print()\\n    ok_console.print(table)\\n\\n    errors = [r for r in results if not r.ok]\\n    if errors:\\n        console.print(f\\\"\\\\n[red]{len(errors)} push(es) failed.[/red]\\\")\\n    elif dry_run:\\n        ok_console.print(f\\\"\\\\n[yellow]{len(results)} flow(s) would be pushed (dry-run).[/yellow]\\\")\\n    else:\\n        created = sum(1 for r in results if r.status == \\\"created\\\")\\n        updated = sum(1 for r in results if r.status == \\\"updated\\\")\\n        unchanged = sum(1 for r in results if r.status == \\\"unchanged\\\")\\n        parts = []\\n        if created:\\n            parts.append(f\\\"[green]{created} created[/green]\\\")\\n        if updated:\\n            parts.append(f\\\"[cyan]{updated} updated[/cyan]\\\")\\n        if unchanged:\\n            parts.append(f\\\"[dim]{unchanged} unchanged[/dim]\\\")\\n        ok_console.print(\\\"\\\\n\\\" + \\\", \\\".join(parts) + \\\".\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# CLI entry point\\n# ---------------------------------------------------------------------------\\n\\n\\ndef push_command(\\n    flow_paths: list[str],\\n    *,\\n    env: str | None,\\n    dir_path: str | None,\\n    project: str | None,\\n    project_id: str | None,\\n    environments_file: str | None,\\n    target: str | None = None,\\n    api_key: str | None = None,\\n    dry_run: bool,\\n    normalize: bool,\\n    strip_secrets: bool,\\n) -> None:\\n    sdk = load_sdk(\\\"push\\\")\\n\\n    from lfx.config import ConfigError, resolve_environment\\n\\n    try:\\n        env_cfg = resolve_environment(\\n            env,\\n            target=target,\\n            api_key=api_key,\\n            environments_file=environments_file,\\n        )\\n    except ConfigError as exc:\\n        console.print(f\\\"[red]Error:[/red] {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n    client = sdk.Client(base_url=env_cfg.url, api_key=env_cfg.api_key)\\n\\n    paths = _collect_flow_files(flow_paths, dir_path)\\n    if not paths:\\n        console.print(\\n            \\\"[red]Error:[/red] No *.json flow files found. \\\"\\n            \\\"Run [bold]lfx pull[/bold] first, or pass explicit file paths.\\\"\\n        )\\n        raise typer.Exit(1)\\n\\n    # Resolve target project folder_id\\n    target_folder_id: UUID | None = None\\n    if project_id:\\n        target_folder_id = UUID(project_id)\\n    elif project:\\n        target_folder_id = _find_or_create_project(client, sdk, project, dry_run=dry_run)\\n\\n    results: list[PushResult] = []\\n\\n    for path in paths:\\n        raw_flow = _load_flow_file(path)\\n\\n        if normalize:\\n            raw_flow = sdk.normalize_flow(\\n                raw_flow,\\n                strip_volatile=True,\\n                strip_secrets=strip_secrets,\\n                sort_keys=True,\\n            )\\n\\n        flow_id = _extract_flow_id(raw_flow, path)\\n        flow_name = raw_flow.get(\\\"name\\\", path.stem)\\n        flow_create = _flow_to_create(sdk, raw_flow, target_folder_id)\\n        # Capture normalized content now so _upsert_single can compare against remote.\\n        local_file_content = sdk.flow_to_json(raw_flow) if normalize else None\\n\\n        result = _upsert_single(\\n            client,\\n            sdk,\\n            path,\\n            flow_id,\\n            flow_create,\\n            dry_run=dry_run,\\n            flow_name=flow_name,\\n            base_url=env_cfg.url,\\n            local_file_content=local_file_content,\\n            strip_secrets=strip_secrets,\\n        )\\n        results.append(result)\\n\\n        if dry_run:\\n            console.print(f\\\"[yellow]DRY-RUN[/yellow] Would push {flow_name!r} ({flow_id})\\\")\\n        elif result.status == \\\"unchanged\\\":\\n            console.print(f\\\"[dim]Unchanged[/dim] {flow_name!r}\\\")\\n        elif result.status == \\\"created\\\":\\n            url_hint = f\\\"  [dim]{result.flow_url}[/dim]\\\" if result.flow_url else \\\"\\\"\\n            console.print(f\\\"[green]Created[/green]  {flow_name!r} ({flow_id}){url_hint}\\\")\\n        elif result.status == \\\"updated\\\":\\n            url_hint = f\\\"  [dim]{result.flow_url}[/dim]\\\" if result.flow_url else \\\"\\\"\\n            console.print(f\\\"[cyan]Updated[/cyan]  {flow_name!r} ({flow_id}){url_hint}\\\")\\n        else:\\n            console.print(f\\\"[red]Failed[/red]   {flow_name!r} ({flow_id}): {result.error}\\\")\\n\\n    _render_results(results, dry_run=dry_run)\\n\\n    if any(not r.ok for r in results):\\n        raise typer.Exit(1)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/run.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b34b450c29c2fa1d212bf1eecb7d1964ffc8f530079a56806bdc1946a7e0c734\",\"content\":\"\\\"\\\"\\\"CLI wrapper for the run command.\\\"\\\"\\\"\\n\\nimport asyncio\\nimport json\\nfrom functools import partial\\nfrom pathlib import Path\\n\\nimport typer\\nfrom asyncer import syncify\\n\\nfrom lfx.observability import bootstrap_application_telemetry, execution_protocol\\nfrom lfx.run.base import RunError, run_flow\\n\\n# Verbosity level constants\\nVERBOSITY_DETAILED = 2\\nVERBOSITY_FULL = 3\\n\\n\\ndef _check_langchain_version_compatibility(error_message: str) -> str | None:\\n    \\\"\\\"\\\"Check if error is due to langchain-core version incompatibility.\\n\\n    Returns a helpful error message if incompatibility is detected, None otherwise.\\n    \\\"\\\"\\\"\\n    # Check for the specific error that occurs with langchain-core 1.x\\n    # The langchain_core.memory module was removed in langchain-core 1.x\\n    if \\\"langchain_core.memory\\\" in error_message or \\\"No module named 'langchain_core.memory'\\\" in error_message:\\n        try:\\n            import langchain_core\\n\\n            version = getattr(langchain_core, \\\"__version__\\\", \\\"unknown\\\")\\n        except ImportError:\\n            version = \\\"unknown\\\"\\n\\n        return (\\n            f\\\"ERROR: Incompatible langchain-core version (v{version}).\\\\n\\\\n\\\"\\n            \\\"The 'langchain_core.memory' module was removed in langchain-core 1.x.\\\\n\\\"\\n            \\\"lfx requires langchain-core < 1.0.0.\\\\n\\\\n\\\"\\n            \\\"This usually happens when langchain-openai >= 1.0.0 is installed,\\\\n\\\"\\n            \\\"which pulls in langchain-core >= 1.0.0.\\\\n\\\\n\\\"\\n            \\\"FIX: Reinstall with compatible versions:\\\\n\\\\n\\\"\\n            \\\"  uv pip install 'langchain-core>=0.3.0,<1.0.0' \\\\\\\\\\\\n\\\"\\n            \\\"                 'langchain-openai>=0.3.0,<1.0.0' \\\\\\\\\\\\n\\\"\\n            \\\"                 'langchain-community>=0.3.0,<1.0.0'\\\\n\\\\n\\\"\\n            \\\"Or with pip:\\\\n\\\\n\\\"\\n            \\\"  pip install 'langchain-core>=0.3.0,<1.0.0' \\\\\\\\\\\\n\\\"\\n            \\\"              'langchain-openai>=0.3.0,<1.0.0' \\\\\\\\\\\\n\\\"\\n            \\\"              'langchain-community>=0.3.0,<1.0.0'\\\"\\n        )\\n    return None\\n\\n\\n@partial(syncify, raise_sync_error=False)\\nasync def run(\\n    script_path: Path | None = typer.Argument(\\n        None, help=\\\"Path to the Python script (.py) or JSON flow (.json) containing a graph\\\"\\n    ),\\n    input_value: str | None = typer.Argument(None, help=\\\"Input value to pass to the graph\\\"),\\n    input_value_option: str | None = typer.Option(\\n        None,\\n        \\\"--input-value\\\",\\n        help=\\\"Input value to pass to the graph (alternative to positional argument)\\\",\\n    ),\\n    output_format: str = typer.Option(\\n        \\\"json\\\",\\n        \\\"--format\\\",\\n        \\\"-f\\\",\\n        help=\\\"Output format: json, text, message, or result\\\",\\n    ),\\n    flow_json: str | None = typer.Option(\\n        None,\\n        \\\"--flow-json\\\",\\n        help=(\\\"Inline JSON flow content as a string (alternative to script_path)\\\"),\\n    ),\\n    *,\\n    stdin: bool | None = typer.Option(\\n        default=False,\\n        flag_value=\\\"--stdin\\\",\\n        show_default=True,\\n        help=\\\"Read JSON flow content from stdin (alternative to script_path)\\\",\\n    ),\\n    check_variables: bool = typer.Option(\\n        default=True,\\n        show_default=True,\\n        help=\\\"Check global variables for environment compatibility\\\",\\n    ),\\n    check_dependencies: bool = typer.Option(\\n        default=True,\\n        show_default=True,\\n        help=\\\"Preflight the flow's required packages; fail fast with install guidance when any are missing\\\",\\n    ),\\n    verbose: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"-v\\\",\\n        \\\"--verbose\\\",\\n        help=\\\"Show basic progress information\\\",\\n    ),\\n    verbose_detailed: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"-vv\\\",\\n        help=\\\"Show detailed progress and debug information\\\",\\n    ),\\n    verbose_full: bool = typer.Option(\\n        False,  # noqa: FBT003\\n        \\\"-vvv\\\",\\n        help=\\\"Show full debugging output including component logs\\\",\\n    ),\\n    timing: bool = typer.Option(\\n        default=False,\\n        show_default=True,\\n        help=\\\"Include detailed timing information in output\\\",\\n    ),\\n    session_id: str | None = typer.Option(\\n        None,\\n        \\\"--session-id\\\",\\n        help=(\\n            \\\"Session ID to attach to the run. Agent and Memory Components will use this to track conversation history.\\\"\\n        ),\\n    ),\\n    upgrade_flow: str | None = None,\\n    human_input: bool | None = typer.Option(\\n        None,\\n        \\\"--human-input/--no-human-input\\\",\\n        help=(\\n            \\\"Interactive human-in-the-loop. Default auto-enables it when the flow has a \\\"\\n            \\\"pausing node (e.g. HumanInput) and the terminal is interactive; the run then \\\"\\n            \\\"prompts at each pause. Use --no-human-input to disable. Interactive-session \\\"\\n            \\\"only: checkpoints are in-memory, so a paused run cannot be resumed later or \\\"\\n            \\\"from another process. Non-interactive runs do not pause (a warning is printed).\\\"\\n        ),\\n    ),\\n) -> None:\\n    \\\"\\\"\\\"Execute a Langflow graph script or JSON flow and return the result.\\n\\n    This command analyzes and executes either a Python script containing a Langflow graph,\\n    a JSON flow file, inline JSON, or JSON from stdin, returning the result in the specified format.\\n    By default, output is minimal for use in containers and serverless environments.\\n\\n    Args:\\n        script_path: Path to the Python script (.py) or JSON flow (.json) containing a graph\\n        input_value: Input value to pass to the graph (positional argument)\\n        input_value_option: Input value to pass to the graph (alternative option)\\n        verbose: Show diagnostic output and execution details\\n        verbose_detailed: Show detailed progress and debug information (-vv)\\n        verbose_full: Show full debugging output including component logs (-vvv)\\n        output_format: Format for output (json, text, message, or result)\\n        flow_json: Inline JSON flow content as a string\\n        stdin: Read JSON flow content from stdin\\n        check_variables: Check global variables for environment compatibility\\n        check_dependencies: Preflight required packages and fail fast when any are missing\\n        timing: Include detailed timing information in output\\n        session_id: Optional session ID; auto-generated if not supplied\\n        upgrade_flow: Component compatibility mode ('check' or 'safe')\\n        human_input: Interactive human-in-the-loop (None auto-detects; True/False force)\\n    \\\"\\\"\\\"\\n    # Determine verbosity for output formatting\\n    verbosity = 3 if verbose_full else (2 if verbose_detailed else (1 if verbose else 0))\\n\\n    # Application observability for the one-shot surface. ``lfx serve`` and the langflow server\\n    # install the OTLP providers from the standard OTEL_* environment variables at boot; this is\\n    # the same call, made here because nothing else on this path makes it. Without it the\\n    # ``flow.execute`` span the graph emits lands on OpenTelemetry's no-op proxy provider and is\\n    # discarded, and an operator who wired ``lfx run`` (a cron job, a CI step, a batch worker)\\n    # into their APM has a blind surface with no warning. A no-op when no endpoint is set, or\\n    # when lfx was installed without the ``otel`` extra, so the default path costs nothing.\\n    telemetry = bootstrap_application_telemetry()\\n    try:\\n        # The whole one-shot run happens inside this await, including the graph's own span.\\n        with execution_protocol(\\\"lfx.run\\\"):\\n            result = await run_flow(\\n                script_path=script_path,\\n                input_value=input_value,\\n                input_value_option=input_value_option,\\n                output_format=output_format,\\n                flow_json=flow_json,\\n                stdin=bool(stdin),\\n                check_variables=check_variables,\\n                check_dependencies=check_dependencies,\\n                verbose=verbose,\\n                verbose_detailed=verbose_detailed,\\n                verbose_full=verbose_full,\\n                timing=timing,\\n                global_variables=None,\\n                session_id=session_id,\\n                upgrade_flow=upgrade_flow,\\n                human_input=human_input,\\n            )\\n\\n        # Output based on format\\n        if output_format in {\\\"text\\\", \\\"message\\\", \\\"result\\\"}:\\n            typer.echo(result.get(\\\"output\\\", \\\"\\\"))\\n        else:\\n            indent = 2 if verbosity > 0 else None\\n            typer.echo(json.dumps(result, indent=indent))\\n\\n    except RunError as e:\\n        error_response = {\\n            \\\"success\\\": False,\\n            \\\"type\\\": \\\"error\\\",\\n        }\\n        if e.original_exception:\\n            error_response[\\\"exception_type\\\"] = type(e.original_exception).__name__\\n            error_response[\\\"exception_message\\\"] = str(e.original_exception)\\n        else:\\n            error_response[\\\"exception_message\\\"] = str(e)\\n        typer.echo(json.dumps(error_response))\\n        raise typer.Exit(1) from e\\n    finally:\\n        # This process owns the telemetry lifetime, so it flushes on the way out: the span is\\n        # sitting in the batch processor when the run ends, and the process exits right after.\\n        # On every exit path, because a failed run's ``status=error`` span is the one an\\n        # operator most needs to see. After the result has been echoed, so a consumer reading\\n        # stdout is never held behind the export, which blocks on the network (up to the OTLP\\n        # timeout when the collector is unreachable). Off the event loop for the same reason.\\n        await asyncio.to_thread(telemetry.shutdown)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/runtime_variables.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"95a62b9e24a9622cd4afc786b10093b138f312779ecdb57ed9126b6cc2ba6a39\",\"content\":\"\\\"\\\"\\\"Normalize runtime ``global_vars`` payloads (WXO ADK / TRM contract).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.log.logger import logger\\nfrom lfx.services.variable.request_scope import normalize_parsed_variables\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n\\n_LANGFLOW_REQUEST_VARIABLES_KEY = \\\"LANGFLOW_REQUEST_VARIABLES\\\"\\n\\n\\ndef build_request_variables_from_global_vars(global_vars: dict[str, str] | None) -> dict[str, str]:\\n    \\\"\\\"\\\"Flatten TRM-style ``global_vars`` into a single lookup map.\\n\\n    TRM sends:\\n    - ``LANGFLOW_REQUEST_VARIABLES``: JSON blob of merged context + connection_details\\n    - raw credential keys (e.g. ``access_token``, ``wxo_github_access_token``)\\n    - ``x-langflow-global-var-*`` aliases\\n\\n    Parsed JSON is applied first; explicit keys in *global_vars* (except the JSON\\n    blob key itself) override on collision. Under the TRM contract connection_details\\n    is sent as raw keys and context inside the JSON blob, so connection_details wins.\\n    \\\"\\\"\\\"\\n    if not global_vars:\\n        return {}\\n\\n    merged: dict[str, str] = {}\\n    raw_json = global_vars.get(_LANGFLOW_REQUEST_VARIABLES_KEY)\\n    if raw_json:\\n        try:\\n            parsed = json.loads(raw_json)\\n        except json.JSONDecodeError as exc:\\n            logger.warning(\\n                f\\\"Failed to parse {_LANGFLOW_REQUEST_VARIABLES_KEY} JSON ({exc}); \\\"\\n                \\\"credentials carried only in this blob will be unavailable.\\\"\\n            )\\n            parsed = None\\n        if isinstance(parsed, dict):\\n            merged.update(normalize_parsed_variables(parsed))\\n        elif parsed is not None:\\n            logger.warning(\\n                f\\\"{_LANGFLOW_REQUEST_VARIABLES_KEY} must be a JSON object, got {type(parsed).__name__}; ignoring blob.\\\"\\n            )\\n\\n    for key, value in global_vars.items():\\n        if key == _LANGFLOW_REQUEST_VARIABLES_KEY:\\n            continue\\n        normalized = key.strip() if isinstance(key, str) else \\\"\\\"\\n        if normalized:\\n            merged[normalized] = str(value)\\n\\n    return merged\\n\\n\\ndef apply_global_vars_to_graph(graph: Graph, global_vars: dict[str, str] | None) -> None:\\n    \\\"\\\"\\\"Inject *global_vars* into ``graph.context['request_variables']``.\\\"\\\"\\\"\\n    if not global_vars:\\n        return\\n    if \\\"request_variables\\\" not in graph.context:\\n        graph.context[\\\"request_variables\\\"] = {}\\n    # Flatten the LANGFLOW_REQUEST_VARIABLES blob here so the no-DB load_from_db path\\n    # (load_from_env_vars reads graph.context) resolves the same names as the\\n    # VariableService/ContextVar path (common.py) \u2014 otherwise a caller sending a credential\\n    # only inside the JSON blob would resolve on one path and return None on the other.\\n    graph.context[\\\"request_variables\\\"].update(build_request_variables_from_global_vars(global_vars))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/script_loader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cb240d12011a0015989841e1e27375174fa8cccc52fc0b44a7bc53155adcf698\",\"content\":\"\\\"\\\"\\\"Script loading utilities for LFX CLI.\\n\\nThis module provides functionality to load and validate Python scripts\\ncontaining LFX graph variables.\\n\\\"\\\"\\\"\\n\\nimport ast\\nimport importlib.util\\nimport inspect\\nimport json\\nimport sys\\nfrom contextlib import contextmanager\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Any\\n\\nimport typer\\n\\nif TYPE_CHECKING:\\n    from lfx.graph import Graph\\n    from lfx.schema.message import Message\\n\\n\\n@contextmanager\\ndef temporary_sys_path(path: str):\\n    \\\"\\\"\\\"Temporarily add a path to sys.path.\\\"\\\"\\\"\\n    if path not in sys.path:\\n        sys.path.insert(0, path)\\n        try:\\n            yield\\n        finally:\\n            sys.path.remove(path)\\n    else:\\n        yield\\n\\n\\ndef _load_module_from_script(script_path: Path) -> Any:\\n    \\\"\\\"\\\"Load a Python module from a script file.\\\"\\\"\\\"\\n    # Use the script name as the module name to allow inspect to find it\\n    module_name = script_path.stem\\n    spec = importlib.util.spec_from_file_location(module_name, script_path)\\n    if spec is None or spec.loader is None:\\n        msg = f\\\"Could not create module spec for '{script_path}'\\\"\\n        raise ImportError(msg)\\n\\n    module = importlib.util.module_from_spec(spec)\\n\\n    # Register in sys.modules so inspect.getmodule works\\n    sys.modules[module_name] = module\\n\\n    try:\\n        with temporary_sys_path(str(script_path.parent)):\\n            spec.loader.exec_module(module)\\n    except Exception:\\n        if module_name in sys.modules:\\n            del sys.modules[module_name]\\n        raise\\n\\n    return module\\n\\n\\ndef _validate_graph_instance(graph_obj: Any) -> \\\"Graph\\\":\\n    \\\"\\\"\\\"Extract information from a graph object.\\\"\\\"\\\"\\n    from lfx.graph import Graph\\n    from lfx.utils.flow_validation import validate_flow_for_current_settings\\n\\n    if not isinstance(graph_obj, Graph):\\n        msg = f\\\"Graph object is not a LFX Graph instance: {type(graph_obj)}\\\"\\n        raise TypeError(msg)\\n\\n    # Find ChatInput and ChatOutput components\\n    display_names: set[str] = set()\\n    for vertex in graph_obj.vertices:\\n        if vertex.custom_component is not None:\\n            display_names.add(vertex.custom_component.display_name)\\n\\n    if \\\"Chat Input\\\" not in display_names:\\n        msg = f\\\"Graph does not contain any ChatInput component. Vertices: {display_names}\\\"\\n        raise ValueError(msg)\\n\\n    if \\\"Chat Output\\\" not in display_names:\\n        msg = f\\\"Graph does not contain any ChatOutput component. Vertices: {display_names}\\\"\\n        raise ValueError(msg)\\n\\n    validate_flow_for_current_settings(graph_obj)\\n\\n    return graph_obj\\n\\n\\nasync def load_graph_from_script(script_path: Path) -> \\\"Graph\\\":\\n    \\\"\\\"\\\"Load and execute a Python script to extract the 'graph' variable or call 'get_graph' function.\\n\\n    Args:\\n        script_path (Path): Path to the Python script file\\n\\n    Returns:\\n        Graph: The loaded and validated graph instance\\n    \\\"\\\"\\\"\\n    try:\\n        # Load the module\\n        module = _load_module_from_script(script_path)\\n\\n        graph_obj = None\\n\\n        # First, try to get graph from 'get_graph' function (preferred for async code)\\n        if hasattr(module, \\\"get_graph\\\") and callable(module.get_graph):\\n            get_graph_func = module.get_graph\\n\\n            # Check if get_graph is async and handle accordingly\\n            if inspect.iscoroutinefunction(get_graph_func):\\n                graph_obj = await get_graph_func()\\n            else:\\n                graph_obj = get_graph_func()\\n\\n        # Fallback to 'graph' variable for backward compatibility\\n        elif hasattr(module, \\\"graph\\\"):\\n            graph_obj = module.graph\\n\\n        if graph_obj is None:\\n            msg = \\\"No 'graph' variable or 'get_graph()' function found in the executed script\\\"\\n            raise ValueError(msg)\\n\\n        # Programmatic Graph construction does not pass through the JSON flow\\n        # loader's warm-up. Active catalog rules need the same canonical\\n        # identity index before synchronous graph validation runs below.\\n        from lfx.utils.flow_validation import ensure_component_hash_lookups_loaded\\n\\n        await ensure_component_hash_lookups_loaded()\\n        return _validate_graph_instance(graph_obj)\\n\\n    except (\\n        ImportError,\\n        AttributeError,\\n        ModuleNotFoundError,\\n        SyntaxError,\\n        TypeError,\\n        ValueError,\\n        FileNotFoundError,\\n    ) as e:\\n        error_msg = f\\\"Error executing script '{script_path}': {e}\\\"\\n        raise RuntimeError(error_msg) from e\\n\\n\\ndef extract_message_from_result(results: list) -> str:\\n    \\\"\\\"\\\"Extract the message from the results.\\\"\\\"\\\"\\n    for result in results:\\n        if (\\n            hasattr(result, \\\"vertex\\\")\\n            and result.vertex.custom_component\\n            and result.vertex.custom_component.display_name == \\\"Chat Output\\\"\\n        ):\\n            message: Message = result.result_dict.results[\\\"message\\\"]\\n            try:\\n                # Parse the JSON to get just the text content\\n                return json.dumps(json.loads(message.model_dump_json()), ensure_ascii=False)\\n            except (json.JSONDecodeError, AttributeError):\\n                # Fallback to string representation\\n                return str(message)\\n    return \\\"No response generated\\\"\\n\\n\\ndef extract_text_from_result(results: list) -> str:\\n    \\\"\\\"\\\"Extract just the text content from the results.\\\"\\\"\\\"\\n    for result in results:\\n        if (\\n            hasattr(result, \\\"vertex\\\")\\n            and result.vertex.custom_component\\n            and result.vertex.custom_component.display_name == \\\"Chat Output\\\"\\n        ):\\n            message: dict | Message = result.result_dict.results.get(\\\"message\\\")\\n            try:\\n                # Return just the text content\\n                if isinstance(message, dict):\\n                    text_content = message.get(\\\"text\\\") if message.get(\\\"text\\\") else str(message)\\n                else:\\n                    text_content = message.text\\n                return str(text_content)\\n            except AttributeError:\\n                # Fallback to string representation\\n                return str(message)\\n    return \\\"No response generated\\\"\\n\\n\\ndef extract_structured_result(results: list, *, extract_text: bool = True) -> dict:\\n    \\\"\\\"\\\"Extract structured result data from the results.\\\"\\\"\\\"\\n    for result in results:\\n        if (\\n            hasattr(result, \\\"vertex\\\")\\n            and result.vertex.custom_component\\n            and result.vertex.custom_component.display_name == \\\"Chat Output\\\"\\n        ):\\n            message: Message = result.result_dict.results[\\\"message\\\"]\\n            try:\\n                result_message = message.text if extract_text and hasattr(message, \\\"text\\\") else message\\n            except (AttributeError, TypeError, ValueError) as e:\\n                return {\\n                    \\\"text\\\": str(message),\\n                    \\\"type\\\": \\\"message\\\",\\n                    \\\"component\\\": result.vertex.custom_component.display_name,\\n                    \\\"component_id\\\": result.vertex.id,\\n                    \\\"success\\\": True,\\n                    \\\"warning\\\": f\\\"Could not extract text properly: {e}\\\",\\n                }\\n\\n            return {\\n                \\\"result\\\": result_message,\\n                \\\"type\\\": \\\"message\\\",\\n                \\\"component\\\": result.vertex.custom_component.display_name,\\n                \\\"component_id\\\": result.vertex.id,\\n                \\\"success\\\": True,\\n            }\\n    return {\\\"text\\\": \\\"No response generated\\\", \\\"type\\\": \\\"error\\\", \\\"success\\\": False}\\n\\n\\ndef find_graph_variable(script_path: Path) -> dict | None:\\n    \\\"\\\"\\\"Parse a Python script and find the 'graph' variable assignment or 'get_graph' function.\\n\\n    Args:\\n        script_path (Path): Path to the Python script file\\n\\n    Returns:\\n        dict | None: Information about the graph variable or get_graph function if found, None otherwise\\n    \\\"\\\"\\\"\\n    try:\\n        with script_path.open(encoding=\\\"utf-8\\\") as f:\\n            content = f.read()\\n\\n        # Parse the script using AST\\n        tree = ast.parse(content)\\n\\n        # Look for 'get_graph' function definitions (preferred) or 'graph' variable assignments\\n        for node in ast.walk(tree):\\n            # Check for get_graph function definition\\n            if isinstance(node, ast.FunctionDef) and node.name == \\\"get_graph\\\":\\n                line_number = node.lineno\\n                is_async = isinstance(node, ast.AsyncFunctionDef)\\n\\n                return {\\n                    \\\"line_number\\\": line_number,\\n                    \\\"type\\\": \\\"function_definition\\\",\\n                    \\\"function\\\": \\\"get_graph\\\",\\n                    \\\"is_async\\\": is_async,\\n                    \\\"arg_count\\\": len(node.args.args),\\n                    \\\"source_line\\\": content.split(\\\"\\\\n\\\")[line_number - 1].strip(),\\n                }\\n\\n            # Check for async get_graph function definition\\n            if isinstance(node, ast.AsyncFunctionDef) and node.name == \\\"get_graph\\\":\\n                line_number = node.lineno\\n\\n                return {\\n                    \\\"line_number\\\": line_number,\\n                    \\\"type\\\": \\\"function_definition\\\",\\n                    \\\"function\\\": \\\"get_graph\\\",\\n                    \\\"is_async\\\": True,\\n                    \\\"arg_count\\\": len(node.args.args),\\n                    \\\"source_line\\\": content.split(\\\"\\\\n\\\")[line_number - 1].strip(),\\n                }\\n\\n            # Fallback: look for assignments to 'graph' variable\\n            if isinstance(node, ast.Assign):\\n                # Check if any target is named 'graph'\\n                for target in node.targets:\\n                    if isinstance(target, ast.Name) and target.id == \\\"graph\\\":\\n                        # Found a graph assignment\\n                        line_number = node.lineno\\n\\n                        # Try to extract some information about the assignment\\n                        if isinstance(node.value, ast.Call):\\n                            # It's a function call like Graph(...)\\n                            if isinstance(node.value.func, ast.Name):\\n                                func_name = node.value.func.id\\n                            elif isinstance(node.value.func, ast.Attribute):\\n                                # Handle cases like Graph.from_payload(...)\\n                                if isinstance(node.value.func.value, ast.Name):\\n                                    func_name = f\\\"{node.value.func.value.id}.{node.value.func.attr}\\\"\\n                                else:\\n                                    func_name = node.value.func.attr\\n                            else:\\n                                func_name = \\\"Unknown\\\"\\n\\n                            # Count arguments\\n                            arg_count = len(node.value.args) + len(node.value.keywords)\\n\\n                            return {\\n                                \\\"line_number\\\": line_number,\\n                                \\\"type\\\": \\\"function_call\\\",\\n                                \\\"function\\\": func_name,\\n                                \\\"arg_count\\\": arg_count,\\n                                \\\"source_line\\\": content.split(\\\"\\\\n\\\")[line_number - 1].strip(),\\n                            }\\n                        # Some other type of assignment\\n                        return {\\n                            \\\"line_number\\\": line_number,\\n                            \\\"type\\\": \\\"assignment\\\",\\n                            \\\"source_line\\\": content.split(\\\"\\\\n\\\")[line_number - 1].strip(),\\n                        }\\n\\n    except FileNotFoundError:\\n        typer.echo(f\\\"Error: File '{script_path}' not found.\\\")\\n        return None\\n    except SyntaxError as e:\\n        typer.echo(f\\\"Error: Invalid Python syntax in '{script_path}': {e}\\\")\\n        return None\\n    except (OSError, UnicodeDecodeError) as e:\\n        typer.echo(f\\\"Error parsing '{script_path}': {e}\\\")\\n        return None\\n    else:\\n        # No graph variable found\\n        return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/serve_app.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a2bfd2029f1fa75eeb84db9ed32fdf57a3ed3d6f13023533aa1f340b86176793\",\"content\":\"\\\"\\\"\\\"FastAPI application factory for serving **multiple** LFX graphs at once.\\n\\nThis module is used by the CLI *serve* command when the provided path is a\\nfolder containing multiple ``*.json`` flow files.  Each flow is exposed under\\nits own router prefix::\\n\\n    /flows/{flow_id}/run  - POST - execute the flow\\n    /flows/{flow_id}/info - GET  - metadata\\n\\nA global ``/flows`` endpoint lists all available flows and returns a JSON array\\nof metadata objects, allowing API consumers to discover IDs without guessing.\\n\\nAuthentication behaves exactly like the single-flow serving: all execution\\nendpoints require the ``x-api-key`` header (or query parameter) validated by\\n:func:`lfx.cli.commands.verify_api_key`.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport os\\nimport secrets\\nimport time\\nimport traceback\\nimport uuid\\nfrom contextlib import asynccontextmanager\\nfrom copy import deepcopy\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING, Annotated, Any\\n\\nfrom fastapi import Depends, FastAPI, HTTPException, Request, Response, Security\\nfrom fastapi.responses import JSONResponse, StreamingResponse\\nfrom fastapi.security import APIKeyHeader, APIKeyQuery\\nfrom pydantic import BaseModel, ConfigDict, Field, field_validator\\nfrom rich.console import Console\\n\\nfrom lfx.cli.common import (\\n    execute_graph_with_capture,\\n    extract_result_data,\\n    get_api_key,\\n)\\nfrom lfx.cli.runtime_variables import apply_global_vars_to_graph\\nfrom lfx.cli.serve_identity import IdentityConfig, build_identity_verifier\\nfrom lfx.cli.serve_workflow import ServeWorkflowHost\\nfrom lfx.load import load_flow_from_json\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import (\\n    bootstrap_application_telemetry,\\n    execution_protocol,\\n    instrument_fastapi_app,\\n    start_event_loop_lag_monitor,\\n    stop_event_loop_lag_monitor,\\n)\\nfrom lfx.utils.flow_validation import validate_flow_for_current_settings\\nfrom lfx.utils.url_redaction import redact_urls_in_text\\nfrom lfx.workflow.router import create_workflow_router\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncGenerator\\n\\n    from lfx.cli.flow_store import FlowStore\\n    from lfx.graph import Graph\\n\\n# Operator-facing startup notices go to stderr via Rich (same mechanism as the\\n# CLI startup banner). The structlog ``logger`` is not reliably surfaced on the\\n# ``lfx serve`` stdout path under uvicorn (single- and multi-worker alike), so\\n# security-critical startup warnings must use a guaranteed channel.\\n_startup_console = Console(stderr=True, soft_wrap=True)\\n\\n# Security - use the same pattern as Langflow main API\\nAPI_KEY_NAME = \\\"x-api-key\\\"\\n\\n# Constants for app factory env vars (used by uvicorn worker processes)\\n_SERVE_ENV_PREFIX = \\\"LFX_SERVE_\\\"\\n_SERVE_FLOW_DIR_ENV = f\\\"{_SERVE_ENV_PREFIX}FLOW_DIR\\\"\\n_SERVE_NO_ENV_FALLBACK_ENV = f\\\"{_SERVE_ENV_PREFIX}NO_ENV_FALLBACK\\\"\\n_SERVE_STARTUP_PATHS_ENV = f\\\"{_SERVE_ENV_PREFIX}STARTUP_PATHS\\\"\\n_SERVE_DURABLE_DB_ENV = f\\\"{_SERVE_ENV_PREFIX}DURABLE_DB\\\"\\n# Opt-in (`lfx serve --reset-environ`): when \\\"1\\\", guarded_execute snapshots\\n# os.environ before each flow run and restores it after, so env mutations made by\\n# one request (or request-scoped credentials) cannot leak into the next request\\n# served by the same warm worker. Off by default. Set by serve_command; read per\\n# request in guarded_execute.\\n_SERVE_RESET_ENVIRON_ENV = f\\\"{_SERVE_ENV_PREFIX}RESET_ENVIRON\\\"\\napi_key_query = APIKeyQuery(name=API_KEY_NAME, scheme_name=\\\"API key query\\\", auto_error=False)\\napi_key_header = APIKeyHeader(name=API_KEY_NAME, scheme_name=\\\"API key header\\\", auto_error=False)\\n\\n# One in-flight flow execution per worker process. An async UvicornWorker can\\n# accept a second connection while one request is mid-flight; this guard ensures\\n# the env-sensitive execution section (where request-scoped vars are active and\\n# flow code may touch os.environ) is never entered by two requests in the same\\n# process at once. Matters most with per-request recycling (--max-requests 1).\\n_EXECUTE_GUARD = asyncio.Semaphore(1)\\n\\n\\nasync def guarded_execute(graph_copy, input_value, session_id=None, user_id=None):\\n    \\\"\\\"\\\"Run ``execute_graph_with_capture`` under the per-worker single-in-flight guard.\\n\\n    Serializes the env-sensitive execution section so two concurrent requests in\\n    the same async worker can never overlap a flow run before the worker recycles.\\n\\n    When ``LFX_SERVE_RESET_ENVIRON`` is \\\"1\\\" (``lfx serve --reset-environ``), the\\n    process environment is snapshotted before the run and restored afterward, so a\\n    flow's os.environ mutations (or request-scoped credentials) cannot leak into the\\n    next request served by the same warm worker. Off by default \u2014 the snapshot is\\n    skipped entirely unless opted in.\\n    \\\"\\\"\\\"\\n    async with _EXECUTE_GUARD:\\n        reset_environ = os.environ.get(_SERVE_RESET_ENVIRON_ENV) == \\\"1\\\"\\n        env_snapshot = dict(os.environ) if reset_environ else None\\n        try:\\n            # Both native serve routes (/flows/{id}/run and /flows/{id}/stream) funnel through\\n            # here, so the flow span gets its label once. The v2 workflow router mounted on the\\n            # same app binds its own, and binding is outermost-wins, so the two never fight.\\n            with execution_protocol(\\\"lfx.serve\\\"):\\n                return await execute_graph_with_capture(graph_copy, input_value, session_id=session_id, user_id=user_id)\\n        finally:\\n            if env_snapshot is not None and os.environ != env_snapshot:\\n                # Restore by diff \u2014 never os.environ.clear(). clear() empties the mapping key\\n                # by key (MutableMapping.clear loops popitem with no lock), and verify_api_key\\n                # is a sync dependency FastAPI runs on a threadpool thread, so a concurrent auth\\n                # check could observe LANGFLOW_API_KEY transiently gone and 401. Touch only the\\n                # keys this run actually changed; keys it never mutated are left in place.\\n                current = os.environ\\n                for key in [k for k in current if k not in env_snapshot]:\\n                    del current[key]\\n                for key, value in env_snapshot.items():\\n                    if current.get(key) != value:\\n                        current[key] = value\\n\\n\\ndef _snapshot_expected_api_key() -> str | None:\\n    \\\"\\\"\\\"Read the configured server API key once (at app startup).\\n\\n    Cached on ``app.state`` so :func:`verify_api_key` need not read live ``os.environ`` per\\n    request. Returns ``None`` when the key is unset at creation time, so verify_api_key falls\\n    back to a one-time lazy read for callers that configure it afterward (e.g. tests).\\n    \\\"\\\"\\\"\\n    try:\\n        return get_api_key()\\n    except ValueError:\\n        return None\\n\\n\\ndef verify_api_key(\\n    request: Request,\\n    query_param: Annotated[str | None, Security(api_key_query)],\\n    header_param: Annotated[str | None, Security(api_key_header)],\\n) -> str:\\n    \\\"\\\"\\\"Verify API key from query parameter or header.\\n\\n    The expected key is snapshotted at app startup (``app.state.expected_api_key``) so this\\n    check does not read live ``os.environ`` on each request. That matters under\\n    ``--reset-environ``: verify_api_key is a sync dependency FastAPI runs on a threadpool\\n    thread, so a live read could race with ``guarded_execute``'s env restore on the loop\\n    thread even for a flow that overwrites the auth key. If the key was not configured at\\n    startup it is read once here and cached, preserving prior behavior.\\n    \\\"\\\"\\\"\\n    provided_key = query_param or header_param\\n    if not provided_key:\\n        raise HTTPException(status_code=401, detail=\\\"API key required\\\")\\n\\n    expected_key = getattr(request.app.state, \\\"expected_api_key\\\", None)\\n    if expected_key is None:\\n        try:\\n            expected_key = get_api_key()\\n        except ValueError as e:\\n            raise HTTPException(status_code=500, detail=str(e)) from e\\n        request.app.state.expected_api_key = expected_key\\n\\n    if not secrets.compare_digest(provided_key.encode(), expected_key.encode()):\\n        raise HTTPException(status_code=401, detail=\\\"Invalid API key\\\")\\n\\n    return provided_key\\n\\n\\nclass FlowAlreadyRegisteredError(ValueError):\\n    \\\"\\\"\\\"Raised by FlowRegistry.add() when a flow ID is already registered and overwrite=False.\\\"\\\"\\\"\\n\\n\\nclass FlowMeta(BaseModel):\\n    \\\"\\\"\\\"Metadata returned by the ``/flows`` endpoint.\\\"\\\"\\\"\\n\\n    id: str = Field(..., description=\\\"Flow identifier (UUID)\\\")\\n    relative_path: str = Field(..., description=\\\"Path of the flow JSON relative to the deployed folder\\\")\\n    title: str = Field(..., description=\\\"Human-readable title (filename stem if unknown)\\\")\\n    description: str | None = Field(None, description=\\\"Optional flow description\\\")\\n\\n\\nclass RunRequest(BaseModel):\\n    \\\"\\\"\\\"Request model for executing a LFX flow.\\\"\\\"\\\"\\n\\n    input_value: str = Field(..., description=\\\"Input value passed to the flow\\\")\\n    session_id: str | None = Field(default=None, description=\\\"Session ID for maintaining conversation state\\\")\\n    global_vars: dict[str, str] | None = Field(\\n        default=None,\\n        description=\\\"Per-request variables injected into graph.context['request_variables'] on the deepcopy. \\\"\\n        \\\"Use this to supply credentials or other scoped values without touching os.environ.\\\",\\n    )\\n\\n\\nclass StreamRequest(BaseModel):\\n    \\\"\\\"\\\"Request model for streaming execution of a LFX flow.\\\"\\\"\\\"\\n\\n    input_value: str = Field(..., description=\\\"Input value passed to the flow\\\")\\n    input_type: str = Field(default=\\\"chat\\\", description=\\\"Type of input (chat, text)\\\")\\n    output_type: str = Field(default=\\\"chat\\\", description=\\\"Type of output (chat, text, debug, any)\\\")\\n    output_component: str | None = Field(default=None, description=\\\"Specific output component to stream from\\\")\\n    session_id: str | None = Field(default=None, description=\\\"Session ID for maintaining conversation state\\\")\\n    tweaks: dict[str, Any] | None = Field(default=None, description=\\\"Optional tweaks to modify flow behavior\\\")\\n    global_vars: dict[str, str] | None = Field(\\n        default=None,\\n        description=\\\"Per-request variables injected into graph.context['request_variables'] on the deepcopy. \\\"\\n        \\\"Use this to supply credentials or other scoped values without touching os.environ.\\\",\\n    )\\n\\n\\nclass RunResponse(BaseModel):\\n    \\\"\\\"\\\"Response model mirroring the single-flow server.\\\"\\\"\\\"\\n\\n    result: str = Field(..., description=\\\"The output result from the flow execution\\\")\\n    success: bool = Field(..., description=\\\"Whether execution was successful\\\")\\n    logs: str = Field(\\\"\\\", description=\\\"Captured logs from execution\\\")\\n    type: str = Field(\\\"message\\\", description=\\\"Type of result\\\")\\n    component: str = Field(\\\"\\\", description=\\\"Component that generated the result\\\")\\n\\n\\nclass ErrorResponse(BaseModel):\\n    error: str = Field(..., description=\\\"Error message\\\")\\n    success: bool = Field(default=False, description=\\\"Always false for errors\\\")\\n\\n\\nclass FlowRegistry:\\n    \\\"\\\"\\\"Mutable in-process registry of loaded flows.\\n\\n    The in-memory dict is a per-worker cache. Backing persistence is provided\\n    by a :class:`~lfx.cli.flow_store.FlowStore`; the default ``NullFlowStore``\\n    keeps everything in memory only.\\n\\n    - ``NullFlowStore`` (default): single-worker, no disk I/O.\\n    - ``FilesystemFlowStore(\\\"/tmp/lfx-flows\\\")``: all uvicorn workers in the\\n      same pod share flows via ``/tmp``.\\n    - ``FilesystemFlowStore(\\\"/mnt/lfx-flows\\\")``: same code, cross-pod if the\\n      path is a PVC mount.\\n\\n    **Per-request stale check (FilesystemFlowStore only)**\\n\\n    Every call to :meth:`get` for a store-backed flow does one\\n    ``FlowStore.read()`` to verify the file still exists.  This is how DELETE\\n    propagates across workers: the deleting worker removes the file; the next\\n    inbound request on any other worker calls ``get()``, finds ``None``, evicts\\n    the cached entry, and returns 404.\\n\\n    On a local SSD this overhead is a single ``stat``-equivalent and is\\n    negligible.  On a **network volume** (NFS, CIFS, or a Kubernetes PVC backed\\n    by a networked storage class) each read call crosses the network, which can\\n    add measurable latency per request.  If you are running on such a mount and\\n    latency matters, prefer ``/tmp/lfx-flows`` (local tmpfs) for single-pod\\n    worker sharing and accept that cross-pod DELETE propagation is eventual\\n    (next request per pod) rather than immediate.\\n\\n    When ``no_env_fallback=True``, every graph registered via ``add()`` has\\n    ``graph.context['no_env_fallback']`` set to ``True`` at registration time,\\n    preventing credential resolution from falling back to ``os.environ``.\\n    \\\"\\\"\\\"\\n\\n    # TTL for the cached result of store.list_ids() (a filesystem glob).\\n    # Avoids one glob per /health call while still reflecting changes within ~1 s.\\n    # Mutations (add / remove) invalidate the cache immediately.\\n    _STORE_IDS_TTL: float = 1.0\\n\\n    def __init__(self, *, no_env_fallback: bool = False, store: FlowStore | None = None) -> None:\\n        from lfx.cli.flow_store import NullFlowStore\\n\\n        # Key invariant: a flow may be stored under TWO keys simultaneously \u2014\\n        # its JSON UUID *and* a filename stem (e.g. \\\"prompt_one\\\") when the\\n        # pre-placed file's stem differs from the UUID in the JSON.  Both keys\\n        # map to the *same* (graph, meta) tuple.  All deduplication logic\\n        # (list_metas, __len__, remove) uses meta.id as the canonical identity.\\n        self._flows: dict[str, tuple[Graph, FlowMeta]] = {}\\n        self._no_env_fallback = no_env_fallback\\n        self._store = store if store is not None else NullFlowStore()\\n        # Maps meta.id \u2192 store key when they differ (pre-placed files with human-readable names).\\n        self._store_keys: dict[str, str] = {}\\n        # Lightweight metadata cache for store flows not yet fully loaded into _flows.\\n        # Avoids re-reading JSON on every list_metas() call for multi-worker uploads.\\n        self._store_meta_cache: dict[str, FlowMeta] = {}\\n        # Flow IDs whose source of truth is the store. These are re-verified against\\n        # the store in get() / list_metas() to catch cross-worker deletes.\\n        self._store_sourced: set[str] = set()\\n        # TTL cache for store.list_ids() to avoid one filesystem glob per /health call.\\n        self._store_ids_cache: list[str] | None = None\\n        self._store_ids_cache_ts: float = 0.0\\n\\n    def stamp(self, graph: Graph) -> None:\\n        \\\"\\\"\\\"Apply the registry's env-fallback policy to ``graph.context``.\\n\\n        Called again after ``deepcopy`` in the run/stream endpoints, since\\n        ``Graph.__deepcopy__`` does not carry ``context`` over.\\n        \\\"\\\"\\\"\\n        if self._no_env_fallback:\\n            graph.context[\\\"no_env_fallback\\\"] = True\\n\\n    def _get_cached_store_ids(self) -> list[str]:\\n        \\\"\\\"\\\"Return store.list_ids(), refreshing at most once per _STORE_IDS_TTL seconds.\\\"\\\"\\\"\\n        now = time.monotonic()\\n        if self._store_ids_cache is None or now - self._store_ids_cache_ts > self._STORE_IDS_TTL:\\n            self._store_ids_cache = self._store.list_ids()\\n            self._store_ids_cache_ts = now\\n        return self._store_ids_cache\\n\\n    def _invalidate_store_ids_cache(self) -> None:\\n        self._store_ids_cache = None\\n\\n    def add(self, graph: Graph, meta: FlowMeta, *, overwrite: bool = False, raw_json: dict | None = None) -> None:\\n        if not overwrite and meta.id in self._flows:\\n            msg = f\\\"Flow '{meta.id}' is already registered. Pass overwrite=True to replace it.\\\"\\n            raise FlowAlreadyRegisteredError(msg)\\n        # If overwriting a flow that was loaded from a differently-named store file\\n        # (e.g. prompt_one.json whose JSON id is a UUID), delete the old file and\\n        # clear the alias so the new file becomes the single source of truth.\\n        if overwrite:\\n            old_store_key = self._store_keys.pop(meta.id, None)\\n            if old_store_key is not None:\\n                self._store.delete(old_store_key)\\n                self._flows.pop(old_store_key, None)\\n            else:\\n                # No alias recorded \u2014 the replace path skips the get() that would have\\n                # learned it. A pre-placed file (e.g. my-flow.json) may still carry meta.id\\n                # in its JSON \\\"id\\\" under a differently-named key; delete it so the new\\n                # {uuid}.json becomes the single source of truth.\\n                self._delete_aliased_store_files(meta.id)\\n        if raw_json is not None:\\n            self._store.write(meta.id, raw_json)\\n            if getattr(self._store, \\\"is_persistent\\\", False):\\n                self._store_sourced.add(meta.id)\\n        self.stamp(graph)\\n        self._flows[meta.id] = (graph, meta)\\n        self._store_meta_cache.pop(meta.id, None)\\n        self._invalidate_store_ids_cache()\\n\\n    def _evict(self, meta_id: str) -> None:\\n        \\\"\\\"\\\"Remove all in-memory traces of a store-sourced flow (e.g. deleted by another worker).\\\"\\\"\\\"\\n        store_key = self._store_keys.pop(meta_id, meta_id)\\n        for k in {meta_id, store_key}:\\n            self._flows.pop(k, None)\\n            self._store_meta_cache.pop(k, None)\\n        self._store_sourced.discard(meta_id)\\n\\n    def _delete_aliased_store_files(self, canonical_id: str) -> None:\\n        \\\"\\\"\\\"Delete stem-keyed store files that are aliases of *canonical_id*.\\n\\n        Targets persistent-store files whose JSON ``id`` equals *canonical_id* but are\\n        keyed under a different stem (e.g. a pre-placed ``my-flow.json`` alongside\\n        ``{uuid}.json``), so the canonical key stays the single source of truth. Also\\n        drops any in-memory cache entries for those stems. No-op for non-persistent\\n        stores (NullFlowStore has no other files). Uses a live ``list_ids()`` rather than\\n        the TTL cache so a listing taken right after a delete is current.\\n        \\\"\\\"\\\"\\n        if not getattr(self._store, \\\"is_persistent\\\", False):\\n            return\\n        for stem_id in self._store.list_ids():\\n            if stem_id == canonical_id:\\n                continue\\n            stem_raw = self._store.read(stem_id)\\n            if stem_raw and stem_raw.get(\\\"id\\\") == canonical_id:\\n                self._store.delete(stem_id)\\n                self._flows.pop(stem_id, None)\\n                self._store_meta_cache.pop(stem_id, None)\\n\\n    def get(self, flow_id: str) -> tuple[Graph, FlowMeta] | None:\\n        if flow_id in self._flows:\\n            _, meta = self._flows[flow_id]\\n            # Cross-worker stale check: if this flow came from the store, verify it\\n            # hasn't been deleted by another worker since we cached it.\\n            # Use _store_keys to find the real store key (which may be a filename stem\\n            # rather than the JSON UUID for pre-placed flows).\\n            if meta.id in self._store_sourced:\\n                store_key = self._store_keys.get(meta.id, meta.id)\\n                if self._store.read(store_key) is None:\\n                    self._evict(meta.id)\\n                    return None\\n            return self._flows[flow_id]\\n        raw_json = self._store.read(flow_id)\\n        if raw_json is None:\\n            return None\\n        # Cache-miss reconstruction from the store. With per-request worker recycling\\n        # (gunicorn --max-requests 1), a flow not folded into the preload image pays\\n        # this graph-rebuild cost on every request \u2014 log it so the overhead is observable.\\n        logger.info(f\\\"Reconstructing flow '{flow_id}' from store on cache miss\\\")\\n        graph, meta = self._reconstruct(flow_id, raw_json)\\n        # Cache under the authoritative JSON id so requests by UUID find it.\\n        self._flows[meta.id] = (graph, meta)\\n        self._store_meta_cache.pop(meta.id, None)\\n        if flow_id != meta.id:\\n            # Also keep the filename-stem alias so warm_from_store lookups hit.\\n            self._flows[flow_id] = (graph, meta)\\n            # Remember the store key so remove() can delete the right file.\\n            self._store_keys[meta.id] = flow_id\\n        return graph, meta\\n\\n    @staticmethod\\n    def _meta_from_raw_json(flow_id: str, raw_json: dict) -> FlowMeta:\\n        actual_id = raw_json.get(\\\"id\\\") or flow_id\\n        return FlowMeta(\\n            id=actual_id,\\n            relative_path=\\\"<filesystem>\\\",\\n            title=raw_json.get(\\\"name\\\", actual_id),\\n            description=raw_json.get(\\\"description\\\"),\\n        )\\n\\n    def _reconstruct(self, flow_id: str, raw_json: dict) -> tuple[Graph, FlowMeta]:\\n        meta = self._meta_from_raw_json(flow_id, raw_json)\\n        graph = load_flow_from_json(raw_json)\\n        graph.prepare()\\n        graph.flow_id = meta.id\\n        self.stamp(graph)\\n        if getattr(self._store, \\\"is_persistent\\\", False):\\n            self._store_sourced.add(meta.id)\\n        return graph, meta\\n\\n    def warm_from_store(self) -> None:\\n        \\\"\\\"\\\"Load all flows from the backing store into the in-memory cache.\\n\\n        Called once at startup so every worker can serve any flow that was\\n        previously uploaded (by another worker or a prior run) without a\\n        cache-miss penalty on the first request.\\n        \\\"\\\"\\\"\\n        # Bypass the TTL cache \u2014 startup must always see the current store state.\\n        for flow_id in self._store.list_ids():\\n            try:\\n                self.get(flow_id)  # no-op if already cached; loads from store otherwise\\n            except Exception as exc:  # noqa: BLE001\\n                # One unloadable flow (corrupt JSON, or a flow referencing a component\\n                # not available in this build) must not abort the whole worker's startup \u2014\\n                # skip it so every other flow still serves.\\n                logger.warning(\\\"Skipping flow %r during store warm-up: %r\\\", flow_id, exc)\\n\\n    def list_metas(self) -> list[FlowMeta]:\\n        seen: set[str] = set()\\n        result: list[FlowMeta] = []\\n        store_ids = set(self._get_cached_store_ids())\\n        for _, meta in self._flows.values():\\n            if meta.id in seen:\\n                continue\\n            # Skip flows deleted by another worker (still in our cache but gone from store).\\n            # Use the real store key (may be a filename stem for pre-placed flows).\\n            # Check the store directly rather than the TTL-cached id list, so a delete\\n            # by another worker is reflected immediately (same as the get() stale check).\\n            if meta.id in self._store_sourced:\\n                store_key = self._store_keys.get(meta.id, meta.id)\\n                if not self._store.exists(store_key):\\n                    continue\\n            result.append(meta)\\n            seen.add(meta.id)\\n        for flow_id in store_ids:\\n            if flow_id not in self._flows:\\n                # Check the lightweight metadata cache before reading from disk.\\n                if flow_id in self._store_meta_cache:\\n                    cached = self._store_meta_cache[flow_id]\\n                    if cached.id not in seen:\\n                        result.append(cached)\\n                        seen.add(cached.id)\\n                    continue\\n                raw_json = self._store.read(flow_id)\\n                if raw_json:\\n                    meta = self._meta_from_raw_json(flow_id, raw_json)\\n                    if meta.id not in seen:\\n                        self._store_meta_cache[flow_id] = meta\\n                        result.append(meta)\\n                        seen.add(meta.id)\\n        return result\\n\\n    def remove(self, flow_id: str) -> bool:\\n        # Resolve the canonical meta id and store key.\\n        entry = self._flows.get(flow_id)\\n        if entry is not None:\\n            meta_id = entry[1].id\\n            store_key = self._store_keys.get(meta_id, meta_id)\\n            # Drop all cache keys that point to this flow (UUID and any filename alias).\\n            for k in [meta_id, store_key]:\\n                self._flows.pop(k, None)\\n                self._store_meta_cache.pop(k, None)\\n            self._store_keys.pop(meta_id, None)\\n            self._store_sourced.discard(meta_id)\\n            mem_had_it = True\\n        else:\\n            # Flow not in memory; derive both the stem key (flow_id) and the UUID from the file.\\n            store_key = flow_id\\n            self._store_meta_cache.pop(flow_id, None)\\n            self._store_sourced.discard(flow_id)\\n            mem_had_it = False\\n            meta_id = flow_id  # best-effort default; overridden below if we can read the file\\n            raw = self._store.read(flow_id)\\n            if raw:\\n                meta_id = raw.get(\\\"id\\\") or flow_id\\n\\n        store_had_it = self._store.delete(store_key)\\n        # Ensure cross-worker DELETE propagation: delete BOTH the primary store key\\n        # and any alternate-keyed file so that workers whose in-memory stale-check\\n        # uses a different key also see the deletion on their next request.\\n        if store_key != meta_id:\\n            # Alias known: primary key was a stem, UUID-keyed file may also exist.\\n            self._store.delete(meta_id)\\n        elif store_had_it:\\n            # Primary key IS the UUID: delete any stem-keyed file carrying the same\\n            # \\\"id\\\" field (e.g. a pre-placed my-flow.json alongside {uuid}.json).\\n            self._delete_aliased_store_files(meta_id)\\n        self._invalidate_store_ids_cache()\\n        return mem_had_it or store_had_it\\n\\n    def __len__(self) -> int:\\n        # Delegates to list_metas() so store-only flows (not yet cache-loaded) are\\n        # counted. list_metas() caches metadata after the first disk read, so\\n        # repeated calls (e.g. /health) are cheap after the first.\\n        return len(self.list_metas())\\n\\n\\nclass UploadFlowRequest(BaseModel):\\n    model_config = ConfigDict(extra=\\\"allow\\\")\\n\\n    name: str = Field(..., description=\\\"Human-readable name for the flow\\\")\\n    data: dict = Field(..., description=\\\"Flow graph data \u2014 nodes and edges\\\")\\n    description: str | None = Field(default=None, description=\\\"Optional flow description\\\")\\n    id: str | None = Field(default=None, description=\\\"Stable flow ID from Langflow export (must be a valid UUID)\\\")\\n    replace: bool = Field(default=False, description=\\\"Overwrite the existing flow if the ID already exists\\\")\\n\\n    @field_validator(\\\"id\\\", mode=\\\"before\\\")\\n    @classmethod\\n    def validate_id_is_uuid(cls, v: object) -> object:\\n        if v is None:\\n            return v\\n        try:\\n            uuid.UUID(str(v))\\n        except ValueError:\\n            msg = f\\\"id must be a valid UUID, got {v!r}\\\"\\n            raise ValueError(msg) from None\\n        return str(v)\\n\\n\\nclass UploadFlowResponse(BaseModel):\\n    id: str = Field(..., description=\\\"Flow identifier (UUID)\\\")\\n    name: str\\n    description: str | None\\n    run_url: str = Field(..., description=\\\"Endpoint to POST run requests, e.g. /flows/{id}/run\\\")\\n\\n\\n# -----------------------------------------------------------------------------\\n# Streaming helper functions\\n# -----------------------------------------------------------------------------\\n\\n\\nasync def consume_and_yield(queue: asyncio.Queue, client_consumed_queue: asyncio.Queue) -> AsyncGenerator:\\n    \\\"\\\"\\\"Consumes events from a queue and yields them to the client while tracking timing metrics.\\n\\n    This coroutine continuously pulls events from the input queue and yields them to the client.\\n    It tracks timing metrics for how long events spend in the queue and how long the client takes\\n    to process them.\\n\\n    Args:\\n        queue (asyncio.Queue): The queue containing events to be consumed and yielded\\n        client_consumed_queue (asyncio.Queue): A queue for tracking when the client has consumed events\\n\\n    Yields:\\n        The value from each event in the queue\\n\\n    Notes:\\n        - Events are tuples of (event_id, value, put_time)\\n        - Breaks the loop when receiving a None value, signaling completion\\n        - Tracks and logs timing metrics for queue time and client processing time\\n        - Notifies client consumption via client_consumed_queue\\n    \\\"\\\"\\\"\\n    while True:\\n        event_id, value, put_time = await queue.get()\\n        if value is None:\\n            break\\n        get_time = time.time()\\n        yield value\\n        get_time_yield = time.time()\\n        client_consumed_queue.put_nowait(event_id)\\n        logger.debug(\\n            f\\\"consumed event {event_id} \\\"\\n            f\\\"(time in queue, {get_time - put_time:.4f}, \\\"\\n            f\\\"client {get_time_yield - get_time:.4f})\\\"\\n        )\\n\\n\\nasync def run_flow_generator_for_serve(\\n    graph: Graph,\\n    input_request: StreamRequest,\\n    flow_id: str,\\n    event_manager,\\n    client_consumed_queue: asyncio.Queue,\\n    user_id: str | None = None,\\n) -> None:\\n    \\\"\\\"\\\"Executes a flow asynchronously and manages event streaming to the client.\\n\\n    This coroutine runs a flow with streaming enabled and handles the event lifecycle,\\n    including success completion and error scenarios.\\n\\n    Args:\\n        graph (Graph): The graph to execute\\n        input_request (StreamRequest): The input parameters for the flow\\n        flow_id (str): The ID of the flow being executed\\n        event_manager: Manages the streaming of events to the client\\n        client_consumed_queue (asyncio.Queue): Tracks client consumption of events\\n        user_id (str | None): Verified caller identity threaded into execution as\\n            the graph's ``user_id``. ``None`` means no verified identity \u2014 the\\n            graph's existing ``user_id`` is used, or a UUID auto-generated if it\\n            has none.\\n\\n    Events Generated:\\n        - \\\"add_message\\\": Sent when new messages are added during flow execution\\n        - \\\"token\\\": Sent for each token generated during streaming\\n        - \\\"end\\\": Sent when flow execution completes, includes final result\\n        - \\\"error\\\": Sent if an error occurs during execution\\n\\n    Notes:\\n        - Runs the flow with streaming enabled via execute_graph_with_capture()\\n        - On success, sends the final result via event_manager.on_end()\\n        - On error, logs the error and sends it via event_manager.on_error()\\n        - Always sends a final None event to signal completion\\n    \\\"\\\"\\\"\\n    try:\\n        # For the serve app, we'll use execute_graph_with_capture with streaming\\n        # Note: This is a simplified version. In a full implementation, you might want\\n        # to integrate with the full LFX streaming pipeline from endpoints.py\\n        # Routed through the single-in-flight guard so a streaming run can never\\n        # overlap another run/stream in the same worker (see _EXECUTE_GUARD).\\n        results, logs = await guarded_execute(\\n            graph, input_request.input_value, session_id=input_request.session_id, user_id=user_id\\n        )\\n        result_data = extract_result_data(results, logs)\\n\\n        # Send the final result\\n        event_manager.on_end(data={\\\"result\\\": result_data})\\n        await client_consumed_queue.get()\\n    except Exception as e:  # noqa: BLE001\\n        logger.error(f\\\"Error running flow {flow_id}: {e}\\\")\\n        event_manager.on_error(data={\\\"error\\\": str(e)})\\n    finally:\\n        await event_manager.queue.put((None, None, time.time()))\\n\\n\\n# -----------------------------------------------------------------------------\\n# Application factory\\n# -----------------------------------------------------------------------------\\n\\n\\ndef _ensure_variable_service_registered() -> None:\\n    \\\"\\\"\\\"Register the minimal in-memory :class:`VariableService` if none is registered.\\n\\n    Idempotent and safe to call on every worker startup: a previously registered\\n    service (e.g. a real DB-backed one in a full Langflow process) is left untouched.\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import get_variable_service\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n    from lfx.services.variable.service import VariableService\\n\\n    if get_variable_service() is not None:\\n        return\\n    get_service_manager().register_service_class(ServiceType.VARIABLE_SERVICE, VariableService, override=False)\\n\\n\\ndef create_multi_serve_app(\\n    *,\\n    registry: FlowRegistry,\\n    identity_config: IdentityConfig | None = None,\\n) -> FastAPI:\\n    \\\"\\\"\\\"Create a FastAPI app exposing LFX flows via a mutable registry.\\n\\n    Routes dispatch to ``registry`` at request time, so flows added after\\n    startup (via ``POST /flows/upload/``) are immediately reachable.\\n\\n    ``identity_config`` configures the optional per-user identity layer (see\\n    :mod:`lfx.cli.serve_identity`). ``None`` (the default) means ``off`` mode \u2014\\n    no identity is read and execution behaves exactly as before.\\n    \\\"\\\"\\\"\\n    # Application observability. lfx serve is the production HTTP surface, so it installs the\\n    # same OTLP providers and HTTP instrumentation the full langflow app does, driven entirely\\n    # by the standard OTEL_* environment variables. No-op unless an endpoint is set (and unless\\n    # lfx was installed with the ``otel`` extra), so this costs nothing by default.\\n    telemetry = bootstrap_application_telemetry()\\n\\n    @asynccontextmanager\\n    async def _lifespan(_app: FastAPI):\\n        # Started here rather than at app construction because it needs the running loop, and\\n        # under ``--workers`` the app is built in the gunicorn master before the fork.\\n        # Best-effort: optional instrumentation must never keep the server from starting.\\n        lag_monitor = None\\n        try:\\n            lag_monitor = start_event_loop_lag_monitor(telemetry.meter_provider)\\n        except Exception as e:  # noqa: BLE001\\n            logger.warning(f\\\"Event loop lag monitor failed to start: {e}\\\")\\n        # Flush the OTLP buffers on shutdown. uvicorn dies by signal and never runs the SDK's\\n        # atexit flush, so without this the last batch of spans, metrics and logs drops on every\\n        # restart and pod eviction. Off the event loop: the final export can block on the network.\\n        yield\\n        await stop_event_loop_lag_monitor(lag_monitor)\\n        await asyncio.to_thread(telemetry.shutdown)\\n\\n    app = FastAPI(\\n        title=f\\\"LFX Multi-Flow Server ({len(registry)})\\\",\\n        description=(\\n            \\\"Hosts LFX graphs under the `/flows/{{id}}` prefix. \\\"\\n            \\\"Use `/flows` to list available IDs then POST your input to `/flows/{{id}}/run`. \\\"\\n            \\\"Use `POST /flows/upload/` to register new flows at runtime.\\\"\\n        ),\\n        version=\\\"1.0.0\\\",\\n        lifespan=_lifespan,\\n    )\\n\\n    instrument_fastapi_app(app)\\n\\n    app.state.registry = registry\\n    # Snapshot the API key once so per-request auth (verify_api_key, run on a threadpool\\n    # thread) never reads live os.environ \u2014 see verify_api_key. Stays None until first use\\n    # when the key is configured after app creation.\\n    app.state.expected_api_key = _snapshot_expected_api_key()\\n\\n    # Register the minimal in-memory VariableService so the unified-model credential\\n    # resolver can see request-scoped ``global_vars``. Standalone lfx ships no\\n    # VariableService factory, so ``get_variable_service()`` is ``None`` by default;\\n    # every credential path that resolves *through* the service\\n    # (``get_api_key_for_provider``, ``get_all_variables_for_provider``,\\n    # ``model_utils``, KB connectors) would then never consult the request scope and\\n    # silently fall back to ``os.environ`` \u2014 defeating ``--no-env-fallback`` + per-request\\n    # credential injection. The service reads request scope first, then env (honoring the\\n    # no-env-fallback contract), so registering it makes those paths request-scope-aware.\\n    _ensure_variable_service_registered()\\n\\n    identity_config = identity_config or IdentityConfig()\\n    app.state.identity_config = identity_config\\n    identity_verifier = build_identity_verifier(identity_config)\\n    app.state.identity_verifier = identity_verifier\\n    if identity_verifier is not None:\\n        if identity_config.mode == \\\"jwt\\\":\\n            # Prefetch so the first request never pays the JWKS round-trip. A failed\\n            # prefetch does not abort startup (requests fail closed with 401), but the\\n            # operator must be told, so warn on the guaranteed stderr channel as well.\\n            if not identity_verifier.prefetch():\\n                _startup_console.print(\\n                    \\\"[bold red]WARNING:[/bold red] JWKS prefetch failed \u2014 lfx serve started but JWT \\\"\\n                    \\\"verification will reject all requests (401) until the JWKS endpoint recovers.\\\"\\n                )\\n        elif identity_config.mode == \\\"header\\\":\\n            warning = (\\n                f\\\"lfx serve identity mode=header: trusting the plain {identity_config.trusted_header!r} header \\\"\\n                \\\"as caller identity. This is only safe when network policy guarantees the gateway is the sole \\\"\\n                \\\"caller \u2014 header trust rests entirely on topology, which fails open on non-enforcing CNIs.\\\"\\n            )\\n            logger.warning(warning)\\n            _startup_console.print(f\\\"[bold yellow]WARNING:[/bold yellow] {warning}\\\")\\n\\n    def resolve_identity(request: Request, _api_key: str = Depends(verify_api_key)) -> str | None:\\n        \\\"\\\"\\\"Resolve the verified caller identity for an authenticated request.\\n\\n        Sub-depends on ``verify_api_key`` so identity processing only ever runs\\n        on requests that already cleared the serve-key floor \u2014 identity annotates\\n        authenticated requests, it never weakens or replaces the serve key.\\n        Returns ``None`` in ``off`` mode (no per-user attribution).\\n\\n        Deliberately a sync ``def``: FastAPI runs sync dependencies in a worker\\n        thread, so a rare blocking JWKS fetch (on key rotation or an issuer blip)\\n        never stalls the event loop. The warm path is CPU-only and ~sub-millisecond.\\n\\n        The verifier is read from ``app.state`` at request time so it can be\\n        swapped (e.g. by tests) after app construction.\\n        \\\"\\\"\\\"\\n        verifier = request.app.state.identity_verifier\\n        if verifier is None:\\n            return None\\n        return verifier.authenticate(request.headers)\\n\\n    # ------------------------------------------------------------------\\n    # Global endpoints\\n    # ------------------------------------------------------------------\\n\\n    @app.get(\\n        \\\"/flows\\\",\\n        response_model=list[FlowMeta],\\n        tags=[\\\"info\\\"],\\n        summary=\\\"List available flows\\\",\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def list_flows():\\n        return registry.list_metas()\\n\\n    @app.get(\\\"/health\\\", tags=[\\\"info\\\"], summary=\\\"Global health check\\\")\\n    async def global_health():\\n        return {\\\"status\\\": \\\"healthy\\\", \\\"flow_count\\\": len(registry)}\\n\\n    # ------------------------------------------------------------------\\n    # Upload endpoint \u2014 registered BEFORE /{flow_id} to avoid shadowing\\n    # ------------------------------------------------------------------\\n\\n    @app.post(\\n        \\\"/flows/upload/\\\",\\n        response_model=UploadFlowResponse,\\n        status_code=201,\\n        tags=[\\\"upload\\\"],\\n        summary=\\\"Upload and register a new flow\\\",\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def upload_flow(body: UploadFlowRequest) -> UploadFlowResponse:\\n        # Conflict check before the expensive load+prepare \u2014 only possible when the\\n        # caller supplies an explicit id.  uuid4()-generated ids are always unique so\\n        # there is no point checking before we have one.\\n        flow_id = body.id or str(uuid.uuid4())\\n\\n        if not body.replace and registry.get(flow_id) is not None:\\n            raise HTTPException(\\n                status_code=409,\\n                detail=f\\\"Flow '{flow_id}' already exists. Pass replace=true to overwrite.\\\",\\n            )\\n\\n        try:\\n            graph = load_flow_from_json(body.model_dump(exclude={\\\"replace\\\"}))\\n        except Exception as exc:\\n            raise HTTPException(status_code=422, detail=f\\\"Invalid flow data: {exc}\\\") from exc\\n\\n        try:\\n            graph.prepare()\\n        except Exception as exc:\\n            raise HTTPException(status_code=422, detail=f\\\"Flow preparation failed: {exc}\\\") from exc\\n\\n        graph.flow_id = flow_id\\n        meta = FlowMeta(\\n            id=flow_id,\\n            relative_path=\\\"<uploaded>\\\",\\n            title=body.name,\\n            description=body.description,\\n        )\\n        # graph.prepare() must run before registry.add() \u2014 add() stamps\\n        # graph.context with no_env_fallback, and prepare() must not overwrite it.\\n        registry.add(graph, meta, overwrite=body.replace, raw_json=body.model_dump(exclude={\\\"replace\\\"}))\\n        return UploadFlowResponse(\\n            id=flow_id,\\n            name=body.name,\\n            description=body.description,\\n            run_url=f\\\"/flows/{flow_id}/run\\\",\\n        )\\n\\n    # ------------------------------------------------------------------\\n    # Per-flow dispatch routes\\n    # ------------------------------------------------------------------\\n\\n    def _get_flow_or_404(flow_id: str) -> tuple[Graph, FlowMeta]:\\n        result = registry.get(flow_id)\\n        if result is None:\\n            raise HTTPException(\\n                status_code=404,\\n                detail={\\\"error\\\": \\\"flow not found\\\", \\\"flow_id\\\": flow_id},\\n            )\\n        return result\\n\\n    @app.delete(\\n        \\\"/flows/{flow_id}\\\",\\n        status_code=204,\\n        tags=[\\\"flows\\\"],\\n        summary=\\\"Remove a registered flow\\\",\\n        description=(\\n            \\\"Remove a flow from this worker's registry and from the backing store (if any). \\\"\\n            \\\"**Multi-worker note:** the store file is deleted immediately, but other workers \\\"\\n            \\\"continue to serve the cached copy until their next stale check \\\"\\n            \\\"(triggered by an incoming request for that flow). \\\"\\n            \\\"This is the same eventual-consistency window that applies to uploads.\\\"\\n        ),\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def delete_flow(flow_id: str) -> Response:\\n        removed = registry.remove(flow_id)\\n        if not removed:\\n            raise HTTPException(\\n                status_code=404,\\n                detail={\\\"error\\\": \\\"flow not found\\\", \\\"flow_id\\\": flow_id},\\n            )\\n        return Response(status_code=204)\\n\\n    @app.get(\\n        \\\"/flows/{flow_id}/info\\\",\\n        response_model=FlowMeta,\\n        tags=[\\\"flows\\\"],\\n        summary=\\\"Flow metadata\\\",\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def flow_info(flow_id: str) -> FlowMeta:\\n        _, meta = _get_flow_or_404(flow_id)\\n        return meta\\n\\n    @app.post(\\n        \\\"/flows/{flow_id}/run\\\",\\n        response_model=RunResponse,\\n        responses={404: {\\\"model\\\": ErrorResponse}, 500: {\\\"model\\\": RunResponse}},\\n        tags=[\\\"flows\\\"],\\n        summary=\\\"Execute flow\\\",\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def run_flow(\\n        flow_id: str,\\n        request: RunRequest,\\n        # Depends() lives in the default (not Annotated) so FastAPI reads the live\\n        # closure-local resolver \u2014 ``from __future__ import annotations`` stringizes\\n        # annotations, and a closure-local name can't be resolved from module globals.\\n        # (Hence the FAST002 suppression: the Annotated form ruff wants would break this.)\\n        user_id: str | None = Depends(resolve_identity),  # noqa: FAST002\\n    ) -> RunResponse:\\n        \\\"\\\"\\\"Execute the flow synchronously and return its completed result.\\n\\n        This endpoint runs the flow to completion within the request and returns a\\n        populated ``RunResponse`` (``result`` / ``success``) \u2014 it is NOT a\\n        job-submission endpoint and never returns a task/job id to poll. Clients\\n        that need incremental output should use ``POST /flows/{flow_id}/stream``.\\n        \\\"\\\"\\\"\\n        graph, _ = _get_flow_or_404(flow_id)\\n        try:\\n            validate_flow_for_current_settings(graph)\\n            graph_copy = deepcopy(graph)\\n            # deepcopy() drops graph.context; re-apply the registry's env policy.\\n            registry.stamp(graph_copy)\\n            apply_global_vars_to_graph(graph_copy, request.global_vars)\\n            results, logs = await guarded_execute(\\n                graph_copy, request.input_value, session_id=request.session_id, user_id=user_id\\n            )\\n            result_data = extract_result_data(results, logs)\\n\\n            if not result_data.get(\\\"success\\\", True):\\n                error_message = result_data.get(\\\"result\\\", result_data.get(\\\"text\\\", \\\"No response generated\\\"))\\n                return JSONResponse(\\n                    status_code=500,\\n                    content=RunResponse(\\n                        result=error_message,\\n                        success=False,\\n                        logs=logs\\n                        or f\\\"Flow execution completed but no valid result was produced.\\\\nResult data: {result_data}\\\",\\n                        type=\\\"error\\\",\\n                        component=result_data.get(\\\"component\\\", \\\"\\\"),\\n                    ).model_dump(),\\n                )\\n            return RunResponse(\\n                result=result_data.get(\\\"result\\\", result_data.get(\\\"text\\\", \\\"\\\")),\\n                success=result_data.get(\\\"success\\\", True),\\n                logs=logs,\\n                type=result_data.get(\\\"type\\\", \\\"message\\\"),\\n                component=result_data.get(\\\"component\\\", \\\"\\\"),\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            # A failing outbound call puts its request URL in the exception text, and the\\n            # traceback reproduces that verbatim \u2014 so a 401 arrives carrying the credential\\n            # it just rejected, on its way to the response body and the log aggregator.\\n            error_traceback = redact_urls_in_text(traceback.format_exc())\\n            error_message = redact_urls_in_text(f\\\"Flow execution failed: {exc!s}\\\")\\n            logger.error(f\\\"Error running flow {flow_id}: {redact_urls_in_text(str(exc))}\\\")\\n            logger.debug(f\\\"Full traceback for flow {flow_id}:\\\\n{error_traceback}\\\")\\n            return JSONResponse(\\n                status_code=500,\\n                content=RunResponse(\\n                    result=error_message,\\n                    success=False,\\n                    logs=f\\\"ERROR: {error_message}\\\\n\\\\nFull traceback:\\\\n{error_traceback}\\\",\\n                    type=\\\"error\\\",\\n                    component=\\\"\\\",\\n                ).model_dump(),\\n            )\\n\\n    @app.post(\\n        \\\"/flows/{flow_id}/stream\\\",\\n        response_model=None,\\n        tags=[\\\"flows\\\"],\\n        summary=\\\"Stream flow execution\\\",\\n        dependencies=[Depends(verify_api_key)],\\n    )\\n    async def stream_flow(\\n        flow_id: str,\\n        request: StreamRequest,\\n        user_id: str | None = Depends(resolve_identity),  # noqa: FAST002 - see run_flow note on Depends-in-default\\n    ) -> StreamingResponse:\\n        graph, _ = _get_flow_or_404(flow_id)\\n        try:\\n            validate_flow_for_current_settings(graph)\\n            from lfx.events.event_manager import create_stream_tokens_event_manager\\n\\n            asyncio_queue: asyncio.Queue = asyncio.Queue()\\n            asyncio_queue_client_consumed: asyncio.Queue = asyncio.Queue()\\n            event_manager = create_stream_tokens_event_manager(queue=asyncio_queue)\\n\\n            graph_copy = deepcopy(graph)\\n            # deepcopy() drops graph.context; re-apply the registry's env policy.\\n            registry.stamp(graph_copy)\\n            apply_global_vars_to_graph(graph_copy, request.global_vars)\\n            main_task = asyncio.create_task(\\n                run_flow_generator_for_serve(\\n                    graph=graph_copy,\\n                    input_request=request,\\n                    flow_id=flow_id,\\n                    event_manager=event_manager,\\n                    client_consumed_queue=asyncio_queue_client_consumed,\\n                    user_id=user_id,\\n                )\\n            )\\n\\n            async def on_disconnect() -> None:\\n                logger.debug(f\\\"Client disconnected from flow {flow_id}, closing tasks\\\")\\n                main_task.cancel()\\n\\n            return StreamingResponse(\\n                consume_and_yield(asyncio_queue, asyncio_queue_client_consumed),\\n                background=on_disconnect,\\n                media_type=\\\"text/event-stream\\\",\\n            )\\n        except Exception as exc:  # noqa: BLE001\\n            logger.error(f\\\"Error setting up streaming for flow {flow_id}: {exc}\\\")\\n            error_payload = json.dumps({\\\"error\\\": str(exc), \\\"success\\\": False})\\n\\n            async def error_stream():\\n                yield f\\\"data: {error_payload}\\\\n\\\\n\\\"\\n\\n            return StreamingResponse(error_stream(), media_type=\\\"text/event-stream\\\")\\n\\n    # V2 workflow contract endpoints (sync + stream), shared with the langflow backend.\\n    # Mounted under /api/v2 so the path matches the backend (/api/v2/workflows): a client\\n    # switches runtimes by changing the host, not the URL. developer_api_guard=False keeps\\n    # serve's surface ungated. With LFX_SERVE_DURABLE_DB set, the durable host also\\n    # registers background job + HITL resume endpoints (LE-1695); otherwise serve stays\\n    # stateless and background mode keeps its 422.\\n    durable_db = os.environ.get(_SERVE_DURABLE_DB_ENV, \\\"\\\").strip()\\n    if durable_db:\\n        from lfx.cli.serve_durable import create_durable_workflow_router\\n\\n        workflow_router = create_durable_workflow_router(registry, verify_api_key, db_path=Path(durable_db))\\n    else:\\n        workflow_router = create_workflow_router(ServeWorkflowHost(registry, verify_api_key), developer_api_guard=False)\\n    app.include_router(workflow_router, prefix=\\\"/api/v2\\\")\\n\\n    return app\\n\\n\\ndef build_registry_from_env() -> FlowRegistry:\\n    \\\"\\\"\\\"Build and warm a ``FlowRegistry`` from the ``LFX_SERVE_*`` environment.\\n\\n    Reads ``LFX_SERVE_FLOW_DIR`` / ``LFX_SERVE_NO_ENV_FALLBACK`` /\\n    ``LFX_SERVE_STARTUP_PATHS``. Safe to call at module-import time in a gunicorn\\n    ``--preload`` master: the result is read-only after warming and is inherited\\n    by forked workers via copy-on-write.\\n\\n    The parent process must set those env vars **before** the worker (or the\\n    preload master) calls this function.\\n    \\\"\\\"\\\"\\n    import asyncio\\n    import os\\n    from pathlib import Path\\n\\n    from lfx.cli.flow_store import FilesystemFlowStore, NullFlowStore\\n\\n    flow_dir_str = os.environ.get(_SERVE_FLOW_DIR_ENV)\\n    no_env_fallback = os.environ.get(_SERVE_NO_ENV_FALLBACK_ENV, \\\"0\\\") == \\\"1\\\"\\n    startup_paths_json = os.environ.get(_SERVE_STARTUP_PATHS_ENV, \\\"\\\")\\n\\n    flow_dir = Path(flow_dir_str) if flow_dir_str else None\\n    flow_store = FilesystemFlowStore(flow_dir) if flow_dir else NullFlowStore()\\n\\n    startup_paths = [Path(p) for p in json.loads(startup_paths_json)] if startup_paths_json else []\\n\\n    if startup_paths and not flow_dir:\\n        # No shared store: each worker reloads startup flows from the original file paths.\\n        # When flow_dir IS set the parent already persisted startup JSON flows to the store;\\n        # workers pick them up via warm_from_store() below \u2014 no need to re-read files.\\n        #\\n        # This is called by uvicorn as an ASGI app factory (or by the gunicorn\\n        # preload master) while an event loop may already be running.\\n        # ``asyncio.run()`` raises RuntimeError in that situation.  Running the\\n        # coroutine in a fresh thread gives it a clean event loop with no\\n        # interference.\\n        import concurrent.futures\\n\\n        from lfx.cli.commands import build_registry_from_directory, build_registry_from_paths\\n\\n        if len(startup_paths) == 1 and startup_paths[0].is_dir():\\n            coro = build_registry_from_directory(\\n                startup_paths[0],\\n                lambda _: None,\\n                check_variables=False,\\n                no_env_fallback=no_env_fallback,\\n                store=flow_store,\\n            )\\n        else:\\n            coro = build_registry_from_paths(\\n                startup_paths,\\n                lambda _: None,\\n                check_variables=False,\\n                no_env_fallback=no_env_fallback,\\n                store=flow_store,\\n            )\\n\\n        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:\\n            registry = pool.submit(asyncio.run, coro).result()\\n    else:\\n        registry = FlowRegistry(no_env_fallback=no_env_fallback, store=flow_store)\\n\\n    registry.warm_from_store()\\n    return registry\\n\\n\\ndef create_serve_app() -> FastAPI:\\n    \\\"\\\"\\\"ASGI app factory called by each uvicorn worker in multi-worker mode.\\n\\n    Workers cannot inherit the parent's in-memory app object. Instead, each\\n    worker calls this factory, which reads the ``LFX_SERVE_*`` environment via\\n    :func:`build_registry_from_env` (and the ``LFX_SERVE_IDENTITY_*`` identity\\n    settings via :meth:`IdentityConfig.from_env`), pre-warms its own in-memory\\n    cache from the shared ``FilesystemFlowStore``, and returns a ready FastAPI app.\\n\\n    The parent process must set those env vars **before** calling\\n    ``uvicorn.run(\\\"lfx.cli.serve_app:create_serve_app\\\", workers=N, ...)``.\\n    \\\"\\\"\\\"\\n    return create_multi_serve_app(\\n        registry=build_registry_from_env(),\\n        identity_config=IdentityConfig.from_env(os.environ),\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/serve_durable.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4244df8e743dee58c273deb03e51e45ebb39e88721ab35262a0576afdab2f15f\",\"content\":\"\\\"\\\"\\\"Durable background execution for bare ``lfx serve`` (LE-1695).\\n\\n``DurableServeWorkflowHost`` upgrades the no-db serve host with\\n``supports_background = True``, backed by the single-node SQLite substrate\\n(``lfx.services.durable``): job rows, a per-job event log, and graph checkpoints\\nin one crash-safe file. A HITL pause suspends the job durably; resume restores\\nthe graph from its checkpoint \u2014 in the same process or after a restart \u2014 injects\\nthe human decision, and re-runs only what the approved branch needs.\\n\\nOpt-in via ``LFX_SERVE_DURABLE_DB=<path>``: without it serve stays stateless and\\n``mode=\\\"background\\\"`` keeps its 422. Multi-worker deployments share the DB file\\n(WAL + single-flight claims), but a stop only cancels a run executing in the\\nworker that received it; the durable STOP signal is still recorded.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nfrom typing import TYPE_CHECKING, Any\\nfrom uuid import uuid4\\n\\nfrom fastapi import HTTPException, Request, status\\nfrom starlette.responses import StreamingResponse\\n\\nfrom lfx.cli.serve_workflow import ServeWorkflowHost\\nfrom lfx.graph.checkpoint.resume import _unbuild_needed_dropped_producers\\nfrom lfx.graph.checkpoint.store import set_default_checkpoint_store\\nfrom lfx.graph.exceptions import GraphPausedException\\nfrom lfx.graph.graph.base import Graph\\nfrom lfx.log.logger import logger\\nfrom lfx.observability import execution_protocol\\nfrom lfx.run._defaults import apply_run_defaults\\nfrom lfx.run.hitl import request_id_targets_vertex, reroute_decision_on_timeout\\nfrom lfx.schema.schema import INPUT_FIELD_NAME\\nfrom lfx.schema.workflow import (\\n    ErrorDetail,\\n    JobStatus,\\n    WorkflowExecutionResponse,\\n    WorkflowJobResponse,\\n    WorkflowResumeRequest,\\n    WorkflowResumeResponse,\\n    WorkflowStopResponse,\\n)\\nfrom lfx.services.durable.models import JobStatus as DurableJobStatus\\nfrom lfx.services.durable.models import SignalType\\nfrom lfx.services.durable.sqlite_checkpoints import SqliteCheckpointStore\\nfrom lfx.services.durable.sqlite_store import SqliteDurableJobStore\\nfrom lfx.services.variable.request_scope import (\\n    activate_no_env_fallback,\\n    activate_request_variables,\\n    reset_no_env_fallback,\\n    reset_request_variables,\\n)\\nfrom lfx.workflow.converters import (\\n    _process_terminal_vertex,\\n    create_job_response,\\n    workflow_response_from_output_events,\\n)\\nfrom lfx.workflow.router import _format_sse, create_workflow_router\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n    from pathlib import Path\\n\\n    from fastapi import APIRouter\\n\\n    from lfx.services.durable.models import DurableEvent\\n    from lfx.workflow.converters import ParsedWorkflowRun\\n    from lfx.workflow.host import ResolvedFlow\\n\\n_NON_TERMINAL = {DurableJobStatus.QUEUED, DurableJobStatus.IN_PROGRESS, DurableJobStatus.SUSPENDED}\\n# The events stream tails only while the job is active; SUSPENDED replays and ends\\n# there (like the langflow backend), and the client reconnects after a resume.\\n_STREAMING_ACTIVE = {DurableJobStatus.QUEUED, DurableJobStatus.IN_PROGRESS}\\n_EVENT_POLL_INTERVAL_S = 0.1\\n\\n\\ndef _parse_last_event_id(raw: str | None) -> int:\\n    \\\"\\\"\\\"Parse the ``Last-Event-ID`` header into a seq cursor; unparseable -> 0 (replay all).\\\"\\\"\\\"\\n    if not raw:\\n        return 0\\n    try:\\n        return max(int(raw), 0)\\n    except (TypeError, ValueError):\\n        return 0\\n\\n\\ndef _sse_for(event: DurableEvent) -> bytes:\\n    \\\"\\\"\\\"Frame one durable event as an SSE message keyed by its seq (for Last-Event-ID).\\\"\\\"\\\"\\n    return _format_sse(json.dumps({\\\"event\\\": event.event_type, \\\"data\\\": event.payload, \\\"seq\\\": event.seq}), event.seq)\\n\\n\\ndef _job_not_found(job_id: str) -> HTTPException:\\n    return HTTPException(\\n        status_code=status.HTTP_404_NOT_FOUND,\\n        detail={\\\"error\\\": \\\"Workflow job not found\\\", \\\"code\\\": \\\"JOB_NOT_FOUND\\\", \\\"job_id\\\": job_id},\\n    )\\n\\n\\ndef _not_resumable(job_id: str) -> HTTPException:\\n    return HTTPException(\\n        status_code=status.HTTP_409_CONFLICT,\\n        detail={\\n            \\\"error\\\": \\\"Job is not resumable\\\",\\n            \\\"code\\\": \\\"NOT_RESUMABLE\\\",\\n            \\\"message\\\": \\\"Job is not suspended, already resumed, or the request_id is stale.\\\",\\n            \\\"job_id\\\": job_id,\\n        },\\n    )\\n\\n\\nclass DurableServeWorkflowHost(ServeWorkflowHost):\\n    \\\"\\\"\\\"Serve host with durable background runs on the SQLite substrate.\\\"\\\"\\\"\\n\\n    supports_background = True\\n\\n    def __init__(self, registry, verify_api_key, *, db_path: Path) -> None:\\n        super().__init__(registry, verify_api_key)\\n        self.jobs = SqliteDurableJobStore(db_path)\\n        self.checkpoints = SqliteCheckpointStore(db_path)\\n        self._tasks: dict[str, asyncio.Task] = {}\\n        # Agent pause blobs resolve via get_checkpoint_service() -> the module fallback\\n        # store; without this they land in-memory and do not survive a restart.\\n        set_default_checkpoint_store(self.checkpoints)\\n\\n    async def submit_background(\\n        self,\\n        parsed: ParsedWorkflowRun,\\n        flow: ResolvedFlow,\\n        caller: Any,\\n        *,\\n        stream_protocol: str,  # noqa: ARG002\\n    ) -> WorkflowJobResponse:\\n        await self._supersede_suspended(flow.flow_id)\\n        job_id = str(uuid4())\\n        await self.jobs.create_job(job_id=job_id, flow_id=flow.flow_id, user_id=self._run_user_id(caller) or \\\"\\\")\\n        self._spawn(job_id, self._run_job(job_id, flow.graph, parsed, caller))\\n        return create_job_response(job_id, flow.flow_id)\\n\\n    async def _supersede_suspended(self, flow_id: str) -> None:\\n        \\\"\\\"\\\"Cancel this flow's stale suspended runs so a rerun replaces the pause.\\n\\n        A suspended run holds a pause nobody will answer once the flow is rerun;\\n        left alive it piles up in every pending surface. serve has a single API-key\\n        identity, so the scope is the flow (the langflow backend scopes by user too).\\n\\n        The conditional claim keeps supersede-vs-resume safe: a resume that flipped\\n        the row IN_PROGRESS between the select and this loop keeps its run, and no\\n        STOP signal is written that its continuation could later consume.\\n        \\\"\\\"\\\"\\n        for stale_job_id in await self.jobs.suspended_job_ids_for_flow(flow_id):\\n            if not await self.jobs.claim_suspended_for_cancel(stale_job_id):\\n                continue\\n            await self.jobs.write_signal(stale_job_id, SignalType.STOP)\\n            task = self._tasks.get(stale_job_id)\\n            if task is not None and not task.done():\\n                task.cancel()\\n            await self.jobs.update_metadata(stale_job_id, {\\\"pending\\\": None})\\n\\n    async def get_job_status(\\n        self,\\n        job_id: str,\\n        caller: Any,  # noqa: ARG002\\n        session: Any,  # noqa: ARG002\\n    ) -> WorkflowExecutionResponse | WorkflowJobResponse:\\n        job = await self.jobs.get_job(job_id)\\n        if job is None:\\n            raise _job_not_found(job_id)\\n        if job.status == DurableJobStatus.COMPLETED and job.result:\\n            return workflow_response_from_output_events(\\n                job.result.get(\\\"output_events\\\", []), flow_id=job.flow_id, job_id=job_id\\n            )\\n        errors = [ErrorDetail(error=job.error.get(\\\"error\\\", \\\"unknown error\\\"))] if job.error else []\\n        return WorkflowJobResponse(\\n            job_id=job_id,\\n            flow_id=job.flow_id,\\n            status=JobStatus(job.status.value),\\n            errors=errors,\\n        )\\n\\n    async def stop_job(self, job_id: str, caller: Any) -> WorkflowStopResponse:  # noqa: ARG002\\n        job = await self.jobs.get_job(job_id)\\n        if job is None:\\n            raise _job_not_found(job_id)\\n        await self.jobs.write_signal(job_id, SignalType.STOP)\\n        task = self._tasks.get(job_id)\\n        if task is not None and not task.done():\\n            task.cancel()\\n        if job.status in _NON_TERMINAL:\\n            await self.jobs.update_status(job_id, DurableJobStatus.CANCELLED)\\n        return WorkflowStopResponse(job_id=job_id, message=\\\"Stop signal recorded; job cancelled.\\\")\\n\\n    async def pending_request(self, job_id: str) -> dict[str, Any]:\\n        job = await self.jobs.get_job(job_id)\\n        if job is None:\\n            raise _job_not_found(job_id)\\n        pending = (job.job_metadata or {}).get(\\\"pending\\\")\\n        if job.status != DurableJobStatus.SUSPENDED or not pending:\\n            raise HTTPException(\\n                status_code=status.HTTP_404_NOT_FOUND,\\n                detail={\\\"error\\\": \\\"No pending human input\\\", \\\"code\\\": \\\"NO_PENDING_REQUEST\\\", \\\"job_id\\\": job_id},\\n            )\\n        return pending\\n\\n    async def stream_events(self, job_id: str, *, last_event_id: str | None) -> StreamingResponse:\\n        \\\"\\\"\\\"Replay the durable event log as SSE, tailing until the run ends or suspends.\\n\\n        Backs the advertised ``links.events`` URL: events are read from the job's\\n        ``job_events`` log after ``Last-Event-ID`` and streamed with the seq as the\\n        SSE id, so a reconnect resumes exactly where it left off.\\n        \\\"\\\"\\\"\\n        if await self.jobs.get_job(job_id) is None:\\n            raise _job_not_found(job_id)\\n        return StreamingResponse(\\n            self._event_frames(job_id, after_seq=_parse_last_event_id(last_event_id)),\\n            media_type=\\\"text/event-stream\\\",\\n            headers={\\\"Cache-Control\\\": \\\"no-cache\\\", \\\"X-Accel-Buffering\\\": \\\"no\\\"},\\n        )\\n\\n    async def _event_frames(self, job_id: str, *, after_seq: int) -> AsyncIterator[bytes]:\\n        seq = after_seq\\n        while True:\\n            events = await self.jobs.read_events(job_id, after_seq=seq)\\n            for event in events:\\n                yield _sse_for(event)\\n            if events:\\n                seq = events[-1].seq\\n            job = await self.jobs.get_job(job_id)\\n            if job is None or job.status not in _STREAMING_ACTIVE:\\n                # Status flips only after its terminal/pause event is appended, so a\\n                # final drain catches an event written between the read above and now.\\n                for event in await self.jobs.read_events(job_id, after_seq=seq):\\n                    yield _sse_for(event)\\n                return\\n            await asyncio.sleep(_EVENT_POLL_INTERVAL_S)\\n\\n    async def resume_job(self, job_id: str, request: WorkflowResumeRequest) -> WorkflowResumeResponse:\\n        job = await self.jobs.get_job(job_id)\\n        if job is None:\\n            raise _job_not_found(job_id)\\n        pending = (job.job_metadata or {}).get(\\\"pending\\\") or {}\\n        if pending.get(\\\"request_id\\\") != request.request_id:\\n            raise _not_resumable(job_id)\\n        allowed = pending.get(\\\"allowed_decisions\\\") or []\\n        if allowed and (request.decision or {}).get(\\\"action_id\\\") not in allowed:\\n            raise HTTPException(\\n                status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,\\n                detail={\\n                    \\\"error\\\": \\\"Invalid decision\\\",\\n                    \\\"code\\\": \\\"INVALID_DECISION\\\",\\n                    \\\"message\\\": \\\"decision.action_id is not one of the pending request's allowed_decisions.\\\",\\n                    \\\"job_id\\\": job_id,\\n                },\\n            )\\n        if not await self.jobs.claim_suspended_for_resume(job_id):\\n            raise _not_resumable(job_id)\\n\\n        run_id = (job.job_metadata or {}).get(\\\"run_id\\\")\\n        checkpoint = await self.checkpoints.load_by_run_id(run_id) if run_id else None\\n        if checkpoint is None:\\n            await self.jobs.set_error(job_id, {\\\"error\\\": \\\"Paused run has no recoverable checkpoint.\\\"})\\n            raise _not_resumable(job_id)\\n\\n        graph = Graph.resume_from_checkpoint(checkpoint, checkpoint_store=self.checkpoints)\\n        self._attach_stores(job_id, graph)\\n        apply_run_defaults(\\n            graph, session_id=graph.session_id, user_id=job.user_id or None, overwrite_user_id=bool(job.user_id)\\n        )\\n        requested_action = (request.decision or {}).get(\\\"action_id\\\")\\n        decision = reroute_decision_on_timeout(pending, request.decision or {})\\n        if decision.get(\\\"action_id\\\") != requested_action:\\n            # The late answer was rerouted (fallback branch or the expired sentinel);\\n            # record why, so /events readers can tell an expiry from an empty-output run.\\n            await self.jobs.append_event(\\n                job_id,\\n                \\\"human_input_expired\\\",\\n                {\\n                    \\\"request_id\\\": request.request_id,\\n                    \\\"requested_action\\\": requested_action,\\n                    \\\"rerouted_to\\\": decision.get(\\\"action_id\\\"),\\n                    \\\"timeout_seconds\\\": pending.get(\\\"timeout_seconds\\\"),\\n                },\\n            )\\n        graph.human_input_decisions = {\\n            **(getattr(graph, \\\"human_input_decisions\\\", {}) or {}),\\n            request.request_id: decision,\\n        }\\n        for vertex in graph.vertices:\\n            if request_id_targets_vertex(request.request_id, vertex.id, str(graph.run_id)):\\n                vertex.built = False\\n        # Re-run the fixpoint post-un-build: a dropped producer feeding only the request\\n        # vertex was still built at restore time, and its restored None would crash the re-run.\\n        _unbuild_needed_dropped_producers(graph)\\n        await self.jobs.update_metadata(job_id, {\\\"pending\\\": None})\\n        await self.jobs.append_event(job_id, \\\"human_input_decision\\\", {\\\"request_id\\\": request.request_id, **decision})\\n        self._spawn(job_id, self._drive(job_id, graph))\\n        return WorkflowResumeResponse(job_id=job_id, status=\\\"resuming\\\", message=\\\"Resume accepted\\\")\\n\\n    def _spawn(self, job_id: str, coro) -> None:\\n        task = asyncio.create_task(coro)\\n        self._tasks[job_id] = task\\n        task.add_done_callback(lambda _t: self._tasks.pop(job_id, None))\\n\\n    def _attach_stores(self, job_id: str, graph: Graph) -> None:\\n        graph.job_id = job_id\\n        graph.checkpointing_enabled = True\\n        graph.checkpoint_store = self.checkpoints\\n\\n    async def _run_job(self, job_id: str, graph: Graph, parsed: ParsedWorkflowRun, caller: Any) -> None:\\n        await self.jobs.update_status(job_id, DurableJobStatus.IN_PROGRESS)\\n        from lfx.cli.runtime_variables import apply_global_vars_to_graph\\n\\n        self._attach_stores(job_id, graph)\\n        user_id = self._run_user_id(caller)\\n        apply_run_defaults(graph, session_id=parsed.session_id, user_id=user_id, overwrite_user_id=user_id is not None)\\n        apply_global_vars_to_graph(graph, parsed.globals)\\n        if parsed.input_value:\\n            graph._set_inputs([], {INPUT_FIELD_NAME: parsed.input_value}, \\\"chat\\\")  # noqa: SLF001\\n        await self._drive(job_id, graph)\\n\\n    async def _drive(self, job_id: str, graph: Graph) -> None:\\n        \\\"\\\"\\\"Run the graph to its next terminal state and persist it on the job row.\\\"\\\"\\\"\\n        from lfx.cli.runtime_variables import build_request_variables_from_global_vars\\n\\n        scope_vars = build_request_variables_from_global_vars(graph.context.get(\\\"request_variables\\\"))\\n        scope_token = activate_request_variables(scope_vars or None)\\n        no_env_token = activate_no_env_fallback(disabled=bool(graph.context.get(\\\"no_env_fallback\\\")))\\n        try:\\n            # Graph.process is a third entry point alongside async_start and arun, and the one the\\n            # durable/background path uses, so it needs its own application span or every job run\\n            # here is invisible to the operator's APM.\\n            with execution_protocol(\\\"lfx.serve\\\"), graph.flow_execution_span():\\n                await graph.process(fallback_to_env_vars=False)\\n        except GraphPausedException as pause:\\n            data = pause.data or {}\\n            await self.jobs.update_metadata(job_id, {\\\"run_id\\\": str(graph.run_id), \\\"pending\\\": data})\\n            await self.jobs.append_event(job_id, \\\"human_input_request\\\", data)\\n            await self.jobs.update_status(job_id, DurableJobStatus.SUSPENDED)\\n            return\\n        except asyncio.CancelledError:\\n            await self.jobs.update_status(job_id, DurableJobStatus.CANCELLED)\\n            raise\\n        except Exception as exc:  # noqa: BLE001\\n            logger.error(f\\\"Durable background job {job_id} failed: {exc}\\\")\\n            await self.jobs.set_error(job_id, {\\\"error\\\": str(exc), \\\"type\\\": type(exc).__name__})\\n            return\\n        finally:\\n            reset_no_env_fallback(no_env_token)\\n            reset_request_variables(scope_token)\\n        await self._complete(job_id, graph)\\n\\n    async def _complete(self, job_id: str, graph: Graph) -> None:\\n        output_events: list[dict[str, Any]] = []\\n        for vertex in graph.vertices:\\n            is_terminal = not graph.successor_map.get(vertex.id, [])\\n            if not is_terminal or not vertex.built or vertex.result is None:\\n                continue\\n            component_id, component_output = _process_terminal_vertex(vertex, {vertex.id: vertex.result})\\n            output_events.append({\\\"component_id\\\": component_id, **component_output.model_dump()})\\n        await self.jobs.append_event(job_id, \\\"end\\\", {})\\n        await self.jobs.set_result(job_id, {\\\"output_events\\\": output_events})\\n\\n\\ndef _register_resume_routes(router: APIRouter, host: DurableServeWorkflowHost) -> None:\\n    @router.post(\\\"/{job_id}/resume\\\", summary=\\\"Resume Workflow (v2 human-in-the-loop)\\\")\\n    async def resume_workflow(job_id: str, request: WorkflowResumeRequest, http_request: Request):\\n        await host.resolve_caller(http_request)\\n        return await host.resume_job(job_id, request)\\n\\n    @router.get(\\\"/{job_id}/pending\\\", summary=\\\"Pending human-input request (v2 background)\\\")\\n    async def pending_request(job_id: str, http_request: Request):\\n        await host.resolve_caller(http_request)\\n        return await host.pending_request(job_id)\\n\\n    @router.get(\\\"/{job_id}/events\\\", response_model=None, summary=\\\"Re-attach to a background run (v2 SSE)\\\")\\n    async def stream_events(job_id: str, http_request: Request):\\n        await host.resolve_caller(http_request)\\n        return await host.stream_events(job_id, last_event_id=http_request.headers.get(\\\"Last-Event-ID\\\"))\\n\\n\\ndef create_durable_workflow_router(registry, verify_api_key, *, db_path: Path) -> APIRouter:\\n    \\\"\\\"\\\"The v2 workflow router for serve with durable background + HITL resume routes.\\\"\\\"\\\"\\n    host = DurableServeWorkflowHost(registry, verify_api_key, db_path=db_path)\\n    router = create_workflow_router(host, developer_api_guard=False)\\n    _register_resume_routes(router, host)\\n    return router\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/serve_gunicorn.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3fe07df9ca896d7cf20eda377a1e3e23551b9af85d12d7d7a43356cbed983b4\",\"content\":\"\\\"\\\"\\\"gunicorn process manager for ``lfx serve --workers N`` on Unix.\\n\\nUses ``preload_app=True`` so the master builds the warm app once and forks\\nworkers (copy-on-write). ``--max-requests`` recycles workers to bound memory (worker\\nhygiene, not per-request isolation \u2014 see ``_launch_workers`` for the isolation story).\\n\\nThe ``pre_fork`` hook (mirrors ``langflow.server.LangflowApplication``) runs in\\nthe master immediately before each worker is forked: it ``gc.freeze()``s the\\nfully-built, warmed preload heap so workers inherit it via copy-on-write without\\nthe GC dirtying shared pages (preserving the preload memory savings), and warns\\nabout any fork-unsafe state \u2014 background threads or open TCP connections (e.g. a\\nDB connection pool) left alive in the master, which would be silently dead or\\ncorrupt in the forked workers.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom gunicorn.app.base import BaseApplication\\nfrom uvicorn.workers import UvicornWorker\\n\\n\\nclass LFXUvicornWorker(UvicornWorker):\\n    \\\"\\\"\\\"Async worker class for ``lfx serve --workers N`` (the default, non-sync path).\\n\\n    A thin named subclass of gunicorn's ``UvicornWorker`` so the worker class is owned\\n    here and can host per-worker customization if needed later.\\n    \\\"\\\"\\\"\\n\\n\\nclass LFXGunicornApp(BaseApplication):\\n    def __init__(self, app_import_string: str, options: dict) -> None:\\n        self._app_import_string = app_import_string\\n        self._options = options or {}\\n        # Freeze + fork-safety diagnostics happen in the master right before each\\n        # fork. Doing the freeze here (not at app-import time) means the fully\\n        # warmed preload heap is frozen immediately before fork, so workers still\\n        # inherit it via copy-on-write \u2014 the preload memory savings are preserved.\\n        self._options.setdefault(\\\"pre_fork\\\", self.pre_fork)\\n        super().__init__()\\n\\n    # Thread-name prefixes known to be benign before fork: they never survive into\\n    # workers and produce no side effects when their fd is inherited.\\n    _BENIGN_THREAD_PREFIXES = (\\n        \\\"OTel\\\",  # OpenTelemetry SDK (BatchSpanProcessor, etc.)\\n        \\\"opentelemetry\\\",  # alternate OTel naming\\n        \\\"prometheus\\\",  # Prometheus client background threads\\n        \\\"loguru\\\",  # loguru enqueue=True worker\\n        \\\"asyncio\\\",  # event-loop helper threads (Python internals)\\n        \\\"ThreadPoolExecutor\\\",  # stdlib executor - harmless in parent\\n        \\\"concurrent.futures\\\",  # same pool, different prefix\\n    )\\n\\n    @classmethod\\n    def _is_benign_thread(cls, thread) -> bool:\\n        if any(thread.name.startswith(prefix) for prefix in cls._BENIGN_THREAD_PREFIXES):\\n            return True\\n        # gunicorn's own master-only threads (e.g. the control-socket server's `_run_loop`,\\n        # added in gunicorn 23) are managed by gunicorn's own fork handlers and are meant to\\n        # be absent in workers \u2014 they are gunicorn infrastructure, not app state to flag.\\n        target = getattr(thread, \\\"_target\\\", None)\\n        return (getattr(target, \\\"__module__\\\", \\\"\\\") or \\\"\\\").startswith(\\\"gunicorn\\\")\\n\\n    @classmethod\\n    def pre_fork(cls, server, _worker) -> None:\\n        \\\"\\\"\\\"Run in the master before each fork: warn on fork-unsafe state, then freeze.\\n\\n        Any non-benign background thread or non-listening TCP connection still alive\\n        here will be dead/corrupt in the forked workers (e.g. a DB engine pool opened\\n        during preload). lfx serve is DB-less by default and opens nothing fork-unsafe\\n        at preload, so this is normally silent \u2014 but it loudly flags the day something\\n        leaves a live connection or thread in the master.\\n        \\\"\\\"\\\"\\n        import gc\\n        import threading\\n\\n        non_main = [t for t in threading.enumerate() if t.is_alive() and t is not threading.main_thread()]\\n        suspicious = [t for t in non_main if not cls._is_benign_thread(t)]\\n        if suspicious:\\n            server.log.warning(\\n                \\\"Ghost threads found before fork (these will be dead in workers): %s\\\",\\n                [t.name for t in suspicious],\\n            )\\n\\n        try:\\n            import psutil\\n\\n            ghost_conns = [c for c in psutil.Process().net_connections(kind=\\\"tcp\\\") if c.status != \\\"LISTEN\\\"]\\n            if ghost_conns:\\n                server.log.warning(\\n                    \\\"Ghost TCP connections found before fork (these will be dead/corrupt in workers): %s\\\",\\n                    [(c.laddr, c.raddr, c.status) for c in ghost_conns],\\n                )\\n        except ImportError:\\n            server.log.debug(\\\"psutil not installed; skipping ghost TCP connection check\\\")\\n        except Exception as e:  # noqa: BLE001\\n            server.log.warning(\\\"Failed to inspect TCP connections before fork: %s\\\", e)\\n\\n        try:\\n            gc.collect()\\n        except Exception as e:  # noqa: BLE001\\n            server.log.warning(\\\"gc.collect() raised during pre-fork hook: %s\\\", e)\\n        gc.freeze()\\n\\n    def load_config(self) -> None:\\n        for key, value in self._options.items():\\n            if value is not None and key in self.cfg.settings:\\n                self.cfg.set(key, value)\\n\\n    def load(self):\\n        # preload_app=True -> gunicorn imports this \\\"module:attr\\\" string in the master\\n        # pre-fork. The async path passes the ASGI app (\\\"...:app\\\"); --use-sync-workers\\n        # passes the WSGI bridge (\\\"...:wsgi_application\\\"). Honor whichever was given\\n        # rather than hardcoding one, so the worker gets the callable it expects.\\n        import importlib\\n\\n        module_str, _, attr = self._app_import_string.partition(\\\":\\\")\\n        module = importlib.import_module(module_str)\\n        return getattr(module, attr)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/serve_identity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"871252aa57a8e3554aaee1ebda9868cb8e55dc1e4b8591674ecc495006bb403d\",\"content\":\"\\\"\\\"\\\"Per-user identity forwarding for ``lfx serve``.\\n\\nThis module lets ``lfx serve`` *consume* an upstream identity and thread it\\ninto flow execution as ``user_id``.\\n\\nTwo modes carry identity, plus an off switch:\\n\\n``off``\\n    Default. No identity is read; ``user_id`` stays ``None`` and behavior is\\n    byte-for-byte identical to a server without this module.\\n\\n``jwt``\\n    A signed JWT (``Authorization: Bearer`` or a configured header) is verified\\n    against the issuer's JWKS before its identity claim is trusted. Missing or\\n    invalid tokens are rejected with 401. This is the recommended secure mode\\n    when identity forwarding is enabled (note: ``off`` is the actual default).\\n\\n``header``\\n    A plain gateway header (e.g. ``X-Consumer-Username``) is trusted verbatim.\\n    This is the *weaker* mode \u2014 its safety rests entirely on network topology\\n    (the gateway being the only reachable caller), so it logs a loud startup\\n    warning naming that assumption. It exists because Kong OSS key-auth callers\\n    have no JWT.\\n\\nThe verifier owns a small, per-process, TTL'd JWKS cache. It is prefetched at\\nstartup so the first request never pays the fetch round-trip, and JWKS fetch\\nfailures degrade the *request* (401), never the server.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport time\\nfrom dataclasses import dataclass, field\\nfrom typing import TYPE_CHECKING, ClassVar, Literal\\n\\nimport httpx\\nimport jwt\\nfrom fastapi import HTTPException\\n\\nfrom lfx.log.logger import logger\\n\\nif TYPE_CHECKING:\\n    from collections.abc import Callable, Mapping\\n\\nIdentityMode = Literal[\\\"off\\\", \\\"jwt\\\", \\\"header\\\"]\\n\\n# Only asymmetric signatures. Pinning these kills the two classic JWT forgeries:\\n# ``alg: none`` (no signature) and HMAC alg-confusion (signing with the public\\n# key as an HMAC secret). HS256/384/512 and none are rejected before any crypto.\\nALLOWED_ALGORITHMS: tuple[str, ...] = (\\\"RS256\\\", \\\"ES256\\\")\\n\\n# JWKS cache TTL and the minimum spacing between forced refreshes triggered by an\\n# unknown ``kid``. The TTL keeps keys fresh through rotation; the refresh floor\\n# stops a caller spamming bogus ``kid``s from hammering the issuer's JWKS endpoint.\\n_JWKS_TTL_SECONDS = 3600.0\\n_JWKS_MIN_REFRESH_INTERVAL_SECONDS = 10.0\\n\\n_HTTP_TIMEOUT_SECONDS = 10.0\\n\\n# Env var names used to round-trip identity config into uvicorn worker processes\\n# (same mechanism as ``LFX_SERVE_NO_ENV_FALLBACK``).\\nENV_MODE = \\\"LFX_SERVE_IDENTITY_MODE\\\"\\nENV_JWT_ISSUER = \\\"LFX_SERVE_IDENTITY_JWT_ISSUER\\\"\\nENV_JWT_AUDIENCE = \\\"LFX_SERVE_IDENTITY_JWT_AUDIENCE\\\"\\nENV_JWT_JWKS_URL = \\\"LFX_SERVE_IDENTITY_JWT_JWKS_URL\\\"\\nENV_CLAIM = \\\"LFX_SERVE_IDENTITY_CLAIM\\\"\\nENV_JWT_HEADER = \\\"LFX_SERVE_IDENTITY_JWT_HEADER\\\"\\nENV_TRUSTED_HEADER = \\\"LFX_SERVE_IDENTITY_HEADER\\\"\\nENV_ALLOW_INSECURE_HTTP = \\\"LFX_SERVE_IDENTITY_ALLOW_INSECURE_HTTP\\\"\\n\\n# Every identity env key \u2014 used by the parent to clean up after uvicorn.run().\\nIDENTITY_ENV_KEYS: tuple[str, ...] = (\\n    ENV_MODE,\\n    ENV_JWT_ISSUER,\\n    ENV_JWT_AUDIENCE,\\n    ENV_JWT_JWKS_URL,\\n    ENV_CLAIM,\\n    ENV_JWT_HEADER,\\n    ENV_TRUSTED_HEADER,\\n    ENV_ALLOW_INSECURE_HTTP,\\n)\\n\\n\\nclass IdentityConfigError(ValueError):\\n    \\\"\\\"\\\"Raised when identity options are incomplete or inconsistent.\\\"\\\"\\\"\\n\\n\\ndef _fetch_json(url: str) -> dict:\\n    \\\"\\\"\\\"Fetch and parse a JSON document over http(s).\\n\\n    Only http/https URLs are allowed \u2014 the scheme guard prevents ``file://``/``ftp://``\\n    smuggling via a misconfigured issuer or JWKS URL.\\n\\n    Redirects are NOT followed. Following a redirect would let a misconfigured or\\n    malicious issuer downgrade ``https://`` \u2192 ``http://`` (or point off-host), and the\\n    plaintext follow-up request would already be on the wire before any scheme check\\n    could run. We reject the redirect instead so the fetch fails closed rather than\\n    silently downgrading the transport.\\n    \\\"\\\"\\\"\\n    if not url.lower().startswith((\\\"http://\\\", \\\"https://\\\")):\\n        msg = f\\\"Refusing to fetch non-http(s) URL: {url!r}\\\"\\n        raise IdentityConfigError(msg)\\n    with httpx.Client(timeout=_HTTP_TIMEOUT_SECONDS, follow_redirects=False) as client:\\n        resp = client.get(url)\\n        if resp.is_redirect:\\n            location = resp.headers.get(\\\"location\\\", \\\"\\\")\\n            msg = f\\\"Refusing to follow redirect from {url!r} to {location!r} (possible transport downgrade).\\\"\\n            raise IdentityConfigError(msg)\\n        resp.raise_for_status()\\n        return resp.json()\\n\\n\\n@dataclass(frozen=True)\\nclass IdentityConfig:\\n    \\\"\\\"\\\"Immutable identity-layer configuration resolved at serve startup.\\\"\\\"\\\"\\n\\n    mode: IdentityMode = \\\"off\\\"\\n    jwt_issuer: str | None = None\\n    jwt_audience: str | None = None\\n    jwt_jwks_url: str | None = None\\n    claim: str = \\\"sub\\\"\\n    # Header the JWT is read from in ``jwt`` mode (Bearer prefix stripped if present).\\n    jwt_header: str = \\\"Authorization\\\"\\n    # Header trusted verbatim in ``header`` mode.\\n    trusted_header: str = \\\"X-Consumer-Username\\\"\\n    # Allow plaintext http:// for the JWKS/issuer (dev/test only). Off by default:\\n    # a MITM of a plaintext JWKS response forges identities, so HTTPS is required.\\n    allow_insecure_http: bool = False\\n\\n    def _require_fetch_scheme(self, label: str, url: str) -> None:\\n        \\\"\\\"\\\"Reject a fetched URL whose scheme violates the transport policy.\\n\\n        HTTPS is required by default; ``http://`` is permitted only when\\n        ``allow_insecure_http`` is set. Non-http(s) schemes are always refused.\\n        \\\"\\\"\\\"\\n        allowed = (\\\"http://\\\", \\\"https://\\\") if self.allow_insecure_http else (\\\"https://\\\",)\\n        if not url.lower().startswith(allowed):\\n            scheme = \\\"an http(s)\\\" if self.allow_insecure_http else \\\"an https\\\"\\n            hint = \\\"\\\" if self.allow_insecure_http else \\\" Pass --identity-jwt-allow-insecure-http for local/dev http://.\\\"\\n            msg = f\\\"{label} must be {scheme} URL, got {url!r}.{hint}\\\"\\n            raise IdentityConfigError(msg)\\n\\n    def __post_init__(self) -> None:\\n        if self.mode not in (\\\"off\\\", \\\"jwt\\\", \\\"header\\\"):\\n            msg = f\\\"Unknown identity mode {self.mode!r}; expected off, jwt, or header.\\\"\\n            raise IdentityConfigError(msg)\\n        if self.mode == \\\"jwt\\\":\\n            if not self.jwt_issuer:\\n                msg = \\\"--identity-jwt-issuer is required when --identity-mode=jwt.\\\"\\n                raise IdentityConfigError(msg)\\n            if not self.jwt_audience:\\n                msg = \\\"--identity-jwt-audience is required when --identity-mode=jwt.\\\"\\n                raise IdentityConfigError(msg)\\n            if not self.claim:\\n                msg = \\\"--identity-claim must be non-empty when --identity-mode=jwt.\\\"\\n                raise IdentityConfigError(msg)\\n            # Validate the fetched URL scheme offline so a bad scheme (e.g. file://)\\n            # or an insecure http:// fails at startup rather than masquerading as a\\n            # transient fetch error later. An explicit jwks_url is fetched directly;\\n            # otherwise the issuer is fetched for OIDC discovery, so it must comply too.\\n            if self.jwt_jwks_url:\\n                self._require_fetch_scheme(\\\"--identity-jwt-jwks-url\\\", self.jwt_jwks_url)\\n            else:\\n                self._require_fetch_scheme(\\\"--identity-jwt-issuer (used for OIDC discovery)\\\", self.jwt_issuer)\\n        if self.mode == \\\"header\\\" and not self.trusted_header:\\n            msg = \\\"--identity-header must be non-empty when --identity-mode=header.\\\"\\n            raise IdentityConfigError(msg)\\n\\n    @property\\n    def enabled(self) -> bool:\\n        return self.mode != \\\"off\\\"\\n\\n    def to_env(self) -> dict[str, str]:\\n        \\\"\\\"\\\"Serialize to env vars for the uvicorn worker round-trip.\\n\\n        Only ``off`` emits a lone mode key; richer modes emit their settings so a\\n        worker's :meth:`from_env` reconstructs an identical config.\\n        \\\"\\\"\\\"\\n        env = {ENV_MODE: self.mode}\\n        if self.mode == \\\"off\\\":\\n            return env\\n        if self.jwt_issuer:\\n            env[ENV_JWT_ISSUER] = self.jwt_issuer\\n        if self.jwt_audience:\\n            env[ENV_JWT_AUDIENCE] = self.jwt_audience\\n        if self.jwt_jwks_url:\\n            env[ENV_JWT_JWKS_URL] = self.jwt_jwks_url\\n        env[ENV_CLAIM] = self.claim\\n        env[ENV_JWT_HEADER] = self.jwt_header\\n        env[ENV_TRUSTED_HEADER] = self.trusted_header\\n        if self.allow_insecure_http:\\n            env[ENV_ALLOW_INSECURE_HTTP] = \\\"1\\\"\\n        return env\\n\\n    @classmethod\\n    def from_env(cls, environ: Mapping[str, str]) -> IdentityConfig:\\n        \\\"\\\"\\\"Reconstruct config from worker env vars; absence \u21d2 ``off``.\\\"\\\"\\\"\\n        mode = environ.get(ENV_MODE, \\\"off\\\")\\n        if mode == \\\"off\\\":\\n            return cls(mode=\\\"off\\\")\\n        defaults = cls()\\n        return cls(\\n            mode=mode,  # type: ignore[arg-type]\\n            jwt_issuer=environ.get(ENV_JWT_ISSUER),\\n            jwt_audience=environ.get(ENV_JWT_AUDIENCE),\\n            jwt_jwks_url=environ.get(ENV_JWT_JWKS_URL),\\n            claim=environ.get(ENV_CLAIM, defaults.claim),\\n            jwt_header=environ.get(ENV_JWT_HEADER, defaults.jwt_header),\\n            trusted_header=environ.get(ENV_TRUSTED_HEADER, defaults.trusted_header),\\n            allow_insecure_http=environ.get(ENV_ALLOW_INSECURE_HTTP) == \\\"1\\\",\\n        )\\n\\n\\nclass _SigningKeyUnavailableError(Exception):\\n    \\\"\\\"\\\"Internal: no signing key for the presented ``kid`` (after a bounded refresh).\\\"\\\"\\\"\\n\\n\\n@dataclass\\nclass _JwksCache:\\n    \\\"\\\"\\\"A per-process, TTL'd cache of the issuer's signing keys.\\n\\n    Holds a parsed ``PyJWKSet``. Refreshes on TTL expiry and, at most once per\\n    cooldown window, when a request presents an unknown ``kid`` (key rotation).\\n    Fetch failures keep the existing keys and surface as a per-request error.\\n\\n    The stale/cold-cache and unknown-``kid`` fetch paths have independent\\n    cooldown floors (``_last_stale_fetch_at`` / ``_last_unknown_refresh_at``),\\n    each allowing one fetch per ``min_refresh_interval`` \u2014 so the worst case is\\n    ~two fetches per window, not one, which still bounds a JWKS outage away from\\n    a per-request fetch storm. The floors are best-effort and lock-free: under\\n    concurrent requests two threads can both decide to fetch, so the cap is\\n    approximate, not exact (a redundant fetch is harmless; a lock around the\\n    blocking fetch would be worse).\\n    \\\"\\\"\\\"\\n\\n    fetch_jwks: Callable[[], dict]\\n    ttl_seconds: float = _JWKS_TTL_SECONDS\\n    min_refresh_interval: float = _JWKS_MIN_REFRESH_INTERVAL_SECONDS\\n    source_label: str = \\\"the JWKS endpoint\\\"  # human-readable source for log messages\\n    _jwk_set: jwt.PyJWKSet | None = field(default=None, init=False)\\n    _fetched_at: float | None = field(default=None, init=False)\\n    _last_stale_fetch_at: float | None = field(default=None, init=False)\\n    _last_unknown_refresh_at: float | None = field(default=None, init=False)\\n\\n    def _fetch_into_cache(self) -> None:\\n        \\\"\\\"\\\"Best-effort refresh. On failure, keep the existing keys and log loudly.\\n\\n        A permanent configuration error (bad/undiscoverable JWKS source) is logged\\n        distinctly from a transient transport/parse failure, so the operator isn't\\n        told to wait for a recovery that can never come. Either way the cache is\\n        left intact and requests fail closed (401); serving never aborts here.\\n        Unexpected exceptions are intentionally NOT swallowed \u2014 they surface as a\\n        real error rather than a silent \\\"keeping cached keys\\\" line.\\n        \\\"\\\"\\\"\\n        try:\\n            data = self.fetch_jwks()\\n            # Guard the shape before PyJWKSet.from_dict: a non-object JWKS (e.g. a\\n            # JSON array) makes from_dict raise an uncaught AttributeError that\\n            # would abort startup or 500 a request instead of failing closed.\\n            if not isinstance(data, dict):\\n                msg = f\\\"{self.source_label} returned a non-object JSON document (expected a JWKS).\\\"\\n                raise IdentityConfigError(msg)\\n            self._jwk_set = jwt.PyJWKSet.from_dict(data)\\n            self._fetched_at = time.monotonic()\\n        except IdentityConfigError as exc:\\n            logger.error(\\n                f\\\"JWKS source is misconfigured ({self.source_label}): {exc} \\\"\\n                \\\"This is a configuration error, not a transient outage \u2014 requests will be \\\"\\n                \\\"rejected (401) until it is fixed.\\\"\\n            )\\n        except (httpx.HTTPError, OSError, TimeoutError, json.JSONDecodeError, jwt.PyJWTError) as exc:\\n            logger.error(\\n                f\\\"JWKS refresh from {self.source_label} failed ({type(exc).__name__}: {exc}); keeping cached keys.\\\"\\n            )\\n\\n    def prefetch(self) -> bool:\\n        \\\"\\\"\\\"Warm the cache at startup. Logs an error if it stays empty, never raises.\\n\\n        Returns ``True`` if the cache holds keys after the attempt, ``False`` if it\\n        stayed empty, so callers can surface a startup warning on a guaranteed channel.\\n        \\\"\\\"\\\"\\n        self._fetch_into_cache()\\n        if self._jwk_set is None:\\n            logger.error(\\n                \\\"JWKS prefetch failed; serving will start but JWT verification will reject requests \\\"\\n                \\\"(401) until the JWKS endpoint recovers.\\\"\\n            )\\n            return False\\n        return True\\n\\n    def _lookup(self, kid: str) -> jwt.PyJWK | None:\\n        if self._jwk_set is None:\\n            return None\\n        for key in self._jwk_set.keys:\\n            if key.key_id == kid:\\n                return key\\n        return None\\n\\n    def get_signing_key(self, kid: str) -> jwt.PyJWK:\\n        now = time.monotonic()\\n        # Stale/cold cache: refresh, but at most once per cooldown so a down issuer\\n        # cannot make every request pay its own blocking fetch. The floor is NOT\\n        # primed by prefetch(), so the first request after a failed prefetch still\\n        # refetches immediately and recovers.\\n        fetched_this_call = False\\n        stale = self._jwk_set is None or (self._fetched_at is not None and now - self._fetched_at > self.ttl_seconds)\\n        if stale and (\\n            self._last_stale_fetch_at is None or (now - self._last_stale_fetch_at) >= self.min_refresh_interval\\n        ):\\n            self._last_stale_fetch_at = now\\n            self._fetch_into_cache()\\n            fetched_this_call = True\\n\\n        key = self._lookup(kid)\\n        if key is not None:\\n            return key\\n\\n        # Unknown kid (key rotation): refresh at most once per cooldown window (DoS floor).\\n        # Skip if we already refetched above this call \u2014 it would hit the same endpoint.\\n        if not fetched_this_call and (\\n            self._last_unknown_refresh_at is None or (now - self._last_unknown_refresh_at) >= self.min_refresh_interval\\n        ):\\n            self._last_unknown_refresh_at = now\\n            self._fetch_into_cache()\\n            key = self._lookup(kid)\\n\\n        if key is None:\\n            raise _SigningKeyUnavailableError(kid)\\n        return key\\n\\n\\nclass IdentityVerifier:\\n    \\\"\\\"\\\"Resolves a verified ``user_id`` from request headers per :class:`IdentityConfig`.\\\"\\\"\\\"\\n\\n    _ALLOWED_ALGS: ClassVar[frozenset[str]] = frozenset(ALLOWED_ALGORITHMS)\\n\\n    def __init__(\\n        self,\\n        config: IdentityConfig,\\n        *,\\n        jwks_fetcher: Callable[[str], dict] | None = None,\\n        openid_fetcher: Callable[[str], dict] | None = None,\\n    ) -> None:\\n        self._config = config\\n        self._json_fetch = jwks_fetcher or _fetch_json\\n        self._openid_fetch = openid_fetcher or jwks_fetcher or _fetch_json\\n        self._resolved_jwks_url: str | None = config.jwt_jwks_url\\n        self._jwks: _JwksCache | None = None\\n        if config.mode == \\\"jwt\\\":\\n            source_label = config.jwt_jwks_url or f\\\"OIDC discovery from {config.jwt_issuer}\\\"\\n            self._jwks = _JwksCache(fetch_jwks=self._fetch_signing_jwks, source_label=source_label)\\n\\n    @property\\n    def config(self) -> IdentityConfig:\\n        return self._config\\n\\n    # -- startup -----------------------------------------------------------\\n\\n    def prefetch(self) -> bool:\\n        \\\"\\\"\\\"In ``jwt`` mode, warm the JWKS cache; otherwise a no-op.\\n\\n        Returns ``True`` when the cache is warm (or there is nothing to warm, as in\\n        ``header`` mode), ``False`` when a ``jwt``-mode prefetch left the cache empty.\\n        \\\"\\\"\\\"\\n        if self._jwks is not None:\\n            return self._jwks.prefetch()\\n        return True\\n\\n    def _resolve_jwks_url(self) -> str:\\n        if self._resolved_jwks_url:\\n            return self._resolved_jwks_url\\n        if not self._config.jwt_issuer:\\n            msg = \\\"Cannot resolve JWKS URL without an issuer.\\\"\\n            raise IdentityConfigError(msg)\\n        discovery_url = self._config.jwt_issuer.rstrip(\\\"/\\\") + \\\"/.well-known/openid-configuration\\\"\\n        document = self._openid_fetch(discovery_url)\\n        # A well-behaved discovery doc is a JSON object with a string jwks_uri.\\n        # Guard the shape so a malformed response (e.g. a JSON array) fails closed\\n        # as a config error instead of an uncaught AttributeError at request time.\\n        if not isinstance(document, dict):\\n            msg = f\\\"OIDC discovery at {discovery_url} returned a non-object document.\\\"\\n            raise IdentityConfigError(msg)\\n        jwks_uri = document.get(\\\"jwks_uri\\\")\\n        if not isinstance(jwks_uri, str) or not jwks_uri:\\n            msg = f\\\"OIDC discovery at {discovery_url} did not return a string jwks_uri.\\\"\\n            raise IdentityConfigError(msg)\\n        self._config._require_fetch_scheme(\\\"OIDC discovery jwks_uri\\\", jwks_uri)  # noqa: SLF001\\n        self._resolved_jwks_url = jwks_uri\\n        return jwks_uri\\n\\n    def _fetch_signing_jwks(self) -> dict:\\n        return self._json_fetch(self._resolve_jwks_url())\\n\\n    # -- per-request -------------------------------------------------------\\n\\n    def authenticate(self, headers: Mapping[str, str]) -> str | None:\\n        \\\"\\\"\\\"Return the caller's identity, or raise ``HTTPException(401)``.\\n\\n        ``off`` mode returns ``None`` (no identity); the caller treats that as\\n        \\\"no per-user attribution\\\", preserving the pre-identity behavior.\\n        \\\"\\\"\\\"\\n        if self._config.mode == \\\"off\\\":\\n            return None\\n        if self._config.mode == \\\"header\\\":\\n            return self._authenticate_header(headers)\\n        return self._authenticate_jwt(headers)\\n\\n    def _authenticate_header(self, headers: Mapping[str, str]) -> str:\\n        value = headers.get(self._config.trusted_header)\\n        if not value or not value.strip():\\n            raise HTTPException(status_code=401, detail=\\\"Missing identity header\\\")\\n        return value.strip()\\n\\n    def _extract_token(self, headers: Mapping[str, str]) -> str | None:\\n        raw = headers.get(self._config.jwt_header)\\n        if not raw:\\n            return None\\n        raw = raw.strip()\\n        if raw.lower().startswith(\\\"bearer \\\"):\\n            return raw[len(\\\"bearer \\\") :].strip()\\n        return raw\\n\\n    def _authenticate_jwt(self, headers: Mapping[str, str]) -> str:\\n        token = self._extract_token(headers)\\n        if not token:\\n            raise HTTPException(status_code=401, detail=\\\"Missing identity token\\\")\\n\\n        # Inspect the unverified header FIRST so alg-confusion and ``alg: none``\\n        # are rejected before any key resolution or crypto runs.\\n        try:\\n            unverified_header = jwt.get_unverified_header(token)\\n        except jwt.PyJWTError as exc:\\n            raise HTTPException(status_code=401, detail=\\\"Malformed identity token\\\") from exc\\n\\n        algorithm = unverified_header.get(\\\"alg\\\")\\n        if algorithm not in self._ALLOWED_ALGS:\\n            raise HTTPException(status_code=401, detail=\\\"Unsupported token algorithm\\\")\\n        kid = unverified_header.get(\\\"kid\\\")\\n        if not kid:\\n            raise HTTPException(status_code=401, detail=\\\"Token missing key id\\\")\\n\\n        if self._jwks is None:  # pragma: no cover - constructed for jwt mode\\n            raise HTTPException(status_code=401, detail=\\\"Identity verification unavailable\\\")\\n        try:\\n            signing_key = self._jwks.get_signing_key(kid)\\n        except _SigningKeyUnavailableError as exc:\\n            raise HTTPException(status_code=401, detail=\\\"Unknown token signing key\\\") from exc\\n\\n        try:\\n            claims = jwt.decode(\\n                token,\\n                signing_key.key,\\n                algorithms=list(ALLOWED_ALGORITHMS),\\n                audience=self._config.jwt_audience,\\n                issuer=self._config.jwt_issuer,\\n                leeway=60,\\n                options={\\\"require\\\": [\\\"exp\\\"], \\\"verify_aud\\\": True, \\\"verify_iss\\\": True},\\n            )\\n        except jwt.PyJWTError as exc:\\n            # Static detail only \u2014 never echo the token or signature material.\\n            raise HTTPException(status_code=401, detail=\\\"Invalid identity token\\\") from exc\\n\\n        identity = claims.get(self._config.claim)\\n        # Reject missing, empty, and whitespace-only string claims; a non-string claim\\n        # (e.g. a numeric sub) is left to str() below.\\n        if identity is None or (isinstance(identity, str) and not identity.strip()):\\n            raise HTTPException(status_code=401, detail=f\\\"Token missing claim '{self._config.claim}'\\\")\\n        return str(identity)\\n\\n\\ndef build_identity_verifier(config: IdentityConfig) -> IdentityVerifier | None:\\n    \\\"\\\"\\\"Construct a verifier for an enabled config, or ``None`` for ``off`` mode.\\\"\\\"\\\"\\n    if not config.enabled:\\n        return None\\n    return IdentityVerifier(config)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/serve_preloaded_app.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"75929bea781927698f317dc5e24a0d95a074294318668c5c36e0c97ebfa0f9f3\",\"content\":\"\\\"\\\"\\\"Import-time entrypoint for ``gunicorn --preload``.\\n\\ngunicorn's master imports this module ONCE before forking. Building + warming the\\nregistry here means the library, imported component modules, and warm flow graphs\\nall live in the master heap and are inherited by every forked worker via\\ncopy-on-write. Workers are recycled after ``--max-requests`` requests; each new fork\\nre-inherits this warm image.\\n\\nThe ``gc.freeze()`` that keeps this heap out of the GC (so refcount/GC traversal\\ndoesn't dirty the shared pages) is NOT done here \u2014 it runs in the gunicorn\\n``pre_fork`` hook (:meth:`lfx.cli.serve_gunicorn.LFXGunicornApp.pre_fork`), i.e.\\nin the master immediately before each fork, which is the correct point to freeze\\nthe fully-built heap while preserving copy-on-write sharing.\\n\\\"\\\"\\\"\\n\\nimport os\\n\\nfrom lfx.cli.serve_app import build_registry_from_env, create_multi_serve_app\\nfrom lfx.cli.serve_identity import IdentityConfig\\n\\nregistry = build_registry_from_env()\\n# Same env round-trip as the uvicorn factory (create_serve_app): _launch_workers\\n# exports LFX_SERVE_IDENTITY_* before importing this module for gunicorn --preload,\\n# so the warm shared app enforces the operator's identity config.\\napp = create_multi_serve_app(registry=registry, identity_config=IdentityConfig.from_env(os.environ))\\n\\n# WSGI bridge entrypoint for the opt-in ``lfx serve --use-sync-workers`` mode, which\\n# runs gunicorn's blocking ``sync`` worker so the kernel routes each request to an\\n# idle worker (an async worker keeps accepting connections while busy, which can\\n# queue a second request behind an in-flight one even when other workers are idle).\\n# The ASGI->WSGI bridge is created LAZILY on first request, never at preload: a2wsgi\\n# spins up a background event-loop thread, and threads do not survive fork(), so a\\n# bridge built in the preload master would be dead in every forked worker. Building\\n# it on first call constructs it inside the (post-fork) worker process instead.\\n_bridge = None\\n\\n\\ndef wsgi_application(environ, start_response):\\n    \\\"\\\"\\\"Lazily-constructed a2wsgi bridge wrapping the preloaded ASGI ``app``.\\\"\\\"\\\"\\n    global _bridge  # noqa: PLW0603\\n    if _bridge is None:\\n        try:\\n            from a2wsgi import ASGIMiddleware\\n        except ImportError as exc:  # pragma: no cover - exercised via --use-sync-workers without the dep\\n            msg = (\\n                \\\"lfx serve --use-sync-workers needs 'a2wsgi', which ships with lfx on Linux/macOS; \\\"\\n                \\\"it is missing, so reinstall lfx to restore your environment.\\\"\\n            )\\n            raise RuntimeError(msg) from exc\\n        _bridge = ASGIMiddleware(app)\\n    return _bridge(environ, start_response)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/status.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6056f11b92d37d91271138dd3f0a433d881358a5b146673aaf26a833f2cddb25\",\"content\":\"\\\"\\\"\\\"lfx status -- compare local flow files against a remote Langflow instance.\\n\\nShows, for each local flow JSON, whether it is in sync with the remote,\\nahead (locally modified), brand new (not yet pushed), or missing entirely.\\nOptionally surfaces flows that exist on the server but have no local file.\\n\\nExamples::\\n\\n    lfx status                          # scans flows/ in cwd, uses [defaults] env\\n    lfx status --env staging            # compare against staging\\n    lfx status --dir ./my-flows/        # specify a custom flows directory\\n    lfx status --env prod --remote-only # also show server flows not tracked locally\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport hashlib\\nimport json\\nfrom dataclasses import dataclass, field\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom uuid import UUID\\n\\nimport typer\\nfrom rich import box\\nfrom rich.console import Console\\nfrom rich.table import Table\\n\\nfrom lfx.cli.common import load_sdk\\n\\nconsole = Console()\\n\\n# ---------------------------------------------------------------------------\\n# Data model\\n# ---------------------------------------------------------------------------\\n\\n_STATUS_SYNCED = \\\"synced\\\"\\n_STATUS_AHEAD = \\\"ahead\\\"\\n_STATUS_BEHIND = \\\"behind\\\"\\n_STATUS_NEW = \\\"new\\\"\\n_STATUS_REMOTE_ONLY = \\\"remote-only\\\"\\n_STATUS_NO_ID = \\\"no-id\\\"\\n_STATUS_ERROR = \\\"error\\\"\\n\\n_STATUS_STYLE: dict[str, tuple[str, str, str]] = {\\n    _STATUS_SYNCED: (\\\"\u2713\\\", \\\"green\\\", \\\"synced\\\"),\\n    _STATUS_AHEAD: (\\\"\u2191\\\", \\\"yellow\\\", \\\"ahead\\\"),\\n    _STATUS_BEHIND: (\\\"\u2193\\\", \\\"yellow\\\", \\\"behind\\\"),\\n    _STATUS_NEW: (\\\"+\\\", \\\"cyan\\\", \\\"new\\\"),\\n    _STATUS_REMOTE_ONLY: (\\\"\u25cb\\\", \\\"blue\\\", \\\"remote only\\\"),\\n    _STATUS_NO_ID: (\\\"?\\\", \\\"dim\\\", \\\"no id\\\"),\\n    _STATUS_ERROR: (\\\"\u2717\\\", \\\"red\\\", \\\"error\\\"),\\n}\\n\\n\\n@dataclass\\nclass FlowStatus:\\n    name: str\\n    status: str\\n    path: Path | None = None\\n    flow_id: UUID | None = None\\n    detail: str = field(default=\\\"\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _load_sdk() -> tuple[object, object, object, type]:\\n    \\\"\\\"\\\"Return (normalize_flow, flow_to_json, Client, LangflowNotFoundError) from langflow_sdk.\\\"\\\"\\\"\\n    sdk = load_sdk(\\\"status\\\")\\n    from langflow_sdk.exceptions import LangflowNotFoundError\\n    from langflow_sdk.serialization import flow_to_json, normalize_flow\\n\\n    return normalize_flow, flow_to_json, sdk.Client, LangflowNotFoundError\\n\\n\\ndef _flow_hash(flow_dict: dict, normalize_flow: object, flow_to_json: object) -> str:\\n    \\\"\\\"\\\"Return a short deterministic hash of the normalized flow content.\\\"\\\"\\\"\\n    normalized = normalize_flow(flow_dict)  # type: ignore[operator]\\n    content = flow_to_json(normalized)  # type: ignore[operator]\\n    return hashlib.sha256(content.encode()).hexdigest()[:12]\\n\\n\\ndef _collect_files(dir_path: str | None, flow_paths: list[str]) -> list[Path]:\\n    \\\"\\\"\\\"Resolve the set of local flow files to examine.\\\"\\\"\\\"\\n    files: list[Path] = []\\n\\n    if dir_path:\\n        d = Path(dir_path)\\n        if not d.is_dir():\\n            msg = f\\\"Directory not found: {d}\\\"\\n            console.print(f\\\"[red]Error:[/red] {msg}\\\")\\n            raise typer.Exit(1)\\n        files.extend(sorted(d.glob(\\\"*.json\\\")))\\n    elif flow_paths:\\n        files.extend(Path(p) for p in flow_paths)\\n    else:\\n        # Default: flows/ in cwd\\n        default = Path.cwd() / \\\"flows\\\"\\n        if default.is_dir():\\n            files.extend(sorted(default.glob(\\\"*.json\\\")))\\n\\n    return files\\n\\n\\ndef _render_table(statuses: list[FlowStatus], env_label: str) -> None:\\n    table = Table(\\n        box=box.SIMPLE,\\n        show_header=True,\\n        header_style=\\\"bold\\\",\\n        title=f\\\"Flow status vs [bold]{env_label}[/bold]\\\",\\n        title_justify=\\\"left\\\",\\n    )\\n    table.add_column(\\\"Flow\\\", min_width=24)\\n    table.add_column(\\\"ID\\\", style=\\\"dim\\\", min_width=10)\\n    table.add_column(\\\"File\\\", style=\\\"dim\\\")\\n    table.add_column(\\\"Status\\\", min_width=14)\\n\\n    for s in statuses:\\n        icon, color, label = _STATUS_STYLE.get(s.status, (\\\"?\\\", \\\"dim\\\", s.status))\\n        detail_str = f\\\"  [dim]({s.detail})[/dim]\\\" if s.detail else \\\"\\\"\\n        id_str = str(s.flow_id)[:8] + \\\"\u2026\\\" if s.flow_id else \\\"\u2014\\\"\\n        file_str = s.path.name if s.path else \\\"\u2014\\\"\\n        table.add_row(\\n            s.name,\\n            id_str,\\n            file_str,\\n            f\\\"[{color}]{icon} {label}[/{color}]{detail_str}\\\",\\n        )\\n\\n    console.print(table)\\n\\n    # Summary line\\n    counts: dict[str, int] = {}\\n    for s in statuses:\\n        counts[s.status] = counts.get(s.status, 0) + 1\\n\\n    parts = []\\n    for status, (_, color, label) in _STATUS_STYLE.items():\\n        if counts.get(status):\\n            parts.append(f\\\"[{color}]{counts[status]} {label}[/{color}]\\\")\\n\\n    if parts:\\n        console.print(\\\"  \\\" + \\\"  \u00b7  \\\".join(parts))\\n        console.print()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Command\\n# ---------------------------------------------------------------------------\\n\\n\\ndef status_command(\\n    dir_path: str | None,\\n    flow_paths: list[str],\\n    env: str | None,\\n    environments_file: str | None,\\n    *,\\n    target: str | None = None,\\n    api_key: str | None = None,\\n    show_remote_only: bool,\\n) -> None:\\n    \\\"\\\"\\\"Compare local flow files against the remote instance and render a status table.\\\"\\\"\\\"\\n    normalize_flow, flow_to_json, client_cls, not_found_error = _load_sdk()\\n\\n    from lfx.config import ConfigError, resolve_environment\\n\\n    try:\\n        env_cfg = resolve_environment(\\n            env,\\n            target=target,\\n            api_key=api_key,\\n            environments_file=environments_file,\\n        )\\n    except ConfigError as exc:\\n        console.print(f\\\"[red]Error:[/red] {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n    try:\\n        client = client_cls(base_url=env_cfg.url, api_key=env_cfg.api_key)\\n    except Exception as exc:\\n        console.print(f\\\"[red]Error:[/red] Could not create client for {env_cfg.url!r}: {exc}\\\")\\n        raise typer.Exit(1) from exc\\n\\n    try:\\n        env_label = env_cfg.name\\n        local_files = _collect_files(dir_path, flow_paths)\\n\\n        if not local_files and not show_remote_only:\\n            console.print(\\\"[yellow]No flow files found.[/yellow] Use [bold]--dir[/bold] to specify a directory.\\\")\\n            raise typer.Exit(0)\\n\\n        statuses: list[FlowStatus] = []\\n        seen_ids: set[UUID] = set()\\n\\n        # ------------------------------------------------------------------ #\\n        # Check each local file                                               #\\n        # ------------------------------------------------------------------ #\\n        for path in local_files:\\n            if not path.exists():\\n                statuses.append(FlowStatus(name=path.name, status=_STATUS_ERROR, path=path, detail=\\\"file not found\\\"))\\n                continue\\n\\n            try:\\n                raw: dict = json.loads(path.read_text(encoding=\\\"utf-8\\\"))\\n            except (json.JSONDecodeError, OSError) as exc:\\n                statuses.append(FlowStatus(name=path.name, status=_STATUS_ERROR, path=path, detail=str(exc)))\\n                continue\\n\\n            name: str = raw.get(\\\"name\\\", path.stem)\\n            raw_id = raw.get(\\\"id\\\")\\n\\n            if not raw_id:\\n                statuses.append(\\n                    FlowStatus(\\n                        name=name,\\n                        status=_STATUS_NO_ID,\\n                        path=path,\\n                        detail=\\\"run lfx export --env <env> first to assign a stable id\\\",\\n                    )\\n                )\\n                continue\\n\\n            try:\\n                flow_id = UUID(str(raw_id))\\n            except ValueError:\\n                statuses.append(\\n                    FlowStatus(name=name, status=_STATUS_ERROR, path=path, detail=f\\\"invalid id: {raw_id!r}\\\")\\n                )\\n                continue\\n\\n            seen_ids.add(flow_id)\\n\\n            try:\\n                remote_flow = client.get_flow(flow_id)\\n            except not_found_error:\\n                statuses.append(FlowStatus(name=name, status=_STATUS_NEW, path=path, flow_id=flow_id))\\n                continue\\n            except Exception as exc:  # noqa: BLE001\\n                statuses.append(\\n                    FlowStatus(name=name, status=_STATUS_ERROR, path=path, flow_id=flow_id, detail=str(exc))\\n                )\\n                continue\\n\\n            local_hash = _flow_hash(raw, normalize_flow, flow_to_json)\\n            remote_hash = _flow_hash(remote_flow.model_dump(mode=\\\"json\\\"), normalize_flow, flow_to_json)\\n\\n            if local_hash == remote_hash:\\n                statuses.append(FlowStatus(name=name, status=_STATUS_SYNCED, path=path, flow_id=flow_id))\\n            else:\\n                remote_updated_at: datetime | None = remote_flow.updated_at\\n                local_mtime = datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc)\\n                if remote_updated_at and remote_updated_at.tzinfo is None:\\n                    remote_updated_at = remote_updated_at.replace(tzinfo=timezone.utc)\\n\\n                status = _STATUS_BEHIND if remote_updated_at and remote_updated_at > local_mtime else _STATUS_AHEAD\\n                statuses.append(FlowStatus(name=name, status=status, path=path, flow_id=flow_id))\\n\\n        # ------------------------------------------------------------------ #\\n        # Remote-only flows                                                   #\\n        # ------------------------------------------------------------------ #\\n        if show_remote_only:\\n            try:\\n                all_remote = client.list_flows(get_all=True)\\n                statuses.extend(\\n                    FlowStatus(\\n                        name=remote_flow.name,\\n                        status=_STATUS_REMOTE_ONLY,\\n                        flow_id=remote_flow.id,\\n                    )\\n                    for remote_flow in all_remote\\n                    if remote_flow.id not in seen_ids\\n                )\\n            except Exception as exc:  # noqa: BLE001\\n                console.print(f\\\"[yellow]Warning:[/yellow] Could not list remote flows: {exc}\\\")\\n    finally:\\n        with contextlib.suppress(OSError):\\n            client.close()\\n\\n    _render_table(statuses, env_label)\\n\\n    # Exit 1 when anything is out of sync so CI pipelines can detect drift\\n    not_clean = [s for s in statuses if s.status not in (_STATUS_SYNCED,)]\\n    if not_clean:\\n        raise typer.Exit(1)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/upgrade.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8aff20c07afeb767e570895910df09cdc6a183a29ae04d5a3488e4925c614f42\",\"content\":\"\\\"\\\"\\\"Implementation of `lfx upgrade <flow.json>`.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nimport typer\\n\\nfrom lfx.upgrade.applier import apply_safe_upgrades\\nfrom lfx.upgrade.checker import CompatibilityReport, build_registry_lookup, check_flow_compatibility\\nfrom lfx.utils.flow_envelope import merge_flow_envelope, split_flow_envelope\\n\\n# ASCII status markers (no Unicode glyphs) so output is safe on Windows cp1252 consoles,\\n# where non-ASCII symbols would raise UnicodeEncodeError or render as mojibake.\\n_STATUS_MARKERS = {\\n    \\\"ok\\\": \\\"[OK]\\\",\\n    \\\"outdated_safe\\\": \\\"[SAFE]\\\",\\n    \\\"outdated_breaking\\\": \\\"[BREAKING]\\\",\\n    \\\"blocked\\\": \\\"[BLOCKED]\\\",\\n}\\n\\n\\ndef load_registry_from_index() -> dict[str, Any]:\\n    \\\"\\\"\\\"Load the bundled component index and return a flat all_types_dict.\\n\\n    Raises:\\n        typer.Exit: if the bundled registry is empty or missing. Running the checker against\\n            an empty registry would silently classify *every* node as ``blocked``: a\\n            tooling-level failure masquerading as a flow-level problem. Fail loudly instead.\\n    \\\"\\\"\\\"\\n    from lfx.interface.components import _read_component_index\\n\\n    blob = _read_component_index(None)\\n    if not blob or \\\"entries\\\" not in blob:\\n        typer.echo(\\n            \\\"Error: the bundled component registry is empty or missing, so compatibility \\\"\\n            \\\"cannot be checked. Try reinstalling lfx (e.g. `pip install --force-reinstall lfx`).\\\",\\n            err=True,\\n        )\\n        raise typer.Exit(1)\\n    all_types: dict[str, Any] = {}\\n    for category, components in blob[\\\"entries\\\"]:\\n        all_types.setdefault(category, {}).update(components)\\n    return all_types\\n\\n\\ndef _print_report(report: CompatibilityReport) -> None:\\n    if report.is_clean:\\n        typer.echo(\\\"All components are up to date.\\\")\\n        return\\n\\n    for n in report.nodes:\\n        marker = _STATUS_MARKERS.get(n.status, \\\"[?]\\\")\\n        typer.echo(f\\\"  {marker} {n.display_name} ({n.component_type}) - id: {n.node_id}\\\")\\n\\n\\ndef upgrade_command(\\n    flow_path: Path,\\n    *,\\n    write: bool,\\n    strict: bool = False,\\n    registry: dict[str, Any] | None = None,\\n) -> None:\\n    if not flow_path.exists():\\n        typer.echo(f\\\"Error: flow file does not exist: {flow_path}\\\", err=True)\\n        raise typer.Exit(1)\\n\\n    try:\\n        flow_data = json.loads(flow_path.read_text(encoding=\\\"utf-8\\\"))\\n    except (json.JSONDecodeError, OSError) as e:\\n        typer.echo(f\\\"Error reading flow: {e}\\\", err=True)\\n        raise typer.Exit(1) from e\\n\\n    # Exported Langflow flows may have an outer envelope:\\n    # {\\\"name\\\": ..., \\\"data\\\": {\\\"nodes\\\": [...], \\\"edges\\\": [...]}}\\n    # Split it off so the checker sees the inner graph; the envelope is re-attached on write.\\n    try:\\n        outer_envelope, inner_data = split_flow_envelope(flow_data)\\n    except TypeError as e:\\n        typer.echo(f\\\"Error: {e}\\\", err=True)\\n        raise typer.Exit(1) from e\\n\\n    all_types = registry if registry is not None else load_registry_from_index()\\n    # Build the registry lookup once and reuse it for both the check and the apply step.\\n    registry_lookup = build_registry_lookup(all_types)\\n    report = check_flow_compatibility(inner_data, all_types, registry=registry_lookup)\\n\\n    _print_report(report)\\n\\n    wrote_safe = False\\n    if write and report.has_safe_updates:\\n        updated_inner, count = apply_safe_upgrades(\\n            inner_data, all_types, report, return_count=True, registry=registry_lookup\\n        )\\n        # Preserve the on-disk shape: keep the envelope (with metadata) when present, else stay flat.\\n        output = merge_flow_envelope(outer_envelope, updated_inner, wrap_bare=False)\\n        flow_path.write_text(json.dumps(output, indent=2, ensure_ascii=False), encoding=\\\"utf-8\\\")\\n        typer.echo(f\\\"Wrote {count} safe upgrade(s) to {flow_path}\\\")\\n        wrote_safe = True\\n\\n    if report.has_blocked or report.has_breaking:\\n        raise typer.Exit(1)\\n\\n    # --strict: any component left not up to date is drift. Safe upgrades that were just\\n    # written no longer count; pending (unwritten) safe upgrades do.\\n    if strict and report.has_safe_updates and not wrote_safe:\\n        typer.echo(\\n            \\\"Error: --strict: flow has pending safe upgrades. Re-run with --write to apply them.\\\",\\n            err=True,\\n        )\\n        raise typer.Exit(1)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/validate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"10d1d336405dfb9c8249033d3dcb4bbda888128063dde5c7e943adc99e5d2dbb\",\"content\":\"\\\"\\\"\\\"lfx validate -- structural and semantic validation of Langflow flow JSON.\\n\\nValidation levels (each level implies all levels below it):\\n\\n    Level 1 - structural\\n        The file parses as valid JSON and contains the expected top-level keys\\n        (``id``, ``name``, ``data``, ``data.nodes``, ``data.edges``).\\n        Also checks for orphaned nodes (no edges at all) and unused nodes\\n        (not reachable from any output node), and warns about version mismatches\\n        (nodes built with a different Langflow version than the one installed).\\n\\n    Level 2 - components\\n        Every node's ``data.type`` references a component type that exists in\\n        the lfx component registry.\\n\\n    Level 3 - edge types\\n        Connected ports carry compatible types (source output type must be\\n        assignable to target input type).\\n\\n    Level 4 - required inputs\\n        Every required input field on every component has a value or an\\n        incoming edge connected to it.  Also checks that password/secret fields\\n        have a value or a matching environment variable set.\\n\\nUse ``--level`` to select how deep to go, or ``--skip-*`` flags to opt out of\\nindividual checks while still running the others.\\n\\nPass ``--strict`` to treat warnings as errors (exit code 1).\\n\\nThis module is a thin wrapper that re-exports symbols from the\\n``lfx.cli.validation`` subpackage so that all existing imports continue\\nto work unchanged.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\n# Re-export everything from the validation subpackage.\\n# This keeps ``from lfx.cli.validate import ...`` working for all consumers\\n# (the CLI entry point in __main__.py, tests, etc.).\\nfrom lfx.cli.validation import (  # noqa: F401\\n    ValidationIssue,\\n    ValidationResult,\\n    _check_missing_credentials,\\n    _check_orphaned_nodes,\\n    _check_unused_nodes,\\n    _check_version_mismatch,\\n    _expand_paths,\\n    _get_lf_version,\\n    _node_display_name,\\n    validate_command,\\n    validate_flow_file,\\n)\\n\\n# Level constants (re-exported for backwards compatibility)\\nfrom lfx.cli.validation.core import (  # noqa: F401\\n    _LEVEL_COMPONENTS,\\n    _LEVEL_EDGE_TYPES,\\n    _LEVEL_REQUIRED_INPUTS,\\n    _LEVEL_STRUCTURAL,\\n)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/validation/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9eb03f9bd97c544e2d5fd8acc98a92385800e9cc88e7ce12a8917fe640215f78\",\"content\":\"\\\"\\\"\\\"Validation subpackage for lfx flow validation.\\n\\nRe-exports all public symbols so that existing imports from\\n``lfx.cli.validate`` (which delegates here) continue to work.\\n\\\"\\\"\\\"\\n\\nfrom lfx.cli.validation._env_validation import (\\n    is_valid_env_var_name,\\n    validate_global_variables_for_env,\\n)\\nfrom lfx.cli.validation.core import (\\n    LEVEL_COMPONENTS,\\n    LEVEL_EDGE_TYPES,\\n    LEVEL_REQUIRED_INPUTS,\\n    LEVEL_STRUCTURAL,\\n    ValidationIssue,\\n    ValidationResult,\\n    _expand_paths,\\n    _get_lf_version,\\n    _node_display_name,\\n    _render_result,\\n    validate_command,\\n    validate_flow_file,\\n)\\nfrom lfx.cli.validation.semantic import (\\n    _check_component_existence,\\n    _check_edge_type_compatibility,\\n    _check_missing_credentials,\\n    _check_required_inputs,\\n)\\nfrom lfx.cli.validation.structural import (\\n    _check_orphaned_nodes,\\n    _check_structural,\\n    _check_unused_nodes,\\n    _check_version_mismatch,\\n)\\n\\n__all__ = [\\n    \\\"LEVEL_COMPONENTS\\\",\\n    \\\"LEVEL_EDGE_TYPES\\\",\\n    \\\"LEVEL_REQUIRED_INPUTS\\\",\\n    \\\"LEVEL_STRUCTURAL\\\",\\n    \\\"ValidationIssue\\\",\\n    \\\"ValidationResult\\\",\\n    \\\"_check_component_existence\\\",\\n    \\\"_check_edge_type_compatibility\\\",\\n    \\\"_check_missing_credentials\\\",\\n    \\\"_check_orphaned_nodes\\\",\\n    \\\"_check_required_inputs\\\",\\n    \\\"_check_structural\\\",\\n    \\\"_check_unused_nodes\\\",\\n    \\\"_check_version_mismatch\\\",\\n    \\\"_expand_paths\\\",\\n    \\\"_get_lf_version\\\",\\n    \\\"_node_display_name\\\",\\n    \\\"_render_result\\\",\\n    \\\"is_valid_env_var_name\\\",\\n    \\\"validate_command\\\",\\n    \\\"validate_flow_file\\\",\\n    \\\"validate_global_variables_for_env\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/validation/_env_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"31efe90e254a38e06141bea57c7086cde8bc53c36cff2df1f5820f7c903591f8\",\"content\":\"\\\"\\\"\\\"Validation utilities for CLI commands.\\\"\\\"\\\"\\n\\nimport re\\nfrom typing import TYPE_CHECKING\\n\\nif TYPE_CHECKING:\\n    from lfx.graph.graph.base import Graph\\n\\n\\ndef is_valid_env_var_name(name: str) -> bool:\\n    \\\"\\\"\\\"Check if a string is a valid environment variable name.\\n\\n    Environment variable names should:\\n    - Start with a letter or underscore\\n    - Contain only letters, numbers, and underscores\\n    - Not contain spaces or special characters\\n\\n    Args:\\n        name: The string to validate\\n\\n    Returns:\\n        bool: True if valid, False otherwise\\n    \\\"\\\"\\\"\\n    # Pattern for valid environment variable names\\n    # Must start with letter or underscore, followed by letters, numbers, or underscores\\n    pattern = r\\\"^[a-zA-Z_][a-zA-Z0-9_]*$\\\"\\n    return bool(re.match(pattern, name))\\n\\n\\ndef validate_global_variables_for_env(graph: \\\"Graph\\\") -> list[str]:\\n    \\\"\\\"\\\"Validate that all global variables with load_from_db=True can be used as environment variables.\\n\\n    When the database is not available (noop mode), global variables with load_from_db=True\\n    are loaded from environment variables. This function checks that all such variables\\n    have names that are valid for environment variables.\\n\\n    Args:\\n        graph: The graph to validate\\n\\n    Returns:\\n        list[str]: List of error messages for invalid variable names\\n    \\\"\\\"\\\"\\n    from lfx.services.deps import get_settings_service\\n\\n    errors = []\\n    settings_service = get_settings_service()\\n\\n    # Check if we're in noop mode (no database)\\n    is_noop_mode = settings_service and settings_service.settings.use_noop_database\\n\\n    if not is_noop_mode:\\n        # If database is available, no need to validate\\n        return errors\\n\\n    # Check all vertices for fields with load_from_db=True\\n    for vertex in graph.vertices:\\n        # Get the fields that have load_from_db=True\\n        load_from_db_fields = getattr(vertex, \\\"load_from_db_fields\\\", [])\\n\\n        for field_name in load_from_db_fields:\\n            # Get the value of the field (which should be the variable name)\\n            field_value = vertex.params.get(field_name)\\n\\n            if field_value and isinstance(field_value, str) and not is_valid_env_var_name(field_value):\\n                errors.append(\\n                    f\\\"Component '{vertex.display_name}' (id: {vertex.id}) has field '{field_name}' \\\"\\n                    f\\\"with value '{field_value}' that contains invalid characters for an environment \\\"\\n                    f\\\"variable name. Environment variable names must start with a letter or underscore \\\"\\n                    f\\\"and contain only letters, numbers, and underscores (no spaces or special characters).\\\"\\n                )\\n\\n    return errors\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/src/lfx/cli/validation/core.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"097a72d4507a4c201005071442e3e15e0a2bfd76372a1959bcb87f2512879ef0\",\"content\":\"\\\"\\\"\\\"Core validation types, constants, and orchestrator for flow validation.\\n\\nContains the ValidationIssue and ValidationResult dataclasses, level constants,\\nthe main validate_flow_file orchestrator, and CLI rendering / path helpers.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport sys\\nfrom dataclasses import dataclass, field\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nimport typer\\nfrom rich.console import Console\\n\\nfrom lfx.cli.validation.semantic import (\\n    _check_component_existence,\\n    _check_edge_type_compatibility,\\n    _check_missing_credentials,\\n    _check_required_inputs,\\n)\\nfrom lfx.cli.validation.structural import (\\n    _check_orphaned_nodes,\\n    _check_structural,\\n    _check_unused_nodes,\\n    _check_version_mismatch,\\n)\\n\\nconsole = Console(stderr=True)\\nok_console = Console()\\n\\n# Validation level constants\\nLEVEL_STRUCTURAL = 1\\nLEVEL_COMPONENTS = 2\\nLEVEL_EDGE_TYPES = 3\\nLEVEL_REQUIRED_INPUTS = 4\\n\\n# Keep underscore-prefixed aliases for backwards compatibility\\n_LEVEL_STRUCTURAL = LEVEL_STRUCTURAL\\n_LEVEL_COMPONENTS = LEVEL_COMPONENTS\\n_LEVEL_EDGE_TYPES = LEVEL_EDGE_TYPES\\n_LEVEL_REQUIRED_INPUTS = LEVEL_REQUIRED_INPUTS\\n\\n\\n# ---------------------------------------------------------------------------\\n# Result types\\n# ---------------------------------------------------------------------------\\n\\n\\n@dataclass\\nclass ValidationIssue:\\n    level: int\\n    severity: str  # \\\"error\\\" | \\\"warning\\\"\\n    node_id: str | None\\n    node_name: str | None\\n    message: str\\n\\n\\n@dataclass\\nclass ValidationResult:\\n    path: Path\\n    issues: list[ValidationIssue] = field(default_factory=list)\\n\\n    @property\\n    def errors(self) -> list[ValidationIssue]:\\n        return [i for i in self.issues if i.severity == \\\"error\\\"]\\n\\n    @property\\n    def warnings(self) -> list[ValidationIssue]:\\n        return [i for i in self.issues if i.severity == \\\"warning\\\"]\\n\\n    @property\\n    def ok(self) -> bool:\\n        return not self.errors\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _node_display_name(node: dict[str, Any]) -> str | None:\\n    return node.get(\\\"data\\\", {}).get(\\\"node\\\", {}).get(\\\"display_name\\\") or node.get(\\\"data\\\", {}).get(\\\"id\\\") or node.get(\\\"id\\\")\\n\\n\\ndef _get_lf_version() -> str | None:\\n    \\\"\\\"\\\"Return the installed Langflow version string, or *None* if not installed.\\n\\n    Prefer the full distribution, then the version-aligned base distribution.\\n    \\\"\\\"\\\"\\n    from importlib.metadata import PackageNotFoundError, version\\n\\n    for pkg in (\\\"langflow\\\", \\\"langflow-nightly\\\", \\\"langflow-base\\\", \\\"langflow-base-nightly\\\"):\\n        try:\\n            return version(pkg)\\n        except PackageNotFoundError:\\n            continue\\n    return None\\n\\n\\n# ---------------------------------------------------------------------------\\n# Orchestrator\\n# ---------------------------------------------------------------------------\\n\\n\\ndef validate_flow_file(\\n    path: Path,\\n    *,\\n    level: int = LEVEL_REQUIRED_INPUTS,\\n    skip_components: bool = False,\\n    skip_edge_types: bool = False,\\n    skip_required_inputs: bool = False,\\n    skip_version_check: bool = False,\\n    skip_credentials: bool = False,\\n) -> ValidationResult:\\n    result = ValidationResult(path=path)\\n\\n    try:\\n        raw = path.read_text(encoding=\\\"utf-8\\\")\\n        flow: dict[str, Any] = json.loads(raw)\\n    except OSError as exc:\\n        result.issues.append(\\n            ValidationIssue(\\n                level=LEVEL_STRUCTURAL,\\n                severity=\\\"error\\\",\\n                node_id=None,\\n                node_name=None,\\n                message=f\\\"Cannot read file: {exc}\\\",\\n            )\\n        )\\n        return result\\n    except json.JSONDecodeError as exc:\\n        result.issues.append(\\n            ValidationIssue(\\n                level=LEVEL_STRUCTURAL,\\n                severity=\\\"error\\\",\\n                node_id=None,\\n                node_name=None,\\n                message=f\\\"Invalid JSON: {exc}\\\",\\n            )\\n        )\\n        return result\\n\\n    # Level 1 - structural (JSON shape + orphaned/unused node checks)\\n    can_continue = _check_structural(flow, result)\\n    if can_continue:\\n        _check_orphaned_nodes(flow, result)\\n        _check_unused_nodes(flow, result)\\n        # Extended: version mismatch / outdated components\\n        if not skip_version_check:\\n            _check_version_mismatch(flow, result)\\n    if not can_continue or level < LEVEL_COMPONENTS:\\n        return result\\n\\n    # Level 2 - component existence\\n    if not skip_components:\\n        _check_component_existence(flow, result)\\n    if level < LEVEL_EDGE_TYPES:\\n        return result\\n\\n    # Level 3 - edge type compatibility\\n    if not skip_edge_types:\\n        _check_edge_type_compatibility(flow, result)\\n    if level < LEVEL_REQUIRED_INPUTS:\\n        return result\\n\\n    # Level 4 - required inputs + extended: missing credentials\\n    if not skip_required_inputs:\\n        _check_required_inputs(flow, result)\\n    if not skip_credentials:\\n        _check_missing_credentials(flow, result)\\n\\n    return result\\n\\n\\n# ---------------------------------------------------------------------------\\n# CLI rendering and path helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _render_result(\\n    result: ValidationResult,\\n    *,\\n    index: int,\\n    total: int,\\n    verbose: bool,\\n    strict: bool = False,\\n) -> None:\\n    counter = f\\\"[dim][{index}/{total}][/dim] \\\" if total > 1 else \\\"\\\"\\n    label = f\\\"[bold]{result.path}[/bold]\\\"\\n    passes = result.ok and not (strict and result.warnings)\\n    if passes:\\n        ok_console.print(f\\\"{counter}[green]\\\\u2713[/green] {label}\\\")\\n    else:\\n        console.print(f\\\"{counter}[red]\\\\u2717[/red] {label}\\\")\\n\\n    show_issues = verbose or not passes\\n    if show_issues:\\n        for issue in result.issues:\\n            effective_severity = \\\"error\\\" if (strict and issue.severity == \\\"warning\\\") else issue.severity\\n            color = \\\"red\\\" if effective_severity == \\\"error\\\" else \\\"yellow\\\"\\n            loc = f\\\" [{issue.node_name or issue.node_id}]\\\" if (issue.node_id or issue.node_name) else \\\"\\\"\\n            console.print(f\\\"  [{color}][L{issue.level} {effective_severity.upper()}][/{color}]{loc} {issue.message}\\\")\\n\\n\\ndef _expand_paths(raw_paths: list[str]) -> list[Path]:\\n    \\\"\\\"\\\"Expand each entry to a list of .json files.\\n\\n    * If the path is a directory, collect every ``*.json`` file recursively.\\n    * If the path is a file, return it as-is.\\n    * If the path does not exist, print an error and exit 2.\\n    \\\"\\\"\\\"\\n    paths: list[Path] = []\\n    for raw in raw_paths:\\n        p = Path(raw)\\n        if not p.exists():\\n            console.print(f\\\"[red]Error:[/red] Path not found: {p}\\\")\\n            raise typer.Exit(2)\\n        if p.is_dir():\\n            found = sorted(p.rglob(\\\"*.json\\\"))\\n            if not found:\\n                console.print(f\\\"[yellow]Warning:[/yellow] No .json files found in {p}\\\")\\n            paths.extend(found)\\n        else:\\n            paths.append(p)\\n    return paths\\n\\n\\n_DEFAULT_FLOWS_DIR = \\\"flows\\\"\\n\\n\\ndef validate_command(\\n    flow_paths: list[str],\\n    level: int,\\n    *,\\n    skip_components: bool,\\n    skip_edge_types: bool,\\n    skip_required_inputs: bool,\\n    skip_version_check: bool,\\n    skip_credentials: bool,\\n    strict: bool,\\n    verbose: bool,\\n    output_format: str,\\n) -> None:\\n    if not flow_paths:\\n        flow_paths = [_DEFAULT_FLOWS_DIR]\\n\\n    paths = _expand_paths(flow_paths)\\n\\n    if not paths:\\n        console.print(\\\"[yellow]No flow files to validate.[/yellow]\\\")\\n        raise typer.Exit(0)\\n\\n    results: list[ValidationResult] = []\\n    for i, p in enumerate(paths, start=1):\\n        result = validate_flow_file(\\n            p,\\n            level=level,\\n            skip_components=skip_components,\\n            skip_edge_types=skip_edge_types,\\n            skip_required_inputs=skip_required_inputs,\\n            skip_version_check=skip_version_check,\\n            skip_credentials=skip_credentials,\\n        )\\n        results.append(result)\\n        if output_format != \\\"json\\\":\\n            _render_result(result, index=i, total=len(paths), verbose=verbose, strict=strict)\\n\\n    if output_format == \\\"json\\\":\\n        import json as _json\\n\\n        out = [\\n            {\\n                \\\"path\\\": str(r.path),\\n                \\\"ok\\\": r.ok if not strict else (not r.errors and not r.warnings),\\n                \\\"issues\\\": [\\n                    {\\n                        \\\"level\\\": i.level,\\n                        \\\"severity\\\": i.severity,\\n                        \\\"node_id\\\": i.node_id,\\n                        \\\"node_name\\\": i.node_name,\\n                        \\\"message\\\": i.message,\\n                    }\\n            ";
